def set_process_name(name):
    """The name System Monitor, top and htop show for this process: "Player-17", not "python3".
    Linux keeps up to 15 characters of it (the kernel's comm). The command line is renamed
    too when the setproctitle module is around (some monitors read that instead)."""
    try:
        import ctypes
        libc = ctypes.CDLL(None, use_errno=True)
        libc.prctl(15, ctypes.c_char_p(name.encode("utf-8")[:15]), 0, 0, 0)   # 15 = PR_SET_NAME
    except Exception:
        pass
    try:
        import setproctitle
        setproctitle.setproctitle(name)
    except Exception:
        pass
