EXTRA_SITE = [d for d in (os.environ.get("PLAYER_SITE") or os.environ.get("PLYER_SITE", "")).split(os.pathsep) if d and os.path.isdir(d)]
sys.path[:0] = [d for d in EXTRA_SITE if d not in sys.path]


def with_site(code):
    """Python code for a helper process, with the app's own package folders on its path."""
    return f"import sys\nsys.path[:0] = {EXTRA_SITE!r}\n{code}" if EXTRA_SITE else code


