def readable_on(background):
    """White or near-black text, whichever reads better on this background."""
    color = background.lstrip("#")
    try:
        r, g, b = (int(color[i:i + 2], 16) / 255 for i in (0, 2, 4))
    except ValueError:
        return "#ffffff"

    def lin(c):
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4

    light = 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)
    # contrast with white vs contrast with black: take the bigger one
    return "#ffffff" if (1.05 / (light + 0.05)) >= ((light + 0.05) / 0.05) else "#111111"


def glow_on(key):
    """The glow color of `key` when it is switched on (not fully transparent), else None."""
    value = COLORS.get(key, "")
    return value if len(value) == 7 or (len(value) == 9 and value[7:9].lower() != "00") else None


def glow_css():
    """The glow part of the stylesheet: only for the glows that are switched on."""
    rules = {
        "glow_text": "label.track, .main label, headerbar label {{ text-shadow: 0 0 7px {g}; }}\n"
                     "image {{ -gtk-icon-shadow: 0 0 6px {g}; }}\n",
        "glow_title": ".title, .prefs-title, .prefs-head {{ text-shadow: 0 0 9px {g}, 0 0 2px {g}; }}\n",
        "glow_lines": ".pinkline, .search-shell, .prefs-line, popover > contents, .colors-note "
                      "{{ box-shadow: 0 0 9px {g}; }}\n",
        "glow_eq_frame": ".peq-frame, .modules-frame, .module-card {{ box-shadow: 0 0 10px {g}; }}\n",
        "glow_eq_fader": "scale.eq highlight, scale.lim highlight {{ box-shadow: 0 0 8px {g}; }}\n",
        "glow_eq_text": ".eq-label {{ text-shadow: 0 0 7px {g}; }}\n",
    }
    return "".join(rule.format(g=glow_on(key)) for key, rule in rules.items() if glow_on(key))


def _hex_rgba(value):
    value = (value or "#000000").lstrip("#")
    r, g, b = (int(value[i:i + 2], 16) for i in (0, 2, 4))
    a = int(value[6:8], 16) / 255 if len(value) >= 8 else 1.0
    return r, g, b, a


def dense_frame_color(frame, bg):
    """The frame line is drawn twice on the same spot, so its round corners are as dense as its
    straight edges (there the edge pixels are only partly covered, the black showed through and
    the corner looked thinner). Twice must not change the straight edges, so each pass gets:
      - background solid: the frame already mixed over it, solid (twice solid = the same);
      - background see-through: an opacity that gives the frame's own one when doubled."""
    r, g, b, a = _hex_rgba(frame)
    br, bg_, bb, ba = _hex_rgba(bg)
    if ba >= 0.999:
        mix = lambda c, under: round(c * a + under * (1 - a))
        return f"rgb({mix(r, br)}, {mix(g, bg_)}, {mix(b, bb)})"
    return f"rgba({r}, {g}, {b}, {1 - math.sqrt(max(0.0, 1 - a)):.4f})"


def frame_css():
    """The thin frame around every window, when it is on: an outline that follows the window's
    own round corners (none when maximized or full screen: nothing to frame there). The same line
    once more as an inner shadow makes the round corners dense (see dense_frame_color)."""
    if not FRAME_ON[0]:
        return ""
    color = dense_frame_color(COLORS["frame"], COLORS["bg"])
    return (f"window:not(.maximized):not(.fullscreen) {{ outline: 1px solid {color}; "
            f"outline-offset: -1px; box-shadow: inset 0 0 0 1px {color}; }}\n")


def menu_css():
    """Wayland only. There a menu is its own small surface, and GTK tells the system "this
    rectangle is solid" whenever the menu's background is fully solid. While the menu fades in
    or out it is not solid, the system skipped what lies under it, and that was the ghost copy
    and the dark squares. A background a hair short of solid (254 of 255, the eye cannot tell)
    stops GTK from saying so, and the menu then fades as cleanly as on X11."""
    if not _on_wayland() or _plain_menus():
        return ""
    return ("popover > contents, dropdown popover > contents "
            f"{{ background-color: alpha({COLORS['bg']}, 0.996); }}\n")


def apply_colors():
    if _css_provider is not None:
        _css_provider.load_from_string(CSS.format(**COLORS, readable=readable_on(COLORS["bg"])) + glow_css()
                                       + frame_css() + menu_css())


def redraw_all(widget):
    """Ask every custom-drawn widget (knobs, scope) to repaint after a color change."""
    widget.queue_draw()
    child = widget.get_first_child()
    while child is not None:
        redraw_all(child)
        child = child.get_next_sibling()

