tempo = aubio.tempo('default', WIN, HOP, RATE)
beats = []
for i in range(0, len(audio) - HOP, HOP):
    if tempo(audio[i:i + HOP]):
        beats.append(tempo.get_last_s())
bpm = 0.0
if len(beats) > 8:
    gaps = np.diff(np.array(beats))
    gaps = gaps[(gaps > 0.25) & (gaps < 1.5)]
    if len(gaps):
        bpm = 60.0 / float(np.median(gaps))
