    class PlayerLimiterElement(GstBase.BaseTransform):
        """GStreamer element around the C limiter. Settings are GObject properties in dB / ms."""

        __gstmetadata__ = ("Player-17 Limiter", "Filter/Effect/Audio", "Lookahead limiter", "Player-17")
        __gsttemplates__ = (
            Gst.PadTemplate.new("src", Gst.PadDirection.SRC, Gst.PadPresence.ALWAYS, _P17_CAPS),
            Gst.PadTemplate.new("sink", Gst.PadDirection.SINK, Gst.PadPresence.ALWAYS, _P17_CAPS),
        )
        __gproperties__ = {
            **{name: (float, name, name, low, high, default, _RW) for name, low, high, default in P17LIM_PARAMS},
            "boost": (bool, "boost", "keep the loudness when the threshold goes down", True, _RW),
            "enabled": (bool, "enabled", "the limiter on / off", True, _RW),
            "gain-reduction": (float, "gain-reduction", "dB the limiter turns down now", -96.0, 0.0, 0.0,
                               GObject.ParamFlags.READABLE),
        }

        def __init__(self):
            super().__init__()
            self._values = {name: default for name, _l, _h, default in P17LIM_PARAMS}
            self._values.update({"boost": True, "enabled": True})
            self._state = None
            self._rate = 44100
            self._dirty = True

        def do_get_property(self, prop):
            if prop.name == "gain-reduction":
                return float(P17DSP.p17lim_gr(self._state)) if self._state else 0.0
            return self._values[prop.name]

        def do_set_property(self, prop, value):
            self._values[prop.name] = value
            self._dirty = True   # put on the limiter in the sound thread, before the next block

        def _apply(self):
            v = self._values
            P17DSP.p17lim_set(self._state, v["threshold-db"], v["input-db"], v["output-db"], v["attack-ms"],
                              v["release-ms"], v["lookahead-ms"], v["knee-db"], v["density"] / 100.0,
                              int(v["boost"]), int(v["enabled"]))
            P17DSP.p17lim_shape(self._state, v["smooth"] / 100.0, v["auto-level"] / 100.0,
                                v["auto-attack-ms"], v["auto-release-ms"])
            self._dirty = False

        def do_set_caps(self, incaps, outcaps):
            ok, rate = incaps.get_structure(0).get_int("rate")
            rate = rate if ok and rate > 0 else 44100
            if self._state is None or rate != self._rate:
                if self._state:
                    P17DSP.p17lim_free(self._state)
                self._rate = rate
                self._state = P17DSP.p17lim_new(float(rate))
                self._dirty = True
            return True

        def do_stop(self):
            if self._state:
                P17DSP.p17lim_reset(self._state)
            return True

        def scope_take(self, most=2048):
            """The scope points since the last call: [(in, out, gain), ...] (linear; in = after
            the input gain, out = what leaves, gain = all the limiter took away)."""
            state = self._state
            if not state:
                return []
            buf = getattr(self, "_scope_buf", None)
            if buf is None or len(buf) < most * 3:
                buf = self._scope_buf = (_ctypes.c_float * (most * 3))()
            now = _ctypes.c_longlong(0)
            n = P17DSP.p17lim_scope(state, getattr(self, "_scope_since", 0), buf, most, _ctypes.byref(now))
            self._scope_since = now.value
            flat = buf[:n * 3]
            return list(zip(flat[0::3], flat[1::3], flat[2::3]))

        def do_transform_ip(self, buf):
            if not self._state:
                return Gst.FlowReturn.OK
            if self._dirty:
                self._apply()
            dsp_in_place(buf, P17DSP.p17lim_process, self._state)
            return Gst.FlowReturn.OK

