            for i in range(16):
                if i < len(bands) and bands[i]:
                    kind, freq, gain, q, poles = bands[i]
                    P17DSP.p17eq_set_band(self._state, i, int(kind), float(freq), float(gain), float(q), int(poles))
                else:
                    P17DSP.p17eq_set_band(self._state, i, 0, 1000.0, 0.0, 1.0, 2)
            P17DSP.p17eq_set_pre(self._state, pre)

