    class PlayerOttElement(GstBase.BaseTransform):
        """GStreamer element around the C OTT. "config": the module's settings as JSON
        (clean_ott_settings). Changes reach the C code in the sound thread and glide there.
        meters(): [(loudest level dB, gain change dB)] per band, for the display."""

        __gstmetadata__ = ("Player-17 OTT", "Filter/Effect/Audio", "Multiband up / down compression", "Player-17")
        __gsttemplates__ = (
            Gst.PadTemplate.new("src", Gst.PadDirection.SRC, Gst.PadPresence.ALWAYS, _P17_CAPS),
            Gst.PadTemplate.new("sink", Gst.PadDirection.SINK, Gst.PadPresence.ALWAYS, _P17_CAPS),
        )
        __gproperties__ = {"config": (str, "config", "the settings as JSON", "{}", _RW),
                           "active": (bool, "active", "on / off (fades, never leaves the chain)", True, _RW)}

        def __init__(self):
            super().__init__()
            self._text = "{}"
            self._config = clean_ott_settings({})
            self._active, self._mixv = True, 1.0
            self._state = None
            self._rate = 44100
            self._dirty = True
            self._lock = threading.Lock()

        def do_get_property(self, prop):
            return self._active if prop.name == "active" else self._text

        def do_set_property(self, prop, value):
            if prop.name == "active":
                self._active = bool(value)
                return
            try:
                config = clean_ott_settings(json.loads(value or "{}"))
            except ValueError:
                return
            with self._lock:
                self._text, self._config, self._dirty = value, config, True

        def _apply(self):
            with self._lock:
                ott, self._dirty = self._config, False
            xs, gains, dth, uth, att, rel = ott_bands(ott)
            n = len(gains)
            arr = lambda values: (_ctypes.c_float * max(1, len(values)))(*(values or [1000.0]))
            hard = ott["mode"] == "hard"   # the band knobs rule: the global ones step aside
            # Prism: one limit at the end. Hard Prism: every band its own (the end one stays at 0 dB).
            limit_db = 0.0 if hard else -OTT_LIMIT_DB * (1.0 - float(ott.get("limit", 1.0)))
            level = float(ott.get("out_level", 1.0))
            out_db = 20 * math.log10(level) if level > 1e-6 else -120.0   # Out: 0 = silent, 1 = full
            in_db = 0.0 if hard else (ott["in"] - 0.5) * 2 * OTT_IO_DB      # Hard Prism: the bands' own In
            P17DSP.p17ott_set_global(self._state, 1.0 if hard else ott["depth"], in_db, out_db,
                                     1.0 if hard else ott["up"], 1.0 if hard else ott["down"], limit_db,
                                     60.0 if hard else lim_release_ms(ott.get("lim_rel", 0.5)))
            P17DSP.p17ott_set_bands(self._state, n, arr(xs), arr(gains), arr(dth), arr(uth), arr(att), arr(rel),
                                    0.5 if hard else ott["time"])
            depth, up, down, limits, band_in, releases = ott_amounts(ott)
            P17DSP.p17ott_set_amounts(self._state, n, arr(depth), arr(up), arr(down), arr(band_in))
            P17DSP.p17ott_set_band_limits(self._state, n, arr(limits), arr(releases))
            a = ott["amounts"]
            P17DSP.p17ott_set_audible(self._state, n, arr(band_audible(a["mute"][:n], a["solo"][:n])))

        def meters(self):
            state = self._state
            if not state:
                return []
            return [(float(P17DSP.p17ott_level(state, i)), float(P17DSP.p17ott_gr(state, i)))
                    for i in range(int(P17DSP.p17ott_bands(state)))]

        def limit_gr(self):
            """dB the end limiter (the red line) takes away right now."""
            return float(P17DSP.p17ott_limit_gr(self._state)) if self._state else 0.0

        def band_limit_gr(self):
            """dB every band's own limiter takes away right now (Hard Prism)."""
            state = self._state
            if not state:
                return []
            return [float(P17DSP.p17ott_band_limit_gr(state, i)) for i in range(int(P17DSP.p17ott_bands(state)))]

        def do_set_caps(self, incaps, outcaps):
            ok, rate = incaps.get_structure(0).get_int("rate")
            rate = rate if ok and rate > 0 else 44100
            if self._state is None or rate != self._rate:
                if self._state:
                    P17DSP.p17ott_free(self._state)
                self._rate = rate
                self._state = P17DSP.p17ott_new(float(rate))
                self._dirty = True
            return True

        def do_stop(self):
            if self._state:
                P17DSP.p17ott_reset(self._state)
            return True

        def do_transform_ip(self, buf):
            if not self._state:
                return Gst.FlowReturn.OK
            if self._dirty:
                self._apply()
            dsp_switchable(self, buf, P17DSP.p17ott_process, self._state)
            return Gst.FlowReturn.OK

