def have_element(name):
    return Gst.ElementFactory.find(name) is not None


class EqUnit:
    """One Prism EQ 17 module in the sound chain: points (bells, shelves, cuts), Bass, Crunch,
    Reverb. Its settings are kept here, so a new chain gets the same sound; bind() finds its
    elements in a freshly built chain. Every element name ends with the module id, so any
    number of these can sit in one chain."""

    kind = "eq"

    def __init__(self, uid, player):
        self.uid = uid
        self.player = player
        self.points = peq_default_points()
        self.bass_db = 0.0
        self.reverb_level = 0.0
        self.reverb_preset = None
        self.crunch = 0.0
        self.spectrum = None       # latest analyser reading (dB per band)
        self.spectrum_on = False
        self.eq_on = True          # False: the module is not in the sound (the picture fades)
        self._crunch_pending = 0
        self.clear()

    def clear(self):
        """Forget the elements (the chain is being built again)."""
        self.eq = self.bass = self.pre = self.limiter = self.reverb = None
        self.crunch_eq = self.crunch_in = self.crunch_in2 = self.crunch_out = None
        self.crunch_el = None   # the own C Crunch, when it is there
        self.hpf = self.lpf = self.spec = None
        self._eq_sent = {}

    @property
    def playing(self):
        return self.player.playing

    def name(self, what):
        return f"{what}_{self.uid}"

    def copy_state(self, other):
        self.points = [dict(p) for p in other.points]
        self.bass_db, self.reverb_level = other.bass_db, other.reverb_level
        self.reverb_preset, self.crunch = other.reverb_preset, other.crunch

    def _wanted_cuts(self):
        kinds = {p["type"] for p in self.points}
        return "lowcut" in kinds, "highcut" in kinds

    def structure(self):
        """What this module needs in the chain; a change means a new chain.
        With the own equalizer, cuts come and go inside it: no new chain for them."""
        cuts = () if HAVE_P17_EQ else self._wanted_cuts()
        # The own Crunch always sits in the chain: switching it on / off needs no new chain.
        return (self.uid, "eq", cuts, False if HAVE_P17_CRUNCH else self.crunch > CRUNCH_ON)

    def parts(self):
        n = self.name
        if HAVE_P17_EQ:
            # The own equalizer: every band, the cuts, Bass and the headroom in one smooth stage.
            parts = ["audioconvert", "audio/x-raw,format=F32LE,channels=2,layout=interleaved",
                     f"p17eq name={n('eq')}"]
            if HAVE_P17_LIMITER:
                # Bands pushed all the way up: the sound is limited right here (-0.1 dBFS, looks
                # 1.5 ms ahead) instead of cracking in Crunch, the reverb or a plugin after it.
                parts.append(f"p17limiter name={n('eqlim')} threshold-db=0 boost=false attack-ms=1.5 "
                             "release-ms=60 lookahead-ms=1.5 knee-db=1 density=0")
        elif have_element("equalizer-nbands"):
            # 32-bit float with a "headroom" volume before the filters, so that boosting a band
            # never pushes the signal over the limit (that was the crackling).
            parts = ["audioconvert", "audio/x-raw,format=F32LE", f"volume name={n('pre')}",
                     f"equalizer-nbands name={n('eq')} num-bands={PEQ_MAX_BANDS}",
                     f"equalizer-nbands name={n('bass')} num-bands=1"]
            low, high = self._wanted_cuts()  # steep cut filters, only while such a point exists
            if low and have_element("audiocheblimit"):
                parts.append(f"audiocheblimit name={n('hpf')} mode=high-pass type=1 poles=4")
            if high and have_element("audiocheblimit"):
                parts.append(f"audiocheblimit name={n('lpf')} mode=low-pass type=1 poles=4")
        else:
            return []
        if have_element("spectrum"):  # the live picture behind the curve
            parts.append(f"spectrum name={n('spec')} bands={SPECTRUM_BANDS} interval=66000000 threshold=-90 "
                         "post-messages=false message-phase=false")
        if HAVE_P17_CRUNCH:
            parts += ["audioconvert", "audio/x-raw,format=F32LE,channels=2,layout=interleaved",
                      f"p17crunch name={n('crunch')}"]
        elif self.crunch > CRUNCH_ON:
            parts += [
                f"equalizer-nbands name={n('crunch_eq')} num-bands=1",
                # GStreamer's volume goes up to 10x (+20 dB) only: the +24 dB drive is split in two
                f"volume name={n('crunch_in')}", f"volume name={n('crunch_in2')}",
                "audioconvert", "audio/x-raw,format=S16LE",    # the hard clip
                "audioconvert", "audio/x-raw,format=F32LE", f"volume name={n('crunch_out')}",
            ]
        if have_element("rglimiter") and not self.player.lv2_name:
            parts.append(f"rglimiter name={n('limiter')}")  # built-in soft limiter (no limiter plugin)
        parts.append("audioconvert")
        if have_element("freeverb"):
            # Stays in float: going down to 16 bit here could clip a boosted equalizer.
            parts += ["audio/x-raw,channels=2", f"freeverb name={n('reverb')}", "audioconvert"]
        return parts

    def bind(self, fx, owners):
        get = lambda what: fx.get_by_name(self.name(what))
        self.eq, self.bass, self.pre = get("eq"), get("bass"), get("pre")
        self.limiter, self.reverb = get("limiter"), get("reverb")
        self.crunch_eq, self.crunch_in, self.crunch_out = get("crunch_eq"), get("crunch_in"), get("crunch_out")
        self.crunch_in2 = get("crunch_in2")
        self.crunch_el = get("crunch")
        self.hpf, self.lpf, self.spec = get("hpf"), get("lpf"), get("spec")
        self._eq_sent = {}
        for element, freq in ((self.crunch_eq, 90.0), (self.bass, 120.0)):
            if element is None:
                continue
            band = element.get_child_by_index(0)
            try:
                Gst.util_set_object_arg(band, "type", "low-shelf")
            except Exception:
                pass  # older GStreamer: a normal peak band at the same place
            band.set_property("freq", freq)
            band.set_property("bandwidth", freq)
        if self.reverb is not None:
            self.reverb.set_property("room-size", 0.7)
            self.reverb.set_property("damping", 0.4)
        if self.spec is not None:
            self.spec.set_property("post-messages", self.spectrum_on)
            owners[self.name("spec")] = self

    def apply(self):
        """Every setting onto the (new) elements."""
        self._put_eq()
        self._put_reverb()
        if self.reverb_preset:
            self.set_reverb_preset(self.reverb_preset)
        self._put_crunch()
        self._put_active()

    def _put_active(self):
        """Switched off in the Plugins window: everything of this module fades out but stays
        in the chain (no new chain: the radio does not reconnect, a track does not jump)."""
        if self.eq is not None and self.own_eq():
            self.eq.set_property("active", bool(self.eq_on))

    # --- the equalizer ---
    def update_headroom(self):
        """Turn the signal down a little when bands are boosted, and limit the peaks softly.
        Only a part of the boost is taken off, so the volume does not jump while you move
        a fader; the soft limiter protects from the rest."""
        boosts = [0.0]
        for p in self.points:
            if p["type"] in ("lowcut", "highcut") or p["gain"] <= 0:
                continue
            # Low frequencies carry most of the energy: their boost counts most.
            pos = (math.log10(p["freq"]) - math.log10(60)) / (math.log10(10000) - math.log10(60))
            weight = 0.8 - 0.7 * max(0.0, min(1.0, pos))
            boosts.append(weight * p["gain"])
        cut = max(boosts) + BASS_HEADROOM_WEIGHT * max(0.0, self.bass_db)
        if self.own_eq():
            self.eq.set_property("pre-db", float(-cut))  # glides inside the equalizer
        elif self.pre is not None:
            self.pre.set_property("volume", 10 ** (-cut / 20))
        if self.limiter is not None:
            self.limiter.set_property("enabled", cut > 0.0)

    def own_eq(self):
        return self.eq is not None and HAVE_P17_EQ and self.eq.get_factory() is not None \
            and self.eq.get_factory().get_name() == "p17eq"

    def _put_own_eq(self):
        """All points, the cuts and Bass as the bands of the own equalizer."""
        bands = []
        for p in self.points[:PEQ_MAX_BANDS + 2]:  # up to 12 bells / shelves + the two cuts
            kind = P17EQ_TYPES.get(p["type"], 1)
            bands.append([kind, round(float(p["freq"]), 3), round(float(p["gain"]), 3),
                          round(float(p["q"]), 4), peq_cut_poles(p["q"])])
        bands += [None] * (15 - len(bands))
        bands.append([P17EQ_TYPES["lowshelf"], 120.0, round(float(self.bass_db), 3), 0.7, 2])  # Bass knob
        text = json.dumps(bands)
        if self._eq_sent.get("bands") != text:
            self._eq_sent["bands"] = text
            self.eq.set_property("bands", text)
        self.update_headroom()

    def _put_eq(self):
        if self.own_eq():
            self._put_own_eq()
            return
        if self.eq is not None:
            # Only what really changed is sent: while a point is dragged that is one or two
            # values instead of forty, so the sound thread is never held up by the window.
            sent = self._eq_sent

            def put(i, band, prop, value):
                if sent.get((i, prop)) != value:
                    sent[(i, prop)] = value
                    if prop == "type":
                        try:
                            Gst.util_set_object_arg(band, "type", value)
                        except Exception:
                            pass
                    else:
                        band.set_property(prop, value)

            bands = [p for p in self.points if p["type"] in PEQ_GST_TYPE][:PEQ_MAX_BANDS]
            for i in range(PEQ_MAX_BANDS):
                band = self.eq.get_child_by_index(i)
                if i < len(bands):
                    p = bands[i]
                    put(i, band, "type", PEQ_GST_TYPE[p["type"]])
                    put(i, band, "freq", float(p["freq"]))
                    put(i, band, "bandwidth", float(max(1.0, p["freq"] / max(0.1, p["q"]))))
                    put(i, band, "gain", float(p["gain"]))
                else:  # an unused band: flat, it lets everything through unchanged
                    put(i, band, "gain", 0.0)
        for element, kind in ((self.hpf, "lowcut"), (self.lpf, "highcut")):
            point = next((p for p in self.points if p["type"] == kind), None)
            if element is not None and point is not None:
                element.set_property("cutoff", float(point["freq"]))
                element.set_property("poles", peq_cut_poles(point["q"]))
        if self.bass is not None:
            self.bass.get_child_by_index(0).set_property("gain", float(self.bass_db))
        self.update_headroom()

    def set_points(self, points):
        """Bells and shelves change at once; adding or removing a cut needs a new chain."""
        self.points = [peq_clean(p) for p in points]
        if not self.player.rebuild_if_needed():
            self._put_eq()

    def set_spectrum(self, on):
        self.spectrum_on = bool(on)
        if self.spec is not None:
            self.spec.set_property("post-messages", self.spectrum_on)

    def set_bass_db(self, gain_db):
        self.bass_db = float(gain_db)
        if self.own_eq():
            self._put_own_eq()
            return
        if self.bass is not None:
            self.bass.get_child_by_index(0).set_property("gain", self.bass_db)
        self.update_headroom()

    # --- Crunch and reverb ---
    def _put_crunch(self):
        drive = max(0.0, min(1.0, self.crunch)) if self.eq_on else 0.0
        if self.crunch_el is not None:   # the own Crunch: one value, it glides by itself
            self.crunch_el.set_property("amount", drive if drive > CRUNCH_ON else 0.0)
            return
        if self.crunch_eq is not None:
            self.crunch_eq.get_child_by_index(0).set_property("gain", CRUNCH_BASS_DB * drive)
        # Half of the drive on each of the two volume elements (each at most +12 dB, under
        # GStreamer's limit of 10x). One element asked for more than 10x silently kept 1.0:
        # a fresh chain (new browser, a second equalizer) then sounded quieter and clean
        # until the knob was moved.
        half = 10 ** (CRUNCH_DRIVE_DB * drive / 40)
        for element in (self.crunch_in, self.crunch_in2):
            if element is not None:
                element.set_property("volume", half)
        if self.crunch_out is not None:
            self.crunch_out.set_property("volume", 10 ** (CRUNCH_MAKEUP_DB * drive / 20))

    def set_crunch(self, value):
        """0 = clean (the stage is not even in the chain), 1 = fully blown bass."""
        self.crunch = float(value)
        if self.player._structure() != self.player._built_structure:
            # Switched on or off: the chain gets / loses the clip stage. Once per move of the
            # knob, not on every pixel around zero.
            if not self._crunch_pending:
                def rebuild():
                    self._crunch_pending = 0
                    if not self.player.rebuild_if_needed():
                        self._put_crunch()
                    return False

                self._crunch_pending = GLib.timeout_add(150, rebuild)
        else:
            self._put_crunch()

    def _put_reverb(self):
        if self.reverb is not None:
            self.reverb.set_property("level", float(self.reverb_level) if self.eq_on else 0.0)

    def set_reverb(self, value):
        self.reverb_level = float(value)
        self._put_reverb()

    def set_reverb_preset(self, name):
        self.reverb_preset = name
        if self.reverb is None:
            return
        for preset, size, damping in REVERB_PRESETS:
            if preset == name:
                self.reverb.set_property("room-size", float(size))
                self.reverb.set_property("damping", float(damping))


class LimiterUnit:
    """One Limiter 17 module in the sound chain (the own limiter, or an installed LV2 one),
    with a level meter before and after it for the scope."""

    kind = "limiter"

    def __init__(self, uid, player):
        self.uid = uid
        self.player = player
        self.limiter_values = {}
        self.levels = deque(maxlen=SCOPE_COLUMNS)  # (level before, level after, gain reduction) in dB
        self.scope_range = 24.0
        self._last_in = SCOPE_FLOOR_DB
        self.eq_on = True
        self.lv2 = None

    def clear(self):
        self.lv2 = None

    @property
    def playing(self):
        return self.player.playing

    @property
    def lv2_name(self):
        return self.player.lv2_name

    def name(self, what):
        return f"{what}_{self.uid}"

    def copy_state(self, other):
        self.limiter_values = dict(other.limiter_values)

    def structure(self):
        return (self.uid, "limiter")

    def parts(self):
        if not self.lv2_name:
            return []
        meter_in = [f"level name={self.name('lvlin')} interval=33000000"] if have_element("level") else []
        meter_out = [f"level name={self.name('lvlout')} interval=33000000"] if have_element("level") else []
        return (["audioconvert", "audio/x-raw,format=F32LE,channels=2"] + meter_in
                + [f"{self.lv2_name} name={self.name('lim')}"] + meter_out + ["audioconvert"])

    def bind(self, fx, owners):
        self.lv2 = fx.get_by_name(self.name("lim"))
        owners[self.name("lvlin")] = self
        owners[self.name("lvlout")] = self

    def apply(self):
        for name, value in self.limiter_values.items():
            self.set_limiter_param(name, value)
        if self.lv2 is not None and "enabled" not in self.limiter_values:
            # LSP's "enabled" is its own power switch: the module's switch is used instead.
            # Switched off, the own limiter fades to the untouched sound (same delay): no new chain.
            try:
                self.lv2.set_property("enabled", bool(self.eq_on))
            except Exception:
                pass

    def on_level(self, source, peak):
        if source.startswith("lvlin_"):
            self._last_in = peak
        else:
            gr = 0.0
            if self.lv2 is not None:
                try:
                    gr = float(self.lv2.get_property("gain-reduction"))
                except Exception:
                    gr = min(0.0, peak - self._last_in)  # a limiter without that reading
            self.levels.append((self._last_in, peak, gr))

    def limiter_params(self):
        """Settings of the limiter: (name, kind, min, max, default), most useful first.
        Read from a fresh copy when this module is not in the chain."""
        element = self.lv2
        if element is None and self.lv2_name:
            element = Gst.ElementFactory.make(self.lv2_name, None)
        return element_params(element, LIMITER_PRIORITY, LIMITER_MAX_PARAMS, enums=True)

    def limiter_choices(self, name):
        element = self.lv2
        if element is None and self.lv2_name:
            element = Gst.ElementFactory.make(self.lv2_name, None)
        return element_enum_choices(element, name)

    def set_limiter_param(self, name, value):
        self.limiter_values[name] = value
        if self.lv2 is not None:
            if lim_key(name) == "enabled":
                value = bool(value) and bool(self.eq_on)   # the module's own switch counts too
            try:
                self.lv2.set_property(name, value)
            except Exception as err:
                print("Limiter setting failed:", name, err)


class SatUnit:
    """One Prism Saturator 17 in the sound chain: points say how hard each frequency is driven."""

    kind = "sat"

    def __init__(self, uid, player):
        self.uid = uid
        self.player = player
        self.points = [dict(p) for p in SAT_DEFAULTS["points"]]
        self.drive_db = SAT_DEFAULTS["drive"] * SAT_DRIVE_DB
        self.mix = 1.0
        self.output_db = 0.0
        self.sat_type = "soft"
        self.auto = True
        self.mode = "classic"          # or "bands"
        self.bands = clean_sat_bands({})
        self.spectrum = None
        self.spectrum_on = False
        self.eq_on = True
        self.clear()

    def clear(self):
        self.sat = self.spec = self.msat = None
        self._sent = None
        self._msent = None

    @property
    def playing(self):
        return self.player.playing

    def name(self, what):
        return f"{what}_{self.uid}"

    def copy_state(self, other):
        self.points = [dict(p) for p in other.points]
        self.drive_db, self.mix, self.output_db = other.drive_db, other.mix, other.output_db
        self.sat_type, self.auto = other.sat_type, other.auto
        self.mode, self.bands = other.mode, json.loads(json.dumps(other.bands))

    def structure(self):
        return (self.uid, "sat")

    def parts(self):
        if not HAVE_P17_SAT:
            return []
        parts = ["audioconvert", "audio/x-raw,format=F32LE,channels=2,layout=interleaved", f"p17sat name={self.name('sat')}"]
        if HAVE_P17_MSAT:  # Bands mode: always in, so switching modes only crossfades
            parts.append(f"p17msat name={self.name('msat')}")
        if have_element("spectrum"):
            parts.append(f"spectrum name={self.name('spec')} bands={SPECTRUM_BANDS} interval=66000000 threshold=-90 "
                         "post-messages=false message-phase=false")
        return parts + ["audioconvert"]

    def bind(self, fx, owners):
        self.sat = fx.get_by_name(self.name("sat"))
        self.msat = fx.get_by_name(self.name("msat"))
        self.spec = fx.get_by_name(self.name("spec"))
        self._sent = None
        self._msent = None
        if self.spec is not None:
            self.spec.set_property("post-messages", self.spectrum_on)
            owners[self.name("spec")] = self

    def apply(self):
        self._put()

    def _put(self):
        if self.sat is None:
            return
        bands = []
        for p in self.points[:15]:
            kind, gain = p["type"], float(p["gain"])
            if kind == "lowcut":      # a saturator cannot "cut": a cut point means "less drive below"
                kind, gain = "lowshelf", -12.0
            elif kind == "highcut":
                kind, gain = "highshelf", -12.0
            bands.append([{"bell": 1, "lowshelf": 2, "highshelf": 3}[kind], round(float(p["freq"]), 3),
                          round(gain, 3), round(float(p["q"]), 4)])
        bands_mode = self.mode == "bands" and self.msat is not None
        # Bands mode: the points saturator steps aside (mix 0, level 0 dB: the sound passes as it is),
        # both glide, so the change of mode is a crossfade.
        values = (json.dumps(bands), float(self.drive_db), 0.0 if bands_mode else float(self.mix),
                  0.0 if bands_mode else float(self.output_db),
                  [k for k, _n in SAT_TYPES].index(self.sat_type) if self.sat_type in dict(SAT_TYPES) else 0,
                  bool(self.auto))
        if self.sat.get_property("active") != bool(self.eq_on):
            self.sat.set_property("active", bool(self.eq_on))
        if values == self._sent:
            self._put_bands()
            return
        old = self._sent or (None,) * 6
        self._sent = values
        for name, value, before in zip(("bands", "drive-db", "mix", "output-db", "sat-type", "auto"), values, old):
            if value != before:
                self.sat.set_property(name, value)
        self._put_bands()

    def _put_bands(self):
        if self.msat is None:
            return
        text = json.dumps(sat_band_config(self.mode if self.eq_on else "classic", self.bands, self.auto))
        if text != self._msent:
            self._msent = text
            self.msat.set_property("config", text)

    def meters(self):
        """Bands mode: how hard each band hits the saturation now (dB)."""
        try:
            return self.msat.meters() if self.msat is not None else []
        except Exception:
            return []

    def set_points(self, points):
        self.points = [peq_clean(p) for p in points]
        self._put()

    def set_spectrum(self, on):
        self.spectrum_on = bool(on)
        if self.spec is not None:
            self.spec.set_property("post-messages", self.spectrum_on)


class OttUnit:
    """One OTT 17 in the sound chain: multiband upward + downward compression."""

    kind = "ott"

    def __init__(self, uid, player):
        self.uid = uid
        self.player = player
        self.config = clean_ott_settings({})
        self.spectrum = None
        self.spectrum_on = False
        self.eq_on = True
        self.clear()

    def clear(self):
        self.ott = self.spec = None
        self._sent = None

    @property
    def playing(self):
        return self.player.playing

    def name(self, what):
        return f"{what}_{self.uid}"

    def copy_state(self, other):
        self.config = json.loads(json.dumps(other.config))

    def structure(self):
        return (self.uid, "ott")

    def parts(self):
        if not HAVE_P17_OTT:
            return []
        parts = ["audioconvert", "audio/x-raw,format=F32LE,channels=2,layout=interleaved"]
        if have_element("spectrum"):  # what goes in, behind the bands
            parts.append(f"spectrum name={self.name('spec')} bands={SPECTRUM_BANDS} interval=66000000 threshold=-90 "
                         "post-messages=false message-phase=false")
        return parts + [f"p17ott name={self.name('ott')}", "audioconvert"]

    def bind(self, fx, owners):
        self.ott = fx.get_by_name(self.name("ott"))
        self.spec = fx.get_by_name(self.name("spec"))
        self._sent = None
        if self.spec is not None:
            self.spec.set_property("post-messages", self.spectrum_on)
            owners[self.name("spec")] = self

    def apply(self):
        self._put()

    def _put(self):
        if self.ott is None:
            return
        if self.ott.get_property("active") != bool(self.eq_on):
            self.ott.set_property("active", bool(self.eq_on))
        text = json.dumps(self.config)
        if text != self._sent:
            self._sent = text
            self.ott.set_property("config", text)

    def set_config(self, config):
        self.config = json.loads(json.dumps(config))
        self._put()

    def set_spectrum(self, on):
        self.spectrum_on = bool(on)
        if self.spec is not None:
            self.spec.set_property("post-messages", self.spectrum_on)

    def meters(self):
        """[(loudest level dB, gain change dB)] per band, or [] when not playing through it."""
        element = self.ott
        try:
            return element.meters() if element is not None else []
        except Exception:
            return []

    def limit_gr(self):
        element = self.ott
        try:
            return element.limit_gr() if element is not None else 0.0
        except Exception:
            return 0.0

    def band_limit_gr(self):
        element = self.ott
        try:
            return element.band_limit_gr() if element is not None else []
        except Exception:
            return []


MODULE_UNITS = {"eq": EqUnit, "sat": SatUnit, "ott": OttUnit, "limiter": LimiterUnit}


class Player:
    """GStreamer: playbin + the `pitch` element (changes tempo, keeps the tone).

    The effects chain can be built again at any moment (when LV2 effects are added, removed,
    switched on or off): every setting is kept here and put back on the new chain."""

    def __init__(self, on_end, lv2_slots=None, video=False, vst=None, on_play=None):
        self.video = video          # video player: no tempo (EQ, reverb, Crunch, limiter, plugins as music)
        # The sample rate the sound is played at (Plugins window): None = as the track itself.
        # Set before the effects, so Plugins 17 and VST already work at it.
        self.out_rate = None
        self.vst = vst or VST       # which VST3 chain this player uses
        self.on_play = on_play      # called when playback starts (the other window pauses)
        self.pipe = Gst.ElementFactory.make("playbin", "video-player" if video else "player")
        # The own limiter when it is there; otherwise an installed LV2 one (LSP, Calf).
        self.lv2_name = "p17limiter" if HAVE_P17_LIMITER else cached_lv2_limiter()
        self.lv2_slots = list(lv2_slots or [])  # LV2 effects chosen by the user, in order

        # Plugins 17: every module keeps its own settings (EqUnit / LimiterUnit), so a new
        # chain gets the same sound. `modules` = the ones in the sound now, in their order.
        self.units = {}            # module id -> unit (also the switched-off ones)
        self.modules = []
        self._owners = {}          # element name -> unit (spectrum and level readings)
        self._built_structure = None
        self.tempo = 1.0
        self.master_tempo = True   # True: key stays (SoundTouch), False: like vinyl (clean)
        self.master_peak = -90.0   # loudest sample leaving all the effects, in dB (0 dB = overload)
        self.master_rms = -90.0    # its average loudness (what the ear hears), in dB
        self._built_stage = None   # which tempo element the current chain has
        self._tempo_pending = 0
        self.uri = None
        self._resume_at = None
        self.plugins_on = True     # False: the VST3 / LV2 effects are left out (radio, by default)
        self.streaming = False     # True while an internet stream (radio) is loaded
        self._buffering = False
        self.on_tag = None         # called with the title a radio station sends
        self.on_error = None       # called with the error text
        self._tap_cb = None        # recording: gets every block of sound that leaves the effects
        self._tap = None
        # Repeat one track, without a seam: a function that says "loop this one now". When the
        # track is about to end, the same file is queued right behind itself (playbin's gapless
        # playback), so the end runs straight into the start like a loop, with no gap or click,
        # and nothing is stopped or rebuilt (tempo, effects and their tails go on).
        self.loop_one = None
        self.on_looped = None      # called (main thread) each time the loop came round
        self.pipe.connect("about-to-finish", self._about_to_finish)
        # The loop itself: a "segment" seek. The track plays as one segment; at its end the
        # pipeline says "segment done" instead of ending, and a seek back to the start WITHOUT
        # flushing is queued right behind the last sample: the same decoder, the same tempo
        # stretcher and effects go on, sample after sample, at the exact tempo set. (The
        # gapless queue above is only the fallback, e.g. for a file that cannot seek.)
        self._seg_loop = False
        # Start check: a track that was told to play but did not start within a few seconds
        # (stuck at 0:00, silent) is loaded once more; if it still does not start, the window
        # is told (on_error) instead of showing "playing" over silence.
        self._start_watch = 0
        self._start_retried = False

        self.pipe.set_property("audio-filter", self._build_fx())

        # Output buffer: 150 ms. With a smaller one the tempo change (the `pitch` element
        # works in blocks) left short holes in the sound; the equalizer still reacts fast.
        # pulsesink talks to PulseAudio and to PipeWire (the default sound server today).
        sink = Gst.ElementFactory.make("pulsesink", None)
        if sink is None:  # no PulseAudio plugin: let GStreamer pick (ALSA, PipeWire, JACK...)
            fallback = Gst.ElementFactory.make("autoaudiosink", None)
            if fallback is not None:
                self.pipe.set_property("audio-sink", fallback)
        if sink is not None:
            self.sink = sink
            self._tune_sink(self._built_stage)
            self.pipe.set_property("audio-sink", sink)

        # playbin keeps its own audio queue ("aqueue", up to a second of sound). With a file it
        # is always full, so whatever an effect does now could be heard only after that queue
        # has played out. (The browser's live sound never fills it: that is why its faders felt
        # quicker.) Kept short here.
        self.pipe.connect("deep-element-added", self._on_deep_element)

        bus = self.pipe.get_bus()
        bus.add_signal_watch()
        self._on_end = on_end
        bus.connect("message::eos", lambda *_: on_end())
        bus.connect("message::segment-done", self._on_segment_done)
        bus.connect("message::error", self._on_error)
        bus.connect("message::element", self._on_element)
        bus.connect("message::async-done", self._on_async_done)
        bus.connect("message::tag", self._on_tag)
        bus.connect("message::buffering", self._on_buffering)
        self.playing = False

    def loop_wanted(self):
        try:
            return bool(self.loop_one and self.loop_one()) and bool(self.uri) and not self.streaming \
                and self.uri.startswith("file://")
        except Exception:
            return False

    def _seek_flags(self, flags):
        """Every jump keeps the segment loop going while "repeat this track" is on."""
        if self.loop_wanted():
            self._seg_loop = True
            return flags | Gst.SeekFlags.SEGMENT
        self._seg_loop = False
        return flags

    def refresh_loop(self):
        """Repeat mode changed: arm the segment loop from where the track is now (one short
        jump to the same place), or let the next segment end be a normal end."""
        if self.loop_wanted() and not self._seg_loop:
            ok, pos = self.pipe.query_position(Gst.Format.TIME)
            if ok and pos >= 0:
                self.pipe.seek_simple(Gst.Format.TIME, self._seek_flags(Gst.SeekFlags.FLUSH | Gst.SeekFlags.ACCURATE), pos)

    def _on_segment_done(self, *_):
        if self.loop_wanted():
            # back to the start, no flush: it follows the last sample with nothing in between
            self.pipe.seek(1.0, Gst.Format.TIME, Gst.SeekFlags.SEGMENT | Gst.SeekFlags.ACCURATE,
                           Gst.SeekType.SET, 0, Gst.SeekType.NONE, -1)
            if self.on_looped is not None:
                self.on_looped()
        else:   # the loop was switched off while playing: this is the end of the track
            self._seg_loop = False
            if self._on_end is not None:
                self._on_end()

    def _about_to_finish(self, _pipe):
        """(GStreamer's thread) The decoder is near the end: loop this file seamlessly."""
        if self._seg_loop:
            return   # the segment loop does it
        uri = self.uri
        try:
            loop = bool(self.loop_one and self.loop_one())
        except Exception:
            loop = False
        if not loop or not uri or self.streaming or not uri.startswith("file://"):
            return   # normal end: EOS comes, the window decides what plays next
        self.pipe.set_property("uri", uri)
        if self.on_looped is not None:
            GLib.idle_add(lambda: self.on_looped() or False)

    @staticmethod
    def _on_deep_element(_bin, _sub, element):
        factory = element.get_factory()
        name = element.get_name() or ""
        if factory is not None and factory.get_name() == "queue" and name.startswith("aqueue"):
            element.set_property("max-size-buffers", 0)
            element.set_property("max-size-bytes", 0)
            element.set_property("max-size-time", 30 * Gst.MSECOND)
            debug_log(f"audio queue {name}: kept at 30 ms")

    # --- the chain ---
    def _build_fx(self):
        def have(name):
            return Gst.ElementFactory.find(name) is not None

        # Effects chain: tempo -> Plugins 17 (Prism EQ 17 / Limiter 17, in the user's order)
        # -> VST3 -> LV2 -> overload meter.
        # The video player has the same chain without the tempo stage.
        structure = self._structure()
        self._built_structure = structure
        parts = ["audioconvert"]
        if getattr(self, "out_rate", None):
            parts += ["audioresample quality=8", f"audio/x-raw,rate={int(self.out_rate)}", "audioconvert"]
        # Decoders hand over big blocks (FLAC: about 93 ms each). Every effect takes one set of
        # values per block, so a fader was heard in steps and late. Cut into 10 ms blocks
        # ("split_blocks_ms" in settings.json; 0 = off).
        try:
            # Off by default: audiobuffersplit sometimes held a new track at 0:00 in silence.
            split_ms = int(shared_settings().get("split_blocks_ms", 0))
        except (TypeError, ValueError):
            split_ms = 10
        if split_ms > 0 and have("audiobuffersplit"):
            # discont-wait=0: after every new track (or jump) audiobuffersplit waited up to a
            # second "for the stream to settle" before letting sound through. That held some
            # tracks at 0:00 in silence. With 0 it passes the new sound on at once.
            split = f"audiobuffersplit output-buffer-duration=1/{max(10, 1000 // max(1, split_ms))}"
            probe = Gst.ElementFactory.make("audiobuffersplit", None)
            if probe is not None and probe.find_property("discont-wait") is not None:
                split += " discont-wait=0"
            parts += ["audio/x-raw,format=F32LE,layout=interleaved", split, "audioconvert"]
        stage = None if self.video else self._tempo_stage()
        self._built_stage = stage
        if stage in ("stretch", "rate"):
            parts.append("pitch name=pitch")
        elif stage == "speed":
            parts += ["audioconvert", "audio/x-raw,format=F32LE", "speed name=speed"]
        # Plugins 17, in the order the user set. They live in a small bin of their own between
        # these two marks, so they can be swapped while the sound plays (swap_modules).
        parts += ["identity name=p17_head silent=true", "identity name=p17_tail silent=true"]
        if HAVE_VST_ELEMENT:  # VST3 effects: after reverb, before the limiter
            parts += ["audioconvert", "audio/x-raw,format=F32LE,channels=2,layout=interleaved", "plyervst name=vstfx", "audioconvert"]
        before_lv2 = list(parts)
        active = [s for s in self.lv2_slots
                  if self.plugins_on and s.get("enabled", True) and have(s["factory"])]
        for i, slot in enumerate(active):  # LV2 effects, in the order of the list
            parts += ["audioconvert", f"{slot['factory']} name=lv2fx{i}", "audioconvert"]
        tail = []
        # The overload meter of the Plugins window: what leaves every effect, at the very end.
        if have("level"):
            tail = ["audioconvert", "audio/x-raw,format=F32LE", "level name=lvl_master interval=50000000",
                    "audioconvert"]
        # The safety ceiling, at the very end (after the meter, so an overload still shows there):
        # whatever the gains of the effects do (an output or input gain pushed to the end, a loud
        # VST), the sound is limited at -0.1 dBFS instead of clipping into a crackle. It does
        # nothing at all below that level (1.5 ms of delay). "safety_ceiling": false in
        # settings.json switches it off.
        if HAVE_P17_LIMITER and shared_settings().get("safety_ceiling", True):
            tail += ["audioconvert", "audio/x-raw,format=F32LE,channels=2,layout=interleaved",
                     "p17limiter name=p17safe threshold-db=0 boost=false attack-ms=1 release-ms=60 "
                     "lookahead-ms=1.5 knee-db=0 density=0", "audioconvert"]
        try:
            fx = Gst.parse_bin_from_description(" ! ".join(parts + tail), True)
        except GLib.Error as err:  # one of the LV2 effects cannot be built: play without them
            print("LV2 effects are off:", err.message)
            active = []
            fx = Gst.parse_bin_from_description(" ! ".join(before_lv2 + tail), True)

        for slot in self.lv2_slots:
            slot["element"] = None
        for i, slot in enumerate(active):
            slot["element"] = fx.get_by_name(f"lv2fx{i}")
        head, tail_mark = fx.get_by_name("p17_head"), fx.get_by_name("p17_tail")
        head.unlink(tail_mark)
        mods = self._module_bin()
        fx.add(mods)
        head.link(mods)
        mods.link(tail_mark)
        self._mods = mods

        vst_element = fx.get_by_name("vstfx")
        if vst_element is not None:
            vst_element.engine = self.vst  # this chain's own VST3 effects
            try:
                vst_element.set_transform_ip_on_passthrough(False)
            except Exception:
                pass
            self.vst.elements = [e for e in self.vst.elements if e.get_parent() is not None]
            self.vst.elements.append(vst_element)
            self.vst.update_passthrough()
        self.pitch = fx.get_by_name("pitch")
        self.speed = fx.get_by_name("speed")
        self._owners = {}
        for unit in self.modules:
            unit.bind(fx, self._owners)
        self.fx = fx
        self._apply_state()
        return fx

    def _module_bin(self):
        """The Plugins 17 modules, in their order, as one bin (just a pass-through when none)."""
        for unit in self.units.values():
            unit.clear()
        parts = []
        for unit in self.modules:
            parts += unit.parts()
        try:
            return Gst.parse_bin_from_description(" ! ".join(parts) if parts else "identity silent=true", True)
        except GLib.Error as err:
            print("Plugins 17 could not be built:", err.message)
            return Gst.parse_bin_from_description("identity silent=true", True)

    def swap_modules(self):
        """Modules added, removed or moved: only their bin is replaced, while the sound plays.
        The sound is held for a moment just before them, the old bin goes out, the new one goes
        in, and the sound goes on: the radio does not reconnect, a track does not jump.
        Not playing (or anything unusual): the whole chain is built again, as before."""
        fx, old = getattr(self, "fx", None), getattr(self, "_mods", None)
        head = fx.get_by_name("p17_head") if fx is not None else None
        if old is None or head is None or getattr(self, "_swap_probe", None):
            if not getattr(self, "_swap_probe", None):
                self.rebuild_fx()
            return
        # "hot_swap_modules": false in settings.json goes back to the old way (a new chain)
        if self.pipe.get_state(0)[1] != Gst.State.PLAYING or not shared_settings().get("hot_swap_modules", True):
            self.rebuild_fx()
            return
        pad = head.get_static_pad("src")
        scheduled = [False]

        def blocked(_pad, _info):
            if not scheduled[0]:
                scheduled[0] = True
                GLib.idle_add(self._finish_swap)
            return Gst.PadProbeReturn.OK

        self._swap_probe = (pad, pad.add_probe(Gst.PadProbeType.BLOCK_DOWNSTREAM, blocked))

        def too_long():
            # No sound came by (a stream that stalls): no waiting for ever, build it all again.
            if getattr(self, "_swap_probe", None) and not scheduled[0]:
                pad_, probe_id = self._swap_probe
                self._swap_probe = None
                pad_.remove_probe(probe_id)
                self.rebuild_fx()
            return False

        GLib.timeout_add(600, too_long)

    def _finish_swap(self):
        """Main thread, while the sound waits just before the modules."""
        probe = getattr(self, "_swap_probe", None)
        if probe is None:
            return False
        pad, probe_id = probe
        fx, old = self.fx, self._mods
        head, tail_mark = fx.get_by_name("p17_head"), fx.get_by_name("p17_tail")
        try:
            head.unlink(old)
            old.unlink(tail_mark)
            fx.remove(old)
            old.set_state(Gst.State.NULL)
            new = self._module_bin()
            fx.add(new)
            head.link(new)
            new.link(tail_mark)
            new.sync_state_with_parent()
            self._mods = new
            self._built_structure = self._structure()
            self._owners = {}
            for unit in self.modules:
                unit.bind(fx, self._owners)
            for unit in self.modules:
                unit.apply()
            debug_log("Plugins 17 swapped while playing")
        except Exception as exc:  # anything odd: the old way
            print("Plugins 17 could not be swapped while playing:", exc)
            self._swap_probe = None
            pad.remove_probe(probe_id)
            self.rebuild_fx()
            return False
        self._swap_probe = None
        pad.remove_probe(probe_id)   # the sound goes on, through the new modules
        return False

    def _apply_state(self):
        """Put every saved setting on the (new) chain."""
        for unit in self.modules:
            unit.apply()
        self._put_tempo()
        for slot in self.lv2_slots:
            for key, value in slot.get("params", {}).items():
                self._put_lv2(slot, key, value)

    def _structure(self):
        """What the chain must contain: the modules in their order, each with its parts
        (cut filters, Crunch stage). Switched-off modules are simply not there."""
        return tuple(unit.structure() for unit in self.modules)

    def rebuild_if_needed(self):
        """New modules when their parts changed (swapped while playing); True if they were."""
        if self._structure() != self._built_structure:
            self.swap_modules()
            return True
        return False

    def unit(self, uid, kind):
        """The unit of a module (made the first time; its settings stay while the player lives)."""
        unit = self.units.get(uid)
        if unit is None or unit.kind != kind:
            unit = MODULE_UNITS[kind](uid, self)
            self.units[uid] = unit
        return unit

    def set_modules(self, units, live=None):
        """Every module in its order; `live`: the ones switched on (all when None).
        A switched-off module stays in the chain and only fades out, so switching never builds
        a new chain (the radio does not reconnect). A new chain only when modules are added,
        removed or moved."""
        self.modules = list(units)
        live = {id(u) for u in self.modules} if live is None else {id(u) for u in live}
        for unit in self.units.values():
            unit.eq_on = id(unit) in live
        self.refresh()

    def forget_unit(self, uid):
        self.units.pop(uid, None)

    def refresh(self):
        """All the values were set directly: new modules if their parts changed (swapped while
        playing, no new chain), or just apply them."""
        if self._structure() != self._built_structure:
            self.swap_modules()
        else:
            self._apply_state()

    def _tune_sink(self, stage):
        """Output buffer. A changed tempo needs the big one (the `pitch` element works in blocks,
        a small buffer left short holes). At normal tempo a smaller one is enough, and every
        equalizer move is then heard about twice as soon."""
        sink = getattr(self, "sink", None)
        if sink is None:
            return
        big = stage is not None or getattr(self, "big_buffer", False)
        if big:
            buffer_ms, latency_ms = 200, 20
        else:
            # Small buffer: a knob move is heard about 40 ms later. If the sound crackles on a
            # slow computer, set "output_buffer_ms" in settings.json (60, 90...).
            try:
                buffer_ms = int(shared_settings().get("output_buffer_ms", OUTPUT_BUFFER_MS))
            except (TypeError, ValueError):
                buffer_ms = OUTPUT_BUFFER_MS
            buffer_ms = max(20, min(500, buffer_ms))
            latency_ms = max(5, min(10, buffer_ms // 4))
        sink.set_property("buffer-time", buffer_ms * 1000)   # microseconds
        sink.set_property("latency-time", latency_ms * 1000)

    def set_out_rate(self, rate):
        """A new output sample rate (None = as the track): the chain is built again and the track
        goes on from the same place."""
        rate = int(rate) if rate else None
        if rate == self.out_rate:
            return
        self.out_rate = rate
        self.rebuild_fx(reload=True)

    def rebuild_fx(self, reload=True):
        """New effects chain (LV2 effects or the tempo stage changed).
        The track goes on from the same place. reload=False: a new track is loaded next anyway."""
        ok, pos = self.pipe.query_position(Gst.Format.TIME)
        self.pipe.set_state(Gst.State.NULL)
        self.pipe.set_property("audio-filter", self._build_fx())
        self._tune_sink(self._built_stage)
        if self._tap_cb is not None:  # a recording goes on through the new chain
            self._attach_tap()
        if self.uri and reload:
            self._resume_at = pos if ok and pos > 0 and not self.streaming else None
            self.pipe.set_property("uri", self.uri)
            self.pipe.set_state(Gst.State.PLAYING if self.playing else Gst.State.PAUSED)

    # --- tap: what leaves the effects (EQ, VST3, LV2, limiter), before the master volume ---
    def start_tap(self, callback):
        """callback(caps, bytes) is called for every block of sound (in the sound thread)."""
        self._tap_cb = callback
        self._attach_tap()

    def stop_tap(self):
        self._tap_cb = None
        self._detach_tap()

    def _attach_tap(self):
        self._detach_tap()
        fx = getattr(self, "fx", None)
        pad = fx.get_static_pad("src") if fx is not None else None
        if pad is None:
            return

        def probe(pad, info):
            callback = self._tap_cb
            buf = info.get_buffer()
            if callback is not None and buf is not None:
                ok, mapped = buf.map(Gst.MapFlags.READ)
                if ok:
                    try:
                        data = bytes(mapped.data)
                    finally:
                        buf.unmap(mapped)
                    try:
                        callback(pad.get_current_caps(), data)
                    except Exception as exc:  # recording must never stop the sound
                        print("Recording:", exc)
            return Gst.PadProbeReturn.OK

        self._tap = (pad, pad.add_probe(Gst.PadProbeType.BUFFER, probe))

    def _detach_tap(self):
        if self._tap is not None:
            pad, probe_id = self._tap
            self._tap = None
            try:
                pad.remove_probe(probe_id)
            except Exception:
                pass

    def _on_async_done(self, *_):
        if self._resume_at is not None:
            pos, self._resume_at = self._resume_at, None
            self.pipe.seek_simple(Gst.Format.TIME, self._seek_flags(Gst.SeekFlags.FLUSH | Gst.SeekFlags.ACCURATE), pos)
        elif self.loop_wanted() and not self._seg_loop:
            # a track just loaded with "repeat this track" on: it starts as a loop segment
            self.pipe.seek_simple(Gst.Format.TIME, self._seek_flags(Gst.SeekFlags.FLUSH | Gst.SeekFlags.ACCURATE), 0)

    # --- LV2 effects ---
    def _put_lv2(self, slot, key, value):
        element = slot.get("element")
        if element is None:
            return
        kind = slot.get("kinds", {}).get(key, "float")
        try:
            if kind == "bool":
                element.set_property(key, bool(value))
            elif kind == "int":
                element.set_property(key, int(round(value)))
            else:
                element.set_property(key, float(value))
        except Exception as err:
            print("LV2 setting failed:", key, err)

    def set_lv2_param(self, slot, key, value):
        slot.setdefault("params", {})[key] = value
        self._put_lv2(slot, key, value)

    # --- settings ---
    def set_volume(self, value):
        self.pipe.set_property("volume", float(value))

    def _on_element(self, _bus, msg):
        """Level readings (peak, in dB) from before and after the limiter, about 30 per second."""
        structure = msg.get_structure()
        source = msg.src.get_name() if msg.src is not None else ""
        if structure is not None and structure.get_name() == "spectrum":
            owner = self._owners.get(source)
            values = parse_spectrum(structure.to_string()) if owner is not None else None
            if values:
                owner.spectrum = values
            return
        if structure is None or structure.get_name() != "level":
            return
        try:
            peaks = structure.get_value("peak")
            peak = max(peaks) if peaks else SCOPE_FLOOR_DB
        except Exception:
            return
        if source == "lvl_master":
            self.master_peak = peak
            try:
                rms = structure.get_value("rms")
                self.master_rms = max(rms) if rms else SCOPE_FLOOR_DB
            except Exception:
                self.master_rms = peak - 12.0
        else:
            owner = self._owners.get(source)
            if owner is not None and hasattr(owner, "on_level"):
                owner.on_level(source, peak)

    def _on_error(self, _bus, msg):
        err, debug = msg.parse_error()
        print("GStreamer error:", err.message, debug or "")
        if self.on_error is not None:
            self.on_error(err.message)

    def load(self, path):
        self._resume_at = None
        self._seg_loop = False
        self.streaming = False
        self._buffering = False
        # READY, not NULL: the connection to the sound server (pulsesink) stays open between
        # tracks. Closing and reopening it on every click is the likely reason a track was
        # sometimes stuck at 0:00 in silence (the start check below catches what is left).
        self.pipe.set_state(Gst.State.READY)
        self.uri = GLib.filename_to_uri(path, None)
        self.pipe.set_property("uri", self.uri)
        self.pipe.set_state(Gst.State.PLAYING if self.playing else Gst.State.PAUSED)
        self._start_retried = False
        self._arm_start_check()

    def _arm_start_check(self):
        if self._start_watch:
            GLib.source_remove(self._start_watch)
        self._start_watch = GLib.timeout_add(1200, self._check_started)

    def _check_started(self):
        """(1.2 s after a track was loaded) Is it really playing? If not: load it once more."""
        self._start_watch = 0
        if not self.playing or self.streaming or not self.uri or not self.uri.startswith("file://"):
            return False
        _ret, state, _pending = self.pipe.get_state(0)
        ok, pos = self.pipe.query_position(Gst.Format.TIME)
        if state == Gst.State.PLAYING and ok and pos > 0:
            return False   # it plays
        if not self._start_retried:
            self._start_retried = True
            print("[Player-17] the track did not start, loading it again:", self.uri, file=sys.stderr)
            self._resume_at = None
            self.pipe.set_state(Gst.State.NULL)
            self.pipe.set_property("uri", self.uri)
            self.pipe.set_state(Gst.State.PLAYING)
            self._arm_start_check()
            return False
        print("[Player-17] the track could not start:", self.uri, file=sys.stderr)
        if self.on_error is not None:
            self.on_error("This track could not start")
        return False

    def load_uri(self, uri):
        """An internet stream (radio): no seeking, no tempo."""
        self._resume_at = None
        self._seg_loop = False
        self.streaming = True
        self._buffering = False
        self.pipe.set_state(Gst.State.NULL)
        self.uri = uri
        self.pipe.set_property("uri", uri)
        self.pipe.set_state(Gst.State.PLAYING if self.playing else Gst.State.PAUSED)

    def _on_tag(self, _bus, msg):
        """Radio stations send the song that is on ("Artist - Title")."""
        if self.on_tag is None or not self.streaming:
            return
        try:
            ok, title = msg.parse_tag().get_string(Gst.TAG_TITLE)
        except Exception:
            return
        if ok and title and title.strip():
            self.on_tag(title.strip())

    def _on_buffering(self, _bus, msg):
        """A stream waits until enough sound has arrived, instead of stuttering."""
        if not self.streaming:
            return
        percent = msg.parse_buffering()
        if percent < 100:
            if self.playing and not self._buffering:
                self._buffering = True
                self.pipe.set_state(Gst.State.PAUSED)
        elif self._buffering:
            self._buffering = False
            if self.playing:
                self.pipe.set_state(Gst.State.PLAYING)

    def set_plugins_on(self, on, reload=True):
        """All LV2 effects in or out of the chain (the VST3 ones are switched in their engine)."""
        on = bool(on)
        if on == self.plugins_on:
            return
        self.plugins_on = on
        if any(s.get("enabled", True) for s in self.lv2_slots):
            self.rebuild_fx(reload=reload)

    def play(self):
        self.playing = True
        self.pipe.set_state(Gst.State.PLAYING)
        if self.on_play is not None:
            self.on_play()

    def pause(self):
        self.playing = False
        self.pipe.set_state(Gst.State.PAUSED)

    # --- tempo ---
    # SoundTouch (the `pitch` element) sends the sound through its time stretcher ALWAYS, even at
    # the original tempo, and that is what softens the kick. So the chain holds a tempo element
    # only while the tempo is really changed:
    #   None      original tempo: nothing in the way, the sound is untouched
    #   "stretch" Master Tempo on: tempo changes, the key stays (SoundTouch time stretch)
    #   "speed"   Master Tempo off: like vinyl, a plain resampler, clean attacks, the key moves
    #   "rate"    Master Tempo off, but the `speed` element is missing: SoundTouch's resampler
    def _tempo_stage(self):
        if abs(self.tempo - 1.0) < 1e-6:
            return None
        if self.master_tempo:
            return "stretch" if Gst.ElementFactory.find("pitch") else None
        if Gst.ElementFactory.find("speed"):
            return "speed"
        return "rate" if Gst.ElementFactory.find("pitch") else None

    def _put_tempo(self):
        if self.pitch is not None:
            if self._built_stage == "rate":
                self.pitch.set_property("rate", float(self.tempo))
            else:
                self.pitch.set_property("tempo", float(self.tempo))
        if self.speed is not None:
            self.speed.set_property("speed", float(self.tempo))

    def set_tempo(self, ratio, smooth=False):
        """smooth=True (BPM buttons and dragging): at most ~14 changes per second reach the
        tempo element. smooth=False is for loading a track (the track is loaded right after)."""
        self.tempo = float(ratio)
        if not smooth:
            if self._tempo_pending:
                GLib.source_remove(self._tempo_pending)
                self._tempo_pending = 0
            if self._tempo_stage() != self._built_stage:
                self.rebuild_fx(reload=False)
            else:
                self._put_tempo()
            return
        if not self._tempo_pending:
            self._tempo_pending = GLib.timeout_add(70, self._flush_tempo)

    def _flush_tempo(self):
        self._tempo_pending = 0
        if self._tempo_stage() != self._built_stage:
            self.rebuild_fx()  # tempo element added or taken out: the track goes on from the same place
        else:
            self._put_tempo()
        return False

    def set_master_tempo(self, on):
        self.master_tempo = bool(on)
        if self._tempo_stage() != self._built_stage:
            self.rebuild_fx()

    def position_fraction(self):
        ok_p, pos = self.pipe.query_position(Gst.Format.TIME)
        ok_d, dur = self.pipe.query_duration(Gst.Format.TIME)
        if ok_p and ok_d and dur > 0:
            return pos / dur, pos / Gst.SECOND
        return 0.0, 0.0

    def times(self):
        """(position, duration) in seconds; 0 when unknown."""
        ok_p, pos = self.pipe.query_position(Gst.Format.TIME)
        ok_d, dur = self.pipe.query_duration(Gst.Format.TIME)
        return (pos / Gst.SECOND if ok_p else 0.0), (dur / Gst.SECOND if ok_d else 0.0)

    def seek_fraction(self, fraction):
        ok, dur = self.pipe.query_duration(Gst.Format.TIME)
        if ok and dur > 0:
            self.pipe.seek_simple(
                Gst.Format.TIME, self._seek_flags(Gst.SeekFlags.FLUSH | Gst.SeekFlags.ACCURATE),
                int(max(0.0, min(1.0, fraction)) * dur),
            )

    def stop(self):
        self.pipe.set_state(Gst.State.NULL)


class NameLabel(Gtk.Widget):
    """A one-line text that never makes its column wider.

    When the text does not fit, it is cut at the edge and can be moved:
    - by the shared slider under the track list (`shared()` gives 0..1 for every row at once),
    - by itself while the mouse is over it: it slides to the end, waits, and comes back."""

    __gtype_name__ = "PlyerNameLabel"
    SPEED = 45.0  # pixels per second for the hover slide

    def __init__(self, text="", xalign=0.0, shared=None):
        super().__init__()
        self.label = Gtk.Label(label=text, xalign=0, single_line_mode=True)
        self.label.set_parent(self)
        self.xalign = xalign
        self.shared = shared
        self.hover_pos = 0.0     # 0..1 of the hidden part, from the hover slide
        self._hovered = False
        self._tick = 0
        self._t0 = 0
        self._overflow = 0
        self.set_overflow(Gtk.Overflow.HIDDEN)
        self.set_hexpand(True)
        motion = Gtk.EventControllerMotion()
        motion.connect("enter", self._on_enter)
        motion.connect("leave", self._on_leave)
        self.add_controller(motion)

    def do_dispose(self):
        if self._tick:  # a hover slide still running: it must not touch a widget being taken apart
            try:
                self.remove_tick_callback(self._tick)
            except Exception:
                pass
            self._tick = 0
        if self.label is not None:
            self.label.unparent()
            self.label = None
        super().do_dispose()

    # the same calls as a Gtk.Label, so the rest of the code does not care
    def set_text(self, text):
        if self.label is None:
            return
        self.label.set_text(text)
        self.hover_pos = 0.0
        self.queue_resize()

    def get_text(self):
        return self.label.get_text() if self.label is not None else ""

    def do_measure(self, orientation, for_size):
        if self.label is None:
            return 0, 0, -1, -1
        minimum, natural, _b1, _b2 = self.label.measure(orientation, for_size)
        if orientation == Gtk.Orientation.HORIZONTAL:
            return 0, natural, -1, -1  # never forces the column wider
        return minimum, natural, -1, -1

    def do_size_allocate(self, width, height, baseline):
        if self.label is None:
            return
        _m, natural, _b1, _b2 = self.label.measure(Gtk.Orientation.HORIZONTAL, -1)
        self._overflow = max(0, natural - width)
        if self._overflow:
            share = self.shared() if self.shared else 0.0
            x = -self._overflow * max(share, self.hover_pos)
        else:
            x = (width - natural) * self.xalign
        transform = Gsk.Transform.new().translate(Graphene.Point().init(round(x), 0))
        self.label.allocate(max(natural, width) if self._overflow else natural, height, baseline, transform)

    # --- hover slide ---
    def _on_enter(self, *_):
        self._hovered = True
        if self._overflow and not self._tick:
            self._t0 = 0
            self._tick = self.add_tick_callback(self._on_tick)

    def _on_leave(self, *_):
        self._hovered = False
        if self.hover_pos > 0 and not self._tick:
            self._tick = self.add_tick_callback(self._on_tick)

    def _on_tick(self, _w, clock):
        if self.label is None:
            self._tick = 0
            return GLib.SOURCE_REMOVE
        now = clock.get_frame_time() / 1_000_000
        if not self._hovered:  # glide back to the start
            self.hover_pos *= 0.8
            if self.hover_pos < 0.002:
                self.hover_pos = 0.0
                self._tick = 0
                self.queue_allocate()
                return GLib.SOURCE_REMOVE
            self.queue_allocate()
            return GLib.SOURCE_CONTINUE
        if not self._t0:
            self._t0 = now
        travel = max(0.8, self._overflow / self.SPEED)
        wait_start, wait_end = 0.6, 1.2
        cycle = wait_start + travel + wait_end + travel
        t = (now - self._t0) % cycle
        if t < wait_start:
            pos = 0.0
        elif t < wait_start + travel:
            pos = (t - wait_start) / travel
        elif t < wait_start + travel + wait_end:
            pos = 1.0
        else:
            pos = 1.0 - (t - wait_start - travel - wait_end) / travel
        self.hover_pos = pos * pos * (3 - 2 * pos)  # soft start and stop
        self.queue_allocate()
        return GLib.SOURCE_CONTINUE


class PlayingBars(Gtk.Widget):
    """Three small bars that bounce while the track plays and rest low on pause."""

    __gtype_name__ = "PlyerPlayingBars"
    SPEEDS = (7.1, 9.3, 5.7)     # every bar moves at its own speed
    PHASES = (0.0, 1.7, 3.1)

    def __init__(self, is_playing):
        super().__init__()
        self.is_playing = is_playing  # function: True while the music plays
        self.heights = [0.3, 0.3, 0.3]
        self._tick = 0
        self.set_valign(Gtk.Align.CENTER)
        self.connect("map", self._start)
        self.connect("unmap", self._stop)

    def _start(self, *_):
        if not self._tick:
            self._tick = self.add_tick_callback(self._on_tick)

    def _stop(self, *_):
        if self._tick:
            self.remove_tick_callback(self._tick)
            self._tick = 0

    def _on_tick(self, _widget, clock):
        t = clock.get_frame_time() / 1_000_000
        playing = self.is_playing()
        for i in range(3):
            target = 0.25 + 0.75 * abs(math.sin(t * self.SPEEDS[i] / 2 + self.PHASES[i])) if playing else 0.22
            self.heights[i] += (target - self.heights[i]) * 0.35  # soft, not jumpy
        self.queue_draw()
        return GLib.SOURCE_CONTINUE

    def do_measure(self, orientation, for_size):
        return 16, 16, -1, -1

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        color = Gdk.RGBA()
        color.parse(COLORS["lines"])
        bar_w = w / 5
        for i, frac in enumerate(self.heights):
            bar_h = max(2.0, h * frac)
            rect = Graphene.Rect().init(i * 2 * bar_w, h - bar_h, bar_w, bar_h)
            rounded = Gsk.RoundedRect()
            rounded.init_from_rect(rect, bar_w / 2)
            snapshot.push_rounded_clip(rounded)
            snapshot.append_color(color, rect)
            snapshot.pop()


class Knob(Gtk.Widget):
    """A round knob, value 0..1. Drag up/down or use the mouse wheel."""

    __gtype_name__ = "PlyerKnob"

    def __init__(self, value, on_change, default, size=80):
        super().__init__()
        self.default = default
        self.value = max(0.0, min(1.0, value))
        self.on_change = on_change
        self._start = self.value
        self.size = size   # 80 normally; the small ones (Limit, Release) 56
        self.set_size_request(size, size)
        self.set_cursor_from_name("ns-resize")

        drag = Gtk.GestureDrag()
        drag.connect("drag-begin", lambda *_: setattr(self, "_start", self.value))
        drag.connect("drag-update", lambda _g, _dx, dy: self.set_value(self._start - dy / 160))
        self.add_controller(drag)

        scroll = Gtk.EventControllerScroll(flags=Gtk.EventControllerScrollFlags.VERTICAL)

        def on_scroll(_c, _dx, dy):
            self.set_value(self.value - dy * 0.04)
            return True

        scroll.connect("scroll", on_scroll)
        self.add_controller(scroll)

        click = Gtk.GestureClick()  # double click = default value
        click.connect("pressed", lambda _g, n, _x, _y: self.set_value(self.default) if n == 2 else None)
        self.add_controller(click)
        self.set_tooltip_text("Double click: reset")

    def set_value(self, value):
        value = max(0.0, min(1.0, value))
        if value != self.value:
            self.value = value
            self.queue_draw()
            self.on_change(value)

    def do_measure(self, orientation, for_size):
        return self.size, self.size, -1, -1

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        d = min(w, h) - 6
        ring, needle = Gdk.RGBA(), Gdk.RGBA()
        ring.parse(COLORS["eq_knob"])
        needle.parse("#ffffff")

        rect = Graphene.Rect().init((w - d) / 2, (h - d) / 2, d, d)
        rounded = Gsk.RoundedRect()
        rounded.init_from_rect(rect, d / 2)
        snapshot.append_border(rounded, [3, 3, 3, 3], [ring, ring, ring, ring])

        snapshot.save()
        snapshot.translate(Graphene.Point().init(w / 2, h / 2))
        snapshot.rotate(-135 + 270 * self.value)
        snapshot.append_color(needle, Graphene.Rect().init(-1.5, -d / 2 + 6, 3, d * 0.3))
        snapshot.restore()


class PrismEQ(Gtk.Widget):
    """Prism EQ: the frequency picture with points.

    Double click on empty space: new point.  Double click on a point: remove it.
    Drag a point: frequency (left / right) and gain (up / down).
    Mouse wheel over a point: Q (narrower / wider).
    The small arrow right of the selected point opens its settings."""

    __gtype_name__ = "PlyerPrismEQ"
    GRID_FREQS = (20, 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000)
    GRID_DB = (-12, -6, 0, 6, 12)
    PAD = 14
    HIT = 13            # how close the mouse must be to grab a point (pixels)

    def __init__(self, points, on_change, player):
        super().__init__()
        self.points = [peq_clean(p) for p in points]
        self.on_change = on_change
        self.player = player
        self.selected = None      # the point with the arrow
        self.sel = set()          # all selected points (frame, Shift + click, Ctrl + A)
        self.hover = None
        self._drag_start = None
        self._band = None         # the selection frame while it is drawn
        self._tick = 0
        self.set_hexpand(True)
        self.set_vexpand(True)
        self.set_focusable(True)

        click = Gtk.GestureClick()
        click.connect("pressed", self.on_click)
        self.add_controller(click)
        drag = Gtk.GestureDrag()
        drag.connect("drag-begin", self.on_drag_begin)
        drag.connect("drag-update", self.on_drag_update)
        drag.connect("drag-end", self.on_drag_end)
        self.add_controller(drag)
        scroll = Gtk.EventControllerScroll(flags=Gtk.EventControllerScrollFlags.VERTICAL)
        scroll.connect("scroll", self.on_scroll)
        self.add_controller(scroll)
        motion = Gtk.EventControllerMotion()
        motion.connect("motion", self.on_motion)
        motion.connect("leave", lambda *_: self.set_hover(None))
        self.add_controller(motion)
        keys = Gtk.EventControllerKey()
        keys.connect("key-pressed", self.on_key)
        self.add_controller(keys)
        self.connect("map", self._start)
        self.connect("unmap", self._stop)

    # --- live spectrum: redraw about 15 times a second while visible ---
    def _start(self, *_):
        self.player.set_spectrum(True)
        if not self._tick:
            self._tick = GLib.timeout_add(66, self._redraw)

    def _stop(self, *_):
        self.player.set_spectrum(False)
        if self._tick:
            GLib.source_remove(self._tick)
            self._tick = 0

    def _redraw(self):
        if self.player.spectrum is not None:
            self.queue_draw()
        return True

    def do_measure(self, orientation, for_size):
        return (220, 260, -1, -1) if orientation == Gtk.Orientation.VERTICAL else (360, 600, -1, -1)

    # --- coordinates ---
    def area(self):
        w, h = self.get_width(), self.get_height()
        return self.PAD, self.PAD, max(1, w - 2 * self.PAD), max(1, h - 2 * self.PAD)

    def x_of(self, freq):
        x0, _y0, w, _h = self.area()
        return x0 + w * (math.log10(freq / PEQ_FMIN) / math.log10(PEQ_FMAX / PEQ_FMIN))

    def freq_of(self, x):
        x0, _y0, w, _h = self.area()
        frac = max(0.0, min(1.0, (x - x0) / w))
        return PEQ_FMIN * (PEQ_FMAX / PEQ_FMIN) ** frac

    def y_of(self, db):
        _x0, y0, _w, h = self.area()
        return y0 + h / 2 - (db / PEQ_RANGE_DB) * (h / 2)

    def db_of(self, y):
        _x0, y0, _w, h = self.area()
        return max(-PEQ_RANGE_DB, min(PEQ_RANGE_DB, (y0 + h / 2 - y) / (h / 2) * PEQ_RANGE_DB))

    def point_xy(self, p):
        return self.x_of(p["freq"]), self.y_of(0.0 if p["type"] in ("lowcut", "highcut") else p["gain"])

    def point_at(self, x, y):
        best, best_d = None, self.HIT
        for i, p in enumerate(self.points):
            px, py = self.point_xy(p)
            d = math.hypot(px - x, py - y)
            if d <= best_d:
                best, best_d = i, d
        return best

    def arrow_xy(self):
        if self.selected is None or self.selected >= len(self.points):
            return None
        px, py = self.point_xy(self.points[self.selected])
        return px + 20, py

    # --- changes ---
    def changed(self):
        self.on_change([dict(p) for p in self.points])
        self.queue_draw()

    def set_hover(self, index):
        if index != self.hover:
            self.hover = index
            self.queue_draw()

    def add_point(self, x, y):
        bells = sum(1 for p in self.points if p["type"] in PEQ_GST_TYPE)
        if bells >= PEQ_MAX_BANDS:
            return
        self.points.append(peq_clean({"type": "bell", "freq": self.freq_of(x), "gain": self.db_of(y), "q": PEQ_NEW_Q}))
        self.selected = len(self.points) - 1
        self.sel = {self.selected}
        self.changed()

    def remove_points(self, indices):
        indices = sorted({i for i in indices if 0 <= i < len(self.points)}, reverse=True)
        for i in indices:
            del self.points[i]
        self.selected = None
        self.sel = set()
        if indices:
            self.changed()

    def remove_point(self, index):
        self.remove_points([index])

    def select_all(self):
        self.sel = set(range(len(self.points)))
        self.selected = 0 if self.points else None
        self.queue_draw()

    def select_none(self):
        self.sel = set()
        self.selected = None
        self.queue_draw()

    # --- mouse and keys ---
    def on_click(self, gesture, n_press, x, y):
        self.grab_focus()
        arrow = self.arrow_xy()
        if n_press == 1 and arrow and math.hypot(arrow[0] - x, arrow[1] - y) <= 9:
            gesture.set_state(Gtk.EventSequenceState.CLAIMED)
            self.open_point_menu()
            return
        index = self.point_at(x, y)
        if n_press == 2:
            if index is not None:
                self.remove_point(index)
            else:
                self.add_point(x, y)
            return
        shift = bool(gesture.get_current_event_state() & Gdk.ModifierType.SHIFT_MASK)
        if index is None:
            if not shift:
                self.select_none()
            return
        if shift:  # Shift + click: add to / take out of the selection
            self.sel ^= {index}
            self.selected = index if index in self.sel else (min(self.sel) if self.sel else None)
        elif index not in self.sel:
            self.sel = {index}
            self.selected = index
        else:
            self.selected = index
        self.queue_draw()

    def on_drag_begin(self, _gesture, x, y):
        index = self.point_at(x, y)
        if index is None:
            # Empty space: draw a frame, the points inside it get selected.
            self._drag_start = None
            self._band = (x, y, x, y)
            return
        self._band = None
        if index not in self.sel:
            self.sel = {index}
        self.selected = index
        # Every selected point moves together: same step in frequency (on the log scale) and in dB.
        self._drag_start = {i: (self.x_of(self.points[i]["freq"]), self.y_of(self.points[i]["gain"]))
                            for i in self.sel if i < len(self.points)}

    def on_drag_update(self, _gesture, dx, dy):
        if getattr(self, "_band", None):
            x, y = self._band[:2]
            self._band = (x, y, x + dx, y + dy)
            self.queue_draw()
            return
        if not self._drag_start:
            return
        for i, (sx, sy) in self._drag_start.items():
            if i >= len(self.points):
                continue
            p = self.points[i]
            p["freq"] = max(PEQ_FMIN, min(PEQ_FMAX, self.freq_of(sx + dx)))
            if p["type"] not in ("lowcut", "highcut"):
                p["gain"] = round(self.db_of(sy + dy) * 2) / 2  # half-dB steps
        self.on_change([dict(q) for q in self.points])
        self.queue_draw()

    def on_drag_end(self, *_):
        if getattr(self, "_band", None):
            x1, y1, x2, y2 = self._band
            self._band = None
            if abs(x2 - x1) > 4 or abs(y2 - y1) > 4:
                left, right, top, bottom = min(x1, x2), max(x1, x2), min(y1, y2), max(y1, y2)
                inside = {i for i, p in enumerate(self.points)
                          if left <= self.point_xy(p)[0] <= right and top <= self.point_xy(p)[1] <= bottom}
                self.sel = inside
                self.selected = min(inside) if inside else None
            self.queue_draw()
            return
        self.changed()

    def on_scroll(self, _c, _dx, dy):
        index = self.hover if self.hover is not None else self.selected
        if index is None or index >= len(self.points):
            return False
        targets = self.sel if index in self.sel and len(self.sel) > 1 else {index}
        for i in targets:
            p = self.points[i]
            p["q"] = max(0.1, min(18.0, p["q"] * (1.12 ** (-dy))))
        self.changed()
        return True

    def on_motion(self, _c, x, y):
        self.set_hover(self.point_at(x, y))
        self.set_cursor_from_name("grab" if self.hover is not None else "crosshair")

    def on_key(self, _c, keyval, _code, state):
        if keyval in (Gdk.KEY_Delete, Gdk.KEY_BackSpace) and (self.sel or self.selected is not None):
            self.remove_points(self.sel or {self.selected})
            return True
        if keyval in (Gdk.KEY_a, Gdk.KEY_A) and state & Gdk.ModifierType.CONTROL_MASK:
            self.select_all()
            return True
        if keyval == Gdk.KEY_Escape and self.sel:
            self.select_none()
            return True
        return False

    @staticmethod
    def one_cut_each(points, keep=None):
        """Only one low cut and one high cut: the others turn into shelves."""
        for kind, shelf in (("lowcut", "lowshelf"), ("highcut", "highshelf")):
            owners = [i for i, p in enumerate(points) if p["type"] == kind]
            if len(owners) > 1:
                first = keep if keep in owners else owners[0]
                for i in owners:
                    if i != first:
                        points[i]["type"] = shelf

    # --- the small menu of a point (the arrow); with several points selected: for all of them ---
    def open_point_menu(self):
        index = self.selected
        if index is None:
            return
        group = sorted(i for i in self.sel if i < len(self.points)) if len(self.sel) > 1 else [index]
        p = self.points[index]
        pop = Gtk.Popover()
        pop.add_css_class("peq-menu")
        # Closed by the app like its other menus (a click anywhere else, Esc), not by GTK: after
        # its Type list (Bell, Low shelf...) was opened, GTK kept the mouse and the menu no longer
        # closed on a click outside. Its number fields still take the keyboard.
        pop._p17_typing_ok = True
        grid = Gtk.Grid(column_spacing=12, row_spacing=8)
        for side in ("top", "bottom", "start", "end"):
            getattr(grid, f"set_margin_{side}")(10)
        title = f"{len(group)} points" if len(group) > 1 else f"Point {index + 1}"
        head = Gtk.Label(label=title, xalign=0)
        head.add_css_class("prefs-head")
        grid.attach(head, 0, 0, 2, 1)

        names = [n for _k, n in PEQ_TYPES]
        keys = [k for k, _n in PEQ_TYPES]
        kind = Gtk.DropDown.new_from_strings(names)
        kind.set_selected(keys.index(p["type"]))

        def spin(low, high, step, digits, value):
            sb = Gtk.SpinButton.new_with_range(low, high, step)
            sb.set_digits(digits)
            sb.set_value(value)
            return sb

        q = spin(0.1, 18.0, 0.05, 2, p["q"])
        rows = [("Type", kind)]
        if len(group) == 1:
            freq = spin(PEQ_FMIN, PEQ_FMAX, 1, 0, p["freq"])
            gain = spin(-PEQ_RANGE_DB, PEQ_RANGE_DB, 0.5, 1, p["gain"])
            rows += [("Frequency, Hz", freq), ("Gain, dB", gain)]
            gain.set_sensitive(p["type"] not in ("lowcut", "highcut"))
        else:  # several points: move all of them up / down together
            freq = None
            gain = spin(-PEQ_RANGE_DB, PEQ_RANGE_DB, 0.5, 1, 0.0)
            rows += [("Gain change, dB", gain)]
            start_gains = {i: self.points[i]["gain"] for i in group}
        rows.append(("Q", q))
        for row, (text, widget) in enumerate(rows, start=1):
            label = Gtk.Label(label=text, xalign=0)
            label.add_css_class("eq-label")
            grid.attach(label, 0, row, 1, 1)
            grid.attach(widget, 1, row, 1, 1)

        def apply(*_):
            new_type = keys[kind.get_selected()]
            for i in group:
                if i >= len(self.points):
                    continue
                point = self.points[i]
                point["type"] = new_type
                point["q"] = q.get_value()
                if len(group) == 1:
                    point["freq"] = freq.get_value()
                    point["gain"] = gain.get_value()
                else:
                    point["gain"] = start_gains[i] + gain.get_value()
                if point["type"] in ("lowcut", "highcut"):
                    point["gain"] = 0.0
                self.points[i] = peq_clean(point)
            self.one_cut_each(self.points, keep=index)
            if len(group) == 1:
                gain.set_sensitive(self.points[index]["type"] not in ("lowcut", "highcut"))
            self.changed()

        kind.connect("notify::selected", apply)
        for sb in (freq, gain, q):
            if sb is not None:
                sb.connect("value-changed", apply)

        remove = Gtk.Button(label=f"Remove {len(group)} points" if len(group) > 1 else "Remove point")
        remove.add_css_class("flat")
        remove.connect("clicked", lambda *_: (pop.popdown(), self.remove_points(group)))
        grid.attach(remove, 0, len(rows) + 1, 2, 1)

        pop.set_child(grid)
        pop.set_parent(self)
        ax, ay = self.arrow_xy()
        rect = Gdk.Rectangle()
        rect.x, rect.y, rect.width, rect.height = int(ax) - 6, int(ay) - 6, 12, 12
        pop.set_pointing_to(rect)
        pop.set_position(Gtk.PositionType.RIGHT)
        pop.connect("closed", lambda pp: GLib.idle_add(pp.unparent))
        pop.popup()

    # --- drawing ---
    @staticmethod
    def rgba(key, alpha=1.0):
        color = Gdk.RGBA()
        color.parse(COLORS[key])
        return color.red, color.green, color.blue, alpha * color.alpha

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        if w <= 2 or h <= 2:
            return
        cr = smooth_cairo(snapshot, w, h)
        x0, y0, aw, ah = self.area()
        on = self.player.eq_on

        # grid
        cr.set_line_width(1)
        cr.set_source_rgba(*self.rgba("peq_grid", 0.18))
        for f in self.GRID_FREQS:
            x = round(self.x_of(f)) + 0.5
            cr.move_to(x, y0)
            cr.line_to(x, y0 + ah)
        for db in self.GRID_DB:
            y = round(self.y_of(db)) + 0.5
            cr.move_to(x0, y)
            cr.line_to(x0 + aw, y)
        cr.stroke()
        cr.set_source_rgba(*self.rgba("peq_grid", 0.45))
        cr.set_font_size(10)
        for f in FREQ_LABELS:   # the whole range, 20 Hz to 20 kHz
            text = f"{f // 1000}k" if f >= 1000 else str(f)
            ext = cr.text_extents(text)
            x = self.x_of(f) + 3 if f < PEQ_FMAX else self.x_of(f) - ext.width - 4
            cr.move_to(x, y0 + ah - 3)
            cr.show_text(text)
        for db in (-12, 12):
            cr.move_to(x0 + 3, self.y_of(db) - 3)
            cr.show_text(f"{db:+d}")

        # live spectrum (what is playing), behind the curve
        spectrum = self.player.spectrum
        if spectrum and self.player.playing:
            step = 22050.0 / len(spectrum)
            line = []
            for i in range(1, len(spectrum)):
                f = (i + 0.5) * step
                if f < PEQ_FMIN or f > PEQ_FMAX:
                    continue
                frac = max(0.0, min(1.0, (spectrum[i] + 90) / 90))
                line.append((self.x_of(f), y0 + ah - frac * ah * 0.9))
            if line:
                # a faint body and a thin edge: visible, but the curve stays in front
                cr.move_to(line[0][0], y0 + ah)
                for x, y in line:
                    cr.line_to(x, y)
                cr.line_to(line[-1][0], y0 + ah)
                cr.close_path()
                cr.set_source_rgba(*self.rgba("peq_spectrum", 0.08))
                cr.fill()
                cr.set_line_width(1)
                for i, (x, y) in enumerate(line):
                    (cr.move_to if i == 0 else cr.line_to)(x, y)
                cr.set_source_rgba(*self.rgba("peq_spectrum", 0.30))
                cr.stroke()

        # the curve and its fill
        # The curve is worked out only when the points (or the size) change, not every frame.
        n = max(60, int(aw / 3))
        key = (n, on, tuple((p["type"], round(p["freq"], 2), round(p["gain"], 2), round(p["q"], 3)) for p in self.points))
        if getattr(self, "_curve_key", None) != key:
            freqs = [PEQ_FMIN * (PEQ_FMAX / PEQ_FMIN) ** (i / (n - 1)) for i in range(n)]
            self._curve = (freqs, peq_response_db(self.points, freqs) if on else [0.0] * n)
            self._curve_key = key
        freqs, dbs = self._curve
        zero = self.y_of(0)
        cr.move_to(self.x_of(freqs[0]), zero)
        for f, db in zip(freqs, dbs):
            cr.line_to(self.x_of(f), self.y_of(max(-PEQ_RANGE_DB * 1.2, min(PEQ_RANGE_DB * 1.2, db))))
        cr.line_to(self.x_of(freqs[-1]), zero)
        cr.close_path()
        cr.set_source_rgba(*self.rgba("peq_curve", 0.14 if on else 0.05))
        cr.fill()
        cr.set_line_width(2.2)
        cr.set_source_rgba(*self.rgba("peq_curve", 1.0 if on else 0.35))
        for i, (f, db) in enumerate(zip(freqs, dbs)):
            y = self.y_of(max(-PEQ_RANGE_DB * 1.2, min(PEQ_RANGE_DB * 1.2, db)))
            (cr.move_to if i == 0 else cr.line_to)(self.x_of(f), y)
        cr.stroke()

        # points
        for i, p in enumerate(self.points):
            px, py = self.point_xy(p)
            radius = 8 if i in (self.selected, self.hover) else 6
            cr.arc(px, py, radius + 2, 0, 2 * math.pi)
            cr.set_source_rgba(*self.rgba("bg", 1.0))
            cr.fill()
            cr.arc(px, py, radius, 0, 2 * math.pi)
            cr.set_source_rgba(*self.rgba("peq_point", 1.0 if on else 0.4))
            cr.fill_preserve()
            cr.set_line_width(2)
            cr.set_source_rgba(1, 1, 1, 0.9 if (i == self.selected or i in self.sel) else 0.0)
            cr.stroke()
            cr.set_source_rgba(0, 0, 0, 0.85)
            cr.set_font_size(9)
            label = str(i + 1)
            ext = cr.text_extents(label)
            cr.move_to(px - ext.width / 2 - ext.x_bearing, py + ext.height / 2)
            cr.show_text(label)

        # the selection frame while it is drawn
        if self._band:
            bx1, by1, bx2, by2 = self._band
            cr.rectangle(min(bx1, bx2), min(by1, by2), abs(bx2 - bx1), abs(by2 - by1))
            cr.set_source_rgba(*self.rgba("peq_point", 0.12))
            cr.fill_preserve()
            cr.set_line_width(1)
            cr.set_source_rgba(*self.rgba("peq_point", 0.8))
            cr.stroke()

        # the arrow next to the selected point, and its values
        arrow = self.arrow_xy()
        if arrow:
            ax, ay = arrow
            cr.arc(ax, ay, 8, 0, 2 * math.pi)
            cr.set_source_rgba(*self.rgba("peq_point", 0.25))
            cr.fill()
            cr.set_source_rgba(1, 1, 1, 0.95)
            cr.set_line_width(2)
            cr.move_to(ax - 2, ay - 4)
            cr.line_to(ax + 2, ay)
            cr.line_to(ax - 2, ay + 4)
            cr.stroke()
            p = self.points[self.selected]
            f = p["freq"]
            ftext = f"{f / 1000:.2f} kHz" if f >= 1000 else f"{f:.0f} Hz"
            name = dict(PEQ_TYPES)[p["type"]]
            text = f"{name}   {ftext}" + ("" if p["type"] in ("lowcut", "highcut") else f"   {p['gain']:+.1f} dB") + f"   Q {p['q']:.2f}"
            if len(self.sel) > 1:
                text = f"{len(self.sel)} points selected      " + text
            cr.set_font_size(12)
            cr.set_source_rgba(*self.rgba("peq_curve", 1.0))
            cr.move_to(x0 + 6, y0 + 14)
            cr.show_text(text)
        elif not self.points:
            cr.set_font_size(12)
            cr.set_source_rgba(*self.rgba("peq_grid", 0.6))
            cr.move_to(x0 + 6, y0 + 14)
            cr.show_text("Double click to add a point")
        if self.points and self.selected is None and not self.sel:
            cr.set_font_size(11)
            cr.set_source_rgba(*self.rgba("peq_grid", 0.45))
            cr.move_to(x0 + 6, y0 + 14)
            cr.show_text("Drag on empty space to select points   Ctrl+A: all   Delete: remove")


class Scope(Gtk.Widget):
    """Limiter display, read like Pro-L:
      - the sound going in: a thin outline (what would come out without the limiter);
      - the sound coming out: the filled part;
      - the gain reduction: a curve that hangs down from the top edge (how much is turned down);
      - the threshold: a dashed line with its value.
    The scale shows only the top 24 dB (where a limiter works); a click switches to 48 dB.
    Each layer has its own color (Color and background: Limiter in / out / reduction)."""

    __gtype_name__ = "PlyerScope"
    RANGES = (24.0, 48.0)

    HEAD_DB = 12.0   # room above 0 dB in the wave view (an input pushed hot shows how hot)

    def __init__(self, player, threshold_db, values=None):
        super().__init__()
        self.player = player
        self.threshold_db = threshold_db  # function: threshold in dB, or None
        self.values = values              # own limiter: function -> its settings (wave view)
        self.wave_linear = getattr(player, "scope_linear", True)
        self._timer = 0
        self.range_db = getattr(player, "scope_range", self.RANGES[0])
        self.set_hexpand(True)
        self.set_vexpand(True)
        self.set_tooltip_text("Outline: in   Fill: out   Curve from the top: gain reduction\n"
                              "Click: scale 24 / 48 dB")
        click = Gtk.GestureClick()
        click.connect("pressed", self._toggle_range)
        self.add_controller(click)
        self.connect("map", self._start)
        self.connect("unmap", self._stop)

    def _toggle_range(self, *_):
        if self.values is not None:   # the wave view: linear -> 24 dB -> 48 dB -> linear
            if self.wave_linear:
                self.wave_linear, self.range_db = False, self.RANGES[0]
            elif self.range_db == self.RANGES[0]:
                self.range_db = self.RANGES[1]
            else:
                self.wave_linear, self.range_db = True, self.RANGES[0]
            self.player.scope_linear = self.wave_linear
            self.player.scope_range = self.range_db
            self.queue_draw()
            return
        i = self.RANGES.index(self.range_db) if self.range_db in self.RANGES else 0
        self.range_db = self.RANGES[(i + 1) % len(self.RANGES)]
        self.player.scope_range = self.range_db  # the module keeps it while the player runs
        self.queue_draw()

    def _start(self, *_):
        # Redrawn on every frame of the screen (vsync), not on a timer: a knob move shows
        # in the very next frame, and the picture runs smoothly.
        if not self._timer:
            self._last_fill = 0.0
            self._timer = self.add_tick_callback(self._tick)

    def _stop(self, *_):
        if self._timer:
            self.remove_tick_callback(self._timer)
            self._timer = 0

    def _tick(self, _widget, clock):
        now = clock.get_frame_time() / 1_000_000
        if self.values is not None:
            pull_wave(self.player, now)
        if not self.player.playing and now - self._last_fill >= 0.033:
            self._last_fill = now
            self.player.levels.append((SCOPE_FLOOR_DB, SCOPE_FLOOR_DB, 0.0))  # runs out when paused
        self.queue_draw()
        return GLib.SOURCE_CONTINUE

    def do_measure(self, orientation, for_size):
        if orientation == Gtk.Orientation.VERTICAL:
            return 160, 180, -1, -1
        return 200, 200, -1, -1

    @staticmethod
    def rgba(key, alpha=1.0):
        color = Gdk.RGBA()
        color.parse(COLORS.get(key, "#ffffff"))
        return color.red, color.green, color.blue, alpha * color.alpha

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        if w <= 2 or h <= 2:
            return
        cr = smooth_cairo(snapshot, w, h)
        rng = self.range_db
        if self.values is not None and getattr(self.player, "wave", None) is not None:
            self.draw_wave(cr, w, h, rng)
            return

        def y_of(db):
            return h * max(0.0, min(1.0, -db / rng))      # 0 dB at the top, -range at the bottom

        # grid: every 6 dB, with labels
        cr.set_line_width(1)
        cr.set_font_size(10)
        for db in range(0, int(rng) + 1, 6 if rng <= 24 else 12):
            y = round(y_of(-db)) + 0.5
            cr.set_source_rgba(*self.rgba("peq_grid", 0.10))
            cr.move_to(0, y)
            cr.line_to(w, y)
            cr.stroke()
            if 0 < db < rng:
                cr.set_source_rgba(*self.rgba("peq_grid", 0.40))
                cr.move_to(4, y - 3)
                cr.show_text(f"-{db}")

        levels = list(self.player.levels)
        col = w / SCOPE_COLUMNS
        first = SCOPE_COLUMNS - len(levels)
        xs = [(first + k + 0.5) * col for k in range(len(levels))]

        if levels:
            # the sound coming out: filled
            cr.move_to(xs[0], h)
            for x, item in zip(xs, levels):
                cr.line_to(x, y_of(item[1]))
            cr.line_to(xs[-1], h)
            cr.close_path()
            cr.set_source_rgba(*self.rgba("lim_out", 0.55))
            cr.fill()
            # the sound going in: a thin outline above it
            cr.set_line_width(1.2)
            for i, (x, item) in enumerate(zip(xs, levels)):
                (cr.move_to if i == 0 else cr.line_to)(x, y_of(item[0]))
            cr.set_source_rgba(*self.rgba("lim_in", 0.85))
            cr.stroke()
            # gain reduction: hangs from the top, filled lightly, with a clear edge
            cr.move_to(xs[0], 0)
            for x, item in zip(xs, levels):
                cr.line_to(x, y_of(min(0.0, item[2])))
            cr.line_to(xs[-1], 0)
            cr.close_path()
            cr.set_source_rgba(*self.rgba("lim_gr", 0.25))
            cr.fill()
            cr.set_line_width(2)
            for i, (x, item) in enumerate(zip(xs, levels)):
                (cr.move_to if i == 0 else cr.line_to)(x, y_of(min(0.0, item[2])))
            cr.set_source_rgba(*self.rgba("lim_gr", 1.0))
            cr.stroke()

        # the threshold: dashed, with its value
        threshold = self.threshold_db()
        if threshold is not None:
            y = round(y_of(threshold)) + 0.5
            cr.set_dash([6, 4])
            cr.set_line_width(1.5)
            cr.set_source_rgba(*self.rgba("lines", 0.95))
            cr.move_to(0, y)
            cr.line_to(w, y)
            cr.stroke()
            cr.set_dash([])
            label = f"{threshold:+.1f} dB"
            ext = cr.text_extents(label)
            cr.move_to(w - ext.width - 6, min(h - 4, max(ext.height + 2, y - 4)))
            cr.show_text(label)


    def draw_wave(self, cr, w, h, rng):
        """The own limiter, like a scope in Bitwig / Kilohearts: the sound mirrored around the
        middle. Light blue = what goes in (after the input gain), light red = what comes out
        (after the output gain), dashed = the threshold, the curve from the top = how much is
        taken away (compressor + limiter). Click: 24 / 48 dB."""
        head = self.HEAD_DB
        mid = h / 2.0
        half = mid - 3.0
        span = rng + head
        linear = self.wave_linear

        def amp(lin):
            if linear:   # like a real oscilloscope: 0 dB at 3/4 of the height, louder above it
                if lin <= 1.0:
                    return half * 0.75 * max(0.0, lin)
                return half * (0.75 + 0.25 * min(1.0, 20.0 * math.log10(lin) / head))
            db = 20.0 * math.log10(lin) if lin > 1e-9 else -200.0
            return half * max(0.0, min(1.0, (db + rng) / span))

        def amp_db(db):
            return amp(10 ** (db / 20.0))

        # grid: 0 dB (solid) and every 6 / 12 dB, mirrored
        cr.set_line_width(1)
        cr.set_font_size(10)
        stepdb = 6 if rng <= 24 else 12
        marks = (-12, -6, 0, 6, 12) if linear else range(-int(rng) + stepdb, int(head) + 1, stepdb)
        for db in marks:
            a = amp_db(db)
            cr.set_source_rgba(*self.rgba("peq_grid", 0.20 if db == 0 else 0.07))
            for y in (mid - a, mid + a):
                cr.move_to(0, round(y) + 0.5)
                cr.line_to(w, round(y) + 0.5)
                cr.stroke()
            if db in (0, -12, -24, 12) or (linear and db == -6):
                cr.set_source_rgba(*self.rgba("peq_grid", 0.40))
                cr.move_to(4, mid - a - 3)
                cr.show_text(f"{db:+d}" if db else "0")
        cr.set_source_rgba(*self.rgba("peq_grid", 0.12))
        cr.move_to(0, round(mid) + 0.5)
        cr.line_to(w, round(mid) + 0.5)
        cr.stroke()

        wave = list(self.player.wave)
        cols = max(2, int(w))
        per = 2   # two points (about 5 ms) per pixel: a few seconds across the view
        wave = wave[-cols * per:]
        pts = []
        for k in range(0, len(wave) - per + 1, per):
            chunk = wave[k:k + per]
            pts.append((max(c[0] for c in chunk), max(c[1] for c in chunk), min(c[2] for c in chunk)))
        if len(pts) >= 2:
            x0 = w - len(pts)
            xs = [x0 + i + 0.5 for i in range(len(pts))]

            def mirrored(index, color, fill_a, line_a):
                cr.move_to(xs[0], mid - amp(pts[0][index]))
                for x, p in zip(xs, pts):
                    cr.line_to(x, mid - amp(p[index]))
                for x, p in zip(reversed(xs), reversed(pts)):
                    cr.line_to(x, mid + amp(p[index]))
                cr.close_path()
                cr.set_source_rgba(*self.rgba(color, fill_a))
                cr.fill()
                if line_a:
                    cr.set_line_width(1.0)
                    for sign in (-1, 1):
                        for i, (x, p) in enumerate(zip(xs, pts)):
                            (cr.move_to if i == 0 else cr.line_to)(x, mid + sign * amp(p[index]))
                        cr.set_source_rgba(*self.rgba(color, line_a))
                        cr.stroke()

            mirrored(0, "lim_in", 0.20, 0.55)    # in: light blue, behind
            mirrored(1, "lim_out", 0.55, 0.0)    # out: light red, in front
            # taken away: from the top edge
            cr.set_line_width(1.6)
            for i, (x, p) in enumerate(zip(xs, pts)):
                gr = -20.0 * math.log10(max(min(p[2], 1.0), 1e-6))
                (cr.move_to if i == 0 else cr.line_to)(x, min(h, gr / rng * mid))
            cr.set_source_rgba(*self.rgba("lim_gr", 0.95))
            cr.stroke()

        # the threshold, on the scale of what goes in: dashed, mirrored, with its value
        v = self.values()
        threshold = float(v.get("threshold-db", 0.0))
        a = amp_db(threshold)
        cr.set_dash([6, 4])
        cr.set_line_width(1.5)
        cr.set_source_rgba(*self.rgba("lines", 0.95))
        for y in (mid - a, mid + a):
            cr.move_to(0, round(y) + 0.5)
            cr.line_to(w, round(y) + 0.5)
            cr.stroke()
        cr.set_dash([])
        label = f"Threshold {threshold:+.1f} dB"
        ext = cr.text_extents(label)
        cr.move_to(w - ext.width - 6, max(ext.height + 2, mid - a - 4))
        cr.show_text(label)


SCOPE_CEIL_DB = 20.0 * math.log10(0.98855)   # the limiter's ceiling (-0.1 dBFS), as in the C code


def pull_wave(unit, now):
    """New scope points from the own limiter into unit.wave (once per screen frame, however
    many views ask)."""
    if getattr(unit, "_wave_at", None) == now:
        return
    unit._wave_at = now
    if getattr(unit, "wave", None) is None:
        unit.wave = deque(maxlen=4096)
    element = getattr(unit, "lv2", None)
    take = getattr(element, "scope_take", None)
    if take is None:
        return
    try:
        points = take()
    except Exception:
        points = []
    if points:
        unit.wave.extend(points)
    elif not unit.playing:
        unit.wave.append((0.0, 0.0, 1.0))  # paused: the picture runs out


class TransferView(Gtk.Widget):
    """The small square next to the scope: what the limiter does to each level (in -> out),
    with the knee, the threshold and the ceiling, and a dot where the sound is now.
    Input gain moves the dot to the right, output gain lifts the curve (up to the ceiling,
    where it bends flat), threshold and knee move and soften the bend, Density lifts the
    quiet part (the "squeeze")."""

    __gtype_name__ = "PlyerTransferView"

    def __init__(self, player, values, range_of):
        super().__init__()
        self.player = player
        self.values = values
        self.range_of = range_of   # function: the scope's range (24 / 48 dB)
        self._tick = 0
        self.trail = deque(maxlen=36)
        self.set_tooltip_text("In -> out of the limiter: the bend is the knee, dashed = threshold,\n"
                              "top line = ceiling, the dot = the sound now")
        self.connect("map", self._start)
        self.connect("unmap", self._stop)

    def _start(self, *_):
        if not self._tick:
            self._tick = self.add_tick_callback(self._on_tick)

    def _stop(self, *_):
        if self._tick:
            self.remove_tick_callback(self._tick)
            self._tick = 0

    def _on_tick(self, _w, clock):
        pull_wave(self.player, clock.get_frame_time() / 1_000_000)
        wave = getattr(self.player, "wave", None)
        if wave:
            recent = list(wave)[-8:]
            self.trail.append((max(p[0] for p in recent), max(p[1] for p in recent)))
        self.queue_draw()
        return GLib.SOURCE_CONTINUE

    def do_measure(self, orientation, for_size):
        return 150, 170, -1, -1

    def curve(self, v, x_db, peak_db):
        th = float(v.get("threshold-db", 0.0))
        out = float(v.get("output-db", 0.0))
        knee = max(0.0, float(v.get("knee-db", 0.0)))
        dens = max(0.0, min(1.0, float(v.get("density", 0.0)) / 100.0))
        post = (-th if v.get("boost", True) else 0.0) + out
        th_eff = min(th, SCOPE_CEIL_DB - post)
        x2 = x_db
        if dens > 0 and P17DSP is not None:
            x2 += float(P17DSP.p17lim_density_db(x_db, max(peak_db, x_db), th_eff, dens))
        over = x2 - th_eff
        if knee > 0 and -knee / 2 < over < knee / 2:
            g = -((over + knee / 2) ** 2) / (2 * knee)
        else:
            g = -over if over > 0 else 0.0
        y = min(x2 + g, th_eff)
        return y + post, th_eff

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        if w <= 4 or h <= 4:
            return
        cr = smooth_cairo(snapshot, w, h)
        rgba = Scope.rgba
        rng = self.range_of()
        lo, hi = -rng, Scope.HEAD_DB
        pad = 4.0
        side = min(w, h) - 2 * pad
        ox, oy = (w - side) / 2, (h - side) / 2

        def X(db):
            return ox + side * max(0.0, min(1.0, (db - lo) / (hi - lo)))

        def Y(db):
            return oy + side * (1.0 - max(0.0, min(1.0, (db - lo) / (hi - lo))))

        v = self.values()
        # frame and grid
        cr.set_line_width(1)
        cr.set_source_rgba(*rgba("peq_grid", 0.18))
        cr.rectangle(ox + 0.5, oy + 0.5, side - 1, side - 1)
        cr.stroke()
        for db in range(int(lo) + 6, int(hi), 6):
            cr.set_source_rgba(*rgba("peq_grid", 0.16 if db == 0 else 0.06))
            cr.move_to(X(db), oy)
            cr.line_to(X(db), oy + side)
            cr.move_to(ox, Y(db))
            cr.line_to(ox + side, Y(db))
            cr.stroke()
        # unity (no change), faint dashed
        cr.set_dash([3, 3])
        cr.set_source_rgba(*rgba("peq_grid", 0.25))
        cr.move_to(X(lo), Y(lo))
        cr.line_to(X(hi), Y(hi))
        cr.stroke()
        # ceiling
        cr.set_dash([])
        cr.set_source_rgba(*rgba("lim_out", 0.55))
        cr.move_to(ox, Y(SCOPE_CEIL_DB) + 0.5)
        cr.line_to(ox + side, Y(SCOPE_CEIL_DB) + 0.5)
        cr.stroke()

        wave = getattr(self.player, "wave", None)
        recent = list(wave)[-560:] if wave else []
        peak_db = 20 * math.log10(max(max((p[0] for p in recent), default=1e-6), 1e-6))
        # the curve
        steps = 90
        _y, th_eff = self.curve(v, lo, peak_db)
        cr.set_line_width(2.2)
        for i in range(steps + 1):
            x_db = lo + (hi - lo) * i / steps
            y_db, _t = self.curve(v, x_db, peak_db)
            (cr.move_to if i == 0 else cr.line_to)(X(x_db), Y(y_db))
        cr.set_source_rgba(*rgba("lines", 1.0))
        cr.stroke()
        # where the limiting starts: dashed
        cr.set_dash([5, 3])
        cr.set_line_width(1.2)
        cr.set_source_rgba(*rgba("lines", 0.8))
        cr.move_to(X(th_eff) + 0.5, oy)
        cr.line_to(X(th_eff) + 0.5, oy + side)
        cr.stroke()
        cr.set_dash([])
        # the sound now: a dot with a short fading trail (x = in after the input gain, y = out)
        trail = list(self.trail)
        for i, (vin, vout) in enumerate(trail):
            if vin <= 1e-6:
                continue
            a = (i + 1) / len(trail)
            x_db = 20 * math.log10(vin)
            y_db = 20 * math.log10(max(vout, 1e-6))
            r = 1.5 + 2.5 * a
            cr.set_source_rgba(*rgba("lim_in" if i < len(trail) - 1 else "lim_out", 0.15 + 0.85 * a ** 2))
            cr.arc(X(x_db), Y(y_db), r, 0, 2 * math.pi)
            cr.fill()
        # labels
        cr.set_font_size(9)
        cr.set_source_rgba(*rgba("peq_grid", 0.5))
        cr.move_to(ox + 4, oy + 11)
        cr.show_text("OUT")
        cr.move_to(ox + side - 18, oy + side - 4)
        cr.show_text("IN")


# ---- Solo / Mute for a band (OTT 17, the saturator's Bands): two small buttons at the bottom
# of the band, where the band is dragged. Shown on the selected band, and on any band that is
# soloed or muted, so its state is always visible.
SM_W, SM_H, SM_GAP = 22, 16, 4


def sm_rects(left, right, bottom):
    """{"solo": (x, y, w, h), "mute": (...)} centred at the bottom of a band, or {} if too narrow."""
    if right - left < 2 * SM_W + SM_GAP + 6:
        return {}
    cx, y = (left + right) / 2, bottom - SM_H - 30
    return {"solo": (cx - SM_W - SM_GAP / 2, y, SM_W, SM_H), "mute": (cx + SM_GAP / 2, y, SM_W, SM_H)}


def sm_hit(rects, x, y):
    for key, (rx, ry, rw, rh) in rects.items():
        if rx <= x <= rx + rw and ry <= y <= ry + rh:
            return key
    return None


def draw_sm(cr, rects, solo, mute, fade, rgba):
    for key, (rx, ry, rw, rh) in rects.items():
        on = solo if key == "solo" else mute
        r = 4.0
        cr.new_sub_path()
        cr.arc(rx + rw - r, ry + r, r, -math.pi / 2, 0)
        cr.arc(rx + rw - r, ry + rh - r, r, 0, math.pi / 2)
        cr.arc(rx + r, ry + rh - r, r, math.pi / 2, math.pi)
        cr.arc(rx + r, ry + r, r, math.pi, 1.5 * math.pi)
        cr.close_path()
        if on:   # solo: yellow, mute: red
            cr.set_source_rgba(*((1.0, 0.82, 0.0, fade) if key == "solo" else (1.0, 0.23, 0.19, fade)))
            cr.fill_preserve()
        cr.set_line_width(1.2)
        cr.set_source_rgba(*rgba("peq_curve", 0.9 * fade))
        cr.stroke()
        cr.set_font_size(10)
        letter = "S" if key == "solo" else "M"
        ext = cr.text_extents(letter)
        if on:
            cr.set_source_rgba(0.05, 0.05, 0.05, fade)
        else:
            cr.set_source_rgba(*rgba("peq_curve", fade))
        cr.move_to(rx + (rw - ext.width) / 2 - ext.x_bearing, ry + (rh + ext.height) / 2)
        cr.show_text(letter)


class OttView(Gtk.Widget):
    """OTT 17: the bands on the frequency picture, drawn like Prism EQ.
    In every band: the level going in (bar), what is pushed down (pink, at the top of the bar)
    or lifted up (bright, above it), the down threshold (pink line) and the up threshold (blue line).
    Classic: three fixed bands, the mouse wheel over a band sets its gain.
    Prism: also drag a crossover (vertical line) left / right, drag a threshold line up / down,
    double click on empty space adds a band, double click on a crossover removes it.
    Hard Prism: the same bands; a click selects a band, and the knobs below set how that band
    is squeezed (its own Depth, Time, Upward, Downward).
    The red line at the top: the end limiter (drag it down to limit harder)."""

    __gtype_name__ = "PlayerOttView"
    PAD = 14
    DB_BOTTOM = -66.0
    HIT = 8

    def __init__(self, ctl):
        super().__init__()
        self.ctl = ctl
        self.hover = None          # ("x", i) a crossover, ("dth" / "uth", band), ("band", band)
        self.drag = None
        self.shown = []            # displayed meters, falling slowly: [(level, change)]
        self.selected = 0          # Hard Prism: the band the knobs set
        self.limit_shown = 0.0     # the end limiter's reduction, falling slowly
        self.band_lim_shown = []   # Hard Prism: every band limiter's reduction
        self.on_select = None      # called when another band is selected
        self._tick = 0
        self.set_hexpand(True)
        self.set_vexpand(True)
        self.set_focusable(True)
        click = Gtk.GestureClick()
        click.connect("pressed", self.on_click)
        self.add_controller(click)
        drag = Gtk.GestureDrag()
        drag.connect("drag-begin", self.on_drag_begin)
        drag.connect("drag-update", self.on_drag_update)
        drag.connect("drag-end", lambda *_: (setattr(self, "drag", None), self.set_cursor_from_name("default"),
                                             self.queue_draw()))
        self.add_controller(drag)
        scroll = Gtk.EventControllerScroll(flags=Gtk.EventControllerScrollFlags.VERTICAL)
        scroll.connect("scroll", self.on_scroll)
        self.add_controller(scroll)
        motion = Gtk.EventControllerMotion()
        motion.connect("motion", self.on_motion)
        motion.connect("leave", lambda *_: self.set_hover(None))
        self.add_controller(motion)
        self.connect("map", self._start)
        self.connect("unmap", self._stop)

    # --- redrawn on every frame of the screen (rule 4) ---
    def _start(self, *_):
        self.ctl.player.set_spectrum(True)
        if not self._tick:
            self._tick = self.add_tick_callback(self._on_tick)

    def _stop(self, *_):
        self.ctl.player.set_spectrum(False)
        if self._tick:
            self.remove_tick_callback(self._tick)
            self._tick = 0

    def _on_tick(self, *_):
        live = self.ctl.player.meters() if self.ctl.player.playing else []
        n = len(self.bands()[1])
        old = self.shown + [(-120.0, 0.0)] * max(0, n - len(self.shown))
        new = []
        for i in range(n):
            lvl, gr = live[i] if i < len(live) else (-120.0, 0.0)
            slvl, sgr = old[i]
            slvl = lvl if lvl > slvl else max(lvl, slvl - 0.8)     # quick up, about 50 dB/s down
            sgr = gr if abs(gr) > abs(sgr) else sgr + (gr - sgr) * 0.25
            new.append((slvl, sgr))
        self.shown = new
        player = self.ctl.player
        gr = player.limit_gr() if player.playing and hasattr(player, "limit_gr") else 0.0
        self.limit_shown = gr if gr < self.limit_shown else self.limit_shown + (gr - self.limit_shown) * 0.15
        live_b = player.band_limit_gr() if player.playing and hasattr(player, "band_limit_gr") else []
        old_b = self.band_lim_shown + [0.0] * max(0, n - len(self.band_lim_shown))
        new_b = []
        for i in range(n):
            now = live_b[i] if i < len(live_b) else 0.0
            new_b.append(now if now < old_b[i] else old_b[i] + (now - old_b[i]) * 0.15)
        self.band_lim_shown = new_b
        if self.selected >= n:
            self.select(n - 1)
        self.queue_draw()
        return GLib.SOURCE_CONTINUE

    def do_measure(self, orientation, for_size):
        return (220, 260, -1, -1) if orientation == Gtk.Orientation.VERTICAL else (360, 600, -1, -1)

    # --- the settings ---
    @property
    def ott(self):
        return self.ctl.mod["ott"]

    def prism(self):
        """Free bands (Prism and Hard Prism)."""
        return self.ott["mode"] in ("prism", "hard")

    def hard(self):
        return self.ott["mode"] == "hard"

    def limit_db(self):
        return -OTT_LIMIT_DB * (1.0 - float(self.ott.get("limit", 1.0)))

    def band_limit_db(self, band):
        values = self.ott["amounts"]["limit"]
        return -OTT_LIMIT_DB * (1.0 - float(values[band])) if 0 <= band < len(values) else 0.0

    def select(self, band):
        band = max(0, band)
        if band != self.selected:
            self.selected = band
            if self.on_select is not None:
                self.on_select(band)
        self.queue_draw()

    def amounts(self):
        return {k: list(v) for k, v in self.ott["amounts"].items()}

    def bands(self):
        """(crossovers, gains, down thresholds, up thresholds) as shown now."""
        xs, gains, dth, uth, _a, _r = ott_bands(self.ott)
        return list(xs), list(gains), list(dth), list(uth)

    # --- coordinates (the same frequency scale as Prism EQ) ---
    def area(self):
        w, h = self.get_width(), self.get_height()
        return self.PAD, self.PAD, max(1, w - 2 * self.PAD), max(1, h - 2 * self.PAD)

    def x_of(self, freq):
        x0, _y0, w, _h = self.area()
        return x0 + w * (math.log10(freq / PEQ_FMIN) / math.log10(PEQ_FMAX / PEQ_FMIN))

    def freq_of(self, x):
        x0, _y0, w, _h = self.area()
        return PEQ_FMIN * (PEQ_FMAX / PEQ_FMIN) ** max(0.0, min(1.0, (x - x0) / w))

    def y_of(self, db):
        _x0, y0, _w, h = self.area()
        return y0 + h * max(0.0, min(1.0, db / self.DB_BOTTOM))

    def db_of(self, y):
        _x0, y0, _w, h = self.area()
        return max(self.DB_BOTTOM, min(0.0, (y - y0) / h * self.DB_BOTTOM))

    def band_at(self, x):
        xs = self.bands()[0]
        f = self.freq_of(x)
        return sum(1 for c in xs if f > c)

    def edges(self):
        return [PEQ_FMIN] + self.bands()[0] + [PEQ_FMAX]

    def thing_at(self, x, y):
        xs, _g, dth, uth = self.bands()
        band = self.band_at(x)
        if self.hard():   # every band its own red line
            if abs(self.y_of(self.band_limit_db(band)) - y) <= self.HIT:
                return ("blim", band)
        elif abs(self.y_of(self.limit_db()) - y) <= self.HIT:
            return ("lim", 0)
        if self.prism():
            for i, f in enumerate(xs):
                if abs(self.x_of(f) - x) <= self.HIT:
                    return ("x", i)
            if abs(self.y_of(dth[band]) - y) <= self.HIT:
                return ("dth", band)
            if abs(self.y_of(uth[band]) - y) <= self.HIT:
                return ("uth", band)
        if self.hard():
            return ("move", band)   # the middle of a band: drag the whole band
        return ("band", band)

    # --- changes go through the module (saved, sent to the sound) ---
    def put(self, xs=None, gains=None, dth=None, uth=None, amounts=None):
        _xs, _g, _d, _u = self.bands()
        if self.prism():
            self.ctl.set_ott_prism({"x": xs if xs is not None else _xs, "gain": gains if gains is not None else _g,
                                    "dth": dth if dth is not None else _d, "uth": uth if uth is not None else _u},
                                   amounts)
        elif gains is not None:
            self.ctl.set_ott_value("classic_gain", gains)
        self.queue_draw()

    def set_hover(self, thing):
        if thing != self.hover:
            self.hover = thing
            self.queue_draw()

    def on_motion(self, _c, x, y):
        thing = self.thing_at(x, y)
        self.set_hover(thing)
        cursor = {"x": "col-resize", "dth": "row-resize", "uth": "row-resize", "lim": "row-resize",
                  "blim": "row-resize", "move": "grab"}.get(thing[0], "default")
        self.set_cursor_from_name(cursor)

    def sm_of(self, band):
        """The Solo / Mute buttons of a band, where they are drawn (or {})."""
        edges = self.edges()
        if band >= len(edges) - 1:
            return {}
        a = self.ott["amounts"]
        shown = band == self.selected or a["mute"][band] > 0.5 or a["solo"][band] > 0.5
        _x0, y0, _w, ah = self.area()
        return sm_rects(self.x_of(edges[band]), self.x_of(edges[band + 1]), y0 + ah) if shown else {}

    def toggle_sm(self, band, key):
        a = self.amounts()
        a[key][band] = 0.0 if a[key][band] > 0.5 else 1.0
        if key == "solo" and a[key][band] > 0.5:
            a["mute"][band] = 0.0     # soloing a muted band un-mutes it
        self.put(amounts=a)

    def on_click(self, gesture, n_press, x, y):
        self.grab_focus()
        band = self.band_at(x)
        hit = sm_hit(self.sm_of(band), x, y)
        if hit:
            if n_press == 1:
                self.toggle_sm(band, hit)
            return
        thing = self.thing_at(x, y)
        if n_press == 1 and thing[0] not in ("x", "lim"):
            self.select(band)                    # its knobs below (Hard Prism), its Solo / Mute
        if n_press == 2 and thing[0] == "lim":
            self.ctl.set_ott_value("limit", 1.0)  # double click on the red line: back to 0 dB
            return
        if n_press == 2 and thing[0] == "blim":
            self.ctl.set_ott_band_amount("limit", thing[1], 1.0)
            self.sync_knobs()
            return
        if n_press != 2 or not self.prism():
            return
        xs, gains, dth, uth = self.bands()
        amounts = self.amounts()
        if thing[0] == "x":                      # remove this crossover: the two bands become one
            if len(xs) <= 1:
                return
            i = thing[1]
            del xs[i]
            del gains[i + 1], dth[i + 1], uth[i + 1]
            for values in amounts.values():
                del values[i + 1]
        else:                                    # a new crossover here: the band is cut in two
            if len(xs) >= OTT_MAX_BANDS - 1:
                self.ctl.flash_title(f"OTT 17: at most {OTT_MAX_BANDS} bands")
                return
            f = self.freq_of(x)
            if any(abs(math.log10(f / c)) < 0.08 for c in xs) or not XO_MIN <= f <= XO_MAX:
                return
            band = self.band_at(x)
            xs.insert(band, f)
            gains.insert(band, gains[band])
            dth.insert(band, dth[band])
            uth.insert(band, uth[band])
            for values in amounts.values():   # the new band starts as the one it was cut from
                values.insert(band, values[band])
        self.put(xs, gains, dth, uth, amounts)

    def sync_knobs(self):
        ui = getattr(self.ctl, "ui", None)
        if ui is not None and hasattr(ui, "sync_ott_knobs"):
            ui.sync_ott_knobs()

    def on_drag_begin(self, gesture, x, y):
        if sm_hit(self.sm_of(self.band_at(x)), x, y):
            self.drag = None
            return
        thing = self.thing_at(x, y)
        if thing[0] in ("lim", "blim", "move"):
            gesture.set_state(Gtk.EventSequenceState.CLAIMED)
            self.drag = (thing, x, y)
            if thing[0] == "move":
                self.drag_xs = list(self.bands()[0])   # where the band's edges were
                self.set_cursor_from_name("grabbing")
            if thing[0] != "lim":
                self.select(thing[1])
            return
        if not self.prism() or thing[0] == "band":
            self.drag = None
            return
        gesture.set_state(Gtk.EventSequenceState.CLAIMED)
        self.drag = (thing, x, y)

    def on_drag_update(self, _g, dx, dy):
        if self.drag is None:
            return
        (kind, i), x, y = self.drag
        if kind in ("lim", "blim"):
            db = max(-OTT_LIMIT_DB, min(0.0, self.db_of(y + dy)))
            value = round((1.0 + db / OTT_LIMIT_DB) * 200) / 200
            if kind == "lim":
                self.ctl.set_ott_value("limit", value)
            else:
                self.ctl.set_ott_band_amount("limit", i, value)
            self.sync_knobs()
            self.queue_draw()
            return
        if kind == "move":
            # The whole band slides: both its edges move together (on the log scale, so the
            # band keeps its width in octaves), never past the neighbours' edges.
            xs = list(self.drag_xs)
            _x0, _y0, aw, _h = self.area()
            shift = dx / aw * math.log10(PEQ_FMAX / PEQ_FMIN)   # in decades
            edges = [j for j in (i - 1, i) if 0 <= j < len(xs)]
            if not edges:
                return
            low_lim = math.log10(xs[edges[0] - 1] * 1.2) if edges[0] > 0 else math.log10(XO_MIN)
            high_lim = math.log10(xs[edges[-1] + 1] / 1.2) if edges[-1] + 1 < len(xs) else math.log10(XO_MAX)
            lo, hi = math.log10(xs[edges[0]]), math.log10(xs[edges[-1]])
            shift = max(low_lim - lo, min(high_lim - hi, shift))
            for j in edges:
                xs[j] = 10 ** (math.log10(xs[j]) + shift)
            self.put(xs=xs)
            self.sync_knobs()   # the band label shows its new edges
            return
        xs, gains, dth, uth = self.bands()
        if kind == "x":
            low = xs[i - 1] * 1.2 if i > 0 else XO_MIN
            high = xs[i + 1] / 1.2 if i + 1 < len(xs) else XO_MAX
            xs[i] = max(low, min(high, self.freq_of(x + dx)))
        elif kind == "dth":
            dth[i] = round(max(uth[i] + 1.0, min(0.0, self.db_of(y + dy))) * 2) / 2
        else:
            uth[i] = round(min(dth[i] - 1.0, max(-80.0, self.db_of(y + dy))) * 2) / 2
        self.put(xs, gains, dth, uth)

    def on_scroll(self, _c, _dx, dy):
        band = self.hover[1] if self.hover and self.hover[0] not in ("x", "lim") else None
        if band is None:
            return False
        gains = self.bands()[1]
        gains[band] = max(-OTT_GAIN_DB, min(OTT_GAIN_DB, round((gains[band] - dy * 0.5) * 2) / 2))
        self.put(gains=gains)
        return True

    # --- drawing ---
    @staticmethod
    def rgba(key, alpha=1.0):
        color = Gdk.RGBA()
        color.parse(COLORS[key])
        return color.red, color.green, color.blue, alpha * color.alpha

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        if w <= 2 or h <= 2:
            return
        cr = smooth_cairo(snapshot, w, h)
        x0, y0, aw, ah = self.area()
        on = self.ctl.player.eq_on
        xs, gains, dth, uth = self.bands()
        edges = [PEQ_FMIN] + xs + [PEQ_FMAX]

        # grid
        cr.set_line_width(1)
        cr.set_source_rgba(*self.rgba("peq_grid", 0.18))
        for f in PrismEQ.GRID_FREQS:
            x = round(self.x_of(f)) + 0.5
            cr.move_to(x, y0)
            cr.line_to(x, y0 + ah)
        for db in range(0, int(self.DB_BOTTOM) - 1, -12):
            y = round(self.y_of(db)) + 0.5
            cr.move_to(x0, y)
            cr.line_to(x0 + aw, y)
        cr.stroke()
        cr.set_source_rgba(*self.rgba("peq_grid", 0.45))
        cr.set_font_size(10)
        for f in FREQ_LABELS:   # the whole range, 20 Hz to 20 kHz
            text = f"{f // 1000}k" if f >= 1000 else str(f)
            ext = cr.text_extents(text)
            x = self.x_of(f) + 3 if f < PEQ_FMAX else self.x_of(f) - ext.width - 4
            cr.move_to(x, y0 + ah - 3)
            cr.show_text(text)
        for db in (-12, -24, -36, -48, -60):
            cr.move_to(x0 + 3, self.y_of(db) - 3)
            cr.show_text(str(db))

        # what goes in, faint, behind everything
        spectrum = self.ctl.player.spectrum
        if spectrum and self.ctl.player.playing:
            step = 22050.0 / len(spectrum)
            cr.set_line_width(1)
            first = True
            for i in range(1, len(spectrum)):
                f = (i + 0.5) * step
                if PEQ_FMIN <= f <= PEQ_FMAX:
                    y = self.y_of(max(self.DB_BOTTOM, spectrum[i] + 6))
                    (cr.move_to if first else cr.line_to)(self.x_of(f), y)
                    first = False
            cr.set_source_rgba(*self.rgba("peq_spectrum", 0.25))
            cr.stroke()

        # the bands
        fade = 1.0 if on else 0.4
        for b in range(len(gains)):
            left, right = self.x_of(edges[b]), self.x_of(edges[b + 1])
            mid = (left + right) / 2
            if self.hover and self.hover[0] not in ("x", "lim") and self.hover[1] == b:
                cr.rectangle(left, y0, right - left, ah)
                cr.set_source_rgba(*self.rgba("peq_curve", 0.05))
                cr.fill()
            if self.hard() and b == self.selected:   # the band the knobs set
                cr.rectangle(left + 1, y0 + 1, right - left - 2, ah - 2)
                cr.set_source_rgba(*self.rgba("peq_curve", 0.08))
                cr.fill_preserve()
                cr.set_line_width(1.5)
                cr.set_source_rgba(*self.rgba("lines", 0.7 * fade))
                cr.stroke()
            # the level bar and what the band does to it
            lvl, gr = self.shown[b] if b < len(self.shown) else (-120.0, 0.0)
            bar = max(6.0, min(28.0, (right - left) * 0.45))
            if lvl > self.DB_BOTTOM:
                cr.rectangle(mid - bar / 2, self.y_of(lvl), bar, y0 + ah - self.y_of(lvl))
                cr.set_source_rgba(*self.rgba("peq_curve", 0.28 * fade))
                cr.fill()
                if gr < -0.2:      # pushed down: pink, from the level down
                    cr.rectangle(mid - bar / 2, self.y_of(lvl), bar, self.y_of(lvl + gr) - self.y_of(lvl))
                    cr.set_source_rgba(*self.rgba("lines", 0.85 * fade))
                    cr.fill()
                elif gr > 0.2:     # lifted up: bright, above the level
                    cr.rectangle(mid - bar / 2, self.y_of(min(0.0, lvl + gr)), bar,
                                 self.y_of(lvl) - self.y_of(min(0.0, lvl + gr)))
                    cr.set_source_rgba(*self.rgba("peq_curve", 0.9 * fade))
                    cr.fill()
            # the thresholds
            for key, values, color in (("dth", dth, "lines"), ("uth", uth, "peq_curve")):
                y = round(self.y_of(values[b])) + 0.5
                strong = self.hover == (key, b) or (self.drag and self.drag[0] == (key, b))
                cr.set_line_width(3 if strong else 2)
                if not self.prism():
                    cr.set_dash([5, 4])
                cr.set_source_rgba(*self.rgba(color, (1.0 if strong else 0.8) * fade))
                cr.move_to(left + 3, y)
                cr.line_to(right - 3, y)
                cr.stroke()
                cr.set_dash([])
                if strong:
                    cr.set_font_size(10)
                    cr.move_to(left + 6, y - 4)
                    cr.show_text(f"{values[b]:.1f} dB")
            # the band's gain, on top
            cr.set_font_size(11)
            text = f"{gains[b]:+.1f} dB"
            ext = cr.text_extents(text)
            cr.set_source_rgba(*self.rgba("peq_curve", fade))
            cr.move_to(mid - ext.width / 2 - ext.x_bearing, y0 + 14)
            cr.show_text(text)

        # the crossovers
        for i, f in enumerate(xs):
            x = round(self.x_of(f)) + 0.5
            strong = self.hover == ("x", i) or (self.drag and self.drag[0] == ("x", i))
            cr.set_line_width(3 if strong else 2)
            cr.set_source_rgba(*self.rgba("peq_point", (1.0 if strong else 0.75) * fade))
            cr.move_to(x, y0 + 20)
            cr.line_to(x, y0 + ah)
            cr.stroke()
            if self.prism():
                cr.arc(x, y0 + 26, 5 if strong else 4, 0, 2 * math.pi)
                cr.fill()
            if strong:
                cr.set_font_size(11)
                cr.move_to(x + 6, y0 + 30)
                cr.show_text(f"{f / 1000:.2f} kHz" if f >= 1000 else f"{f:.0f} Hz")

        if self.hard():   # every band its own red line, with what it takes away now
            for b in range(len(gains)):
                left, right = self.x_of(edges[b]), self.x_of(edges[b + 1])
                bly = round(self.y_of(self.band_limit_db(b))) + 0.5
                bstrong = self.hover == ("blim", b) or (self.drag and self.drag[0] == ("blim", b))
                cut = self.band_lim_shown[b] if b < len(self.band_lim_shown) else 0.0
                bworking = cut < -0.1
                cr.set_line_width(3 if bstrong else 2)
                cr.set_source_rgba(1.0, 0.23, 0.19, (1.0 if bstrong or bworking else 0.7) * fade)
                cr.move_to(left + 3, bly)
                cr.line_to(right - 3, bly)
                cr.stroke()
                if bworking:
                    cr.rectangle(left + 3, bly, right - left - 6, min(ah * 0.25, -cut * 4))
                    cr.set_source_rgba(1.0, 0.23, 0.19, 0.18 * fade)
                    cr.fill()
                if bstrong or bworking or b == self.selected:
                    cr.set_font_size(10)
                    cr.set_source_rgba(1.0, 0.35, 0.3, fade)
                    label = f"{self.band_limit_db(b):+.1f}" + (f"  {cut:.1f}" if bworking else "")
                    cr.move_to(left + 6, bly + 12 if bly < y0 + 24 else bly - 4)
                    cr.show_text(label)
        # Solo / Mute at the bottom of the selected band (and of every soloed / muted one);
        # a band that is not heard is dimmed
        amounts = self.ott["amounts"]
        heard = band_audible(amounts["mute"][:len(gains)], amounts["solo"][:len(gains)])
        for b in range(len(gains)):
            left, right = self.x_of(edges[b]), self.x_of(edges[b + 1])
            if heard[b] < 0.5:
                cr.rectangle(left, y0, right - left, ah)
                cr.set_source_rgba(0, 0, 0, 0.45)
                cr.fill()
            draw_sm(cr, self.sm_of(b), amounts["solo"][b] > 0.5, amounts["mute"][b] > 0.5, fade, self.rgba)
        # the end limiter (Prism only): a red line, with what it takes away now
        ly = round(self.y_of(self.limit_db())) + 0.5
        strong = self.hover == ("lim", 0) or (self.drag and self.drag[0] == ("lim", 0))
        working = self.limit_shown < -0.1
        show_end = not self.hard()
        cr.set_line_width(3 if strong else 2)
        cr.set_source_rgba(1.0, 0.23, 0.19, (1.0 if strong or working else 0.75) * fade)
        if show_end:
            cr.move_to(x0, ly)
            cr.line_to(x0 + aw, ly)
            cr.stroke()
        if show_end and working:   # how much it is limiting: a red glow under the line
            depth_px = min(ah * 0.25, -self.limit_shown * 4)
            cr.rectangle(x0, ly, aw, depth_px)
            cr.set_source_rgba(1.0, 0.23, 0.19, 0.18 * fade)
            cr.fill()
        if show_end:
            cr.set_font_size(10)
            cr.set_source_rgba(1.0, 0.35, 0.3, fade)
            text = f"Limit {self.limit_db():+.1f} dB" + (f"   {self.limit_shown:.1f} dB" if working else "")
            ext = cr.text_extents(text)
            cr.move_to(x0 + aw - ext.width - 6, ly + 12 if ly < y0 + 24 else ly - 4)
            cr.show_text(text)

        # a short hint
        cr.set_font_size(11)
        cr.set_source_rgba(*self.rgba("peq_grid", 0.45))
        cr.move_to(x0 + 6, y0 + ah - 16)
        cr.show_text("Click a band: its knobs   Drag its middle: move it   Drag edges, thresholds, red line   "
                     "Double click: add / remove"
                     if self.hard() else
                     "Drag lines: crossovers and thresholds   Double click: add / remove a band   Wheel: band gain"
                     if self.prism() else "Mouse wheel over a band: its gain   Prism: free bands")


class SatBandsView(Gtk.Widget):
    """Prism Saturator 17, Bands mode: the bands on the frequency picture (as OTT 17).
    The height of a band is its drive; the thin bar in it is how hard the sound hits the
    saturation now (pink above 0 dB: that is where it really saturates).
    Click a band: its knobs show below.  Drag inside a band up / down: its drive.  Wheel: drive.
    Drag a crossover: move it.  Double click: add a band / remove a crossover."""

    __gtype_name__ = "PlayerSatBandsView"
    PAD = 14
    HIT = 8

    def __init__(self, ctl, on_select):
        super().__init__()
        self.ctl = ctl
        self.on_select = on_select
        self.selected = 0
        self.hover = None
        self.drag = None
        self.shown = []
        self._tick = 0
        self.set_hexpand(True)
        self.set_vexpand(True)
        self.set_focusable(True)
        click = Gtk.GestureClick()
        click.connect("pressed", self.on_click)
        self.add_controller(click)
        drag = Gtk.GestureDrag()
        drag.connect("drag-begin", self.on_drag_begin)
        drag.connect("drag-update", self.on_drag_update)
        drag.connect("drag-end", lambda *_: setattr(self, "drag", None) or self.queue_draw())
        self.add_controller(drag)
        scroll = Gtk.EventControllerScroll(flags=Gtk.EventControllerScrollFlags.VERTICAL)
        scroll.connect("scroll", self.on_scroll)
        self.add_controller(scroll)
        motion = Gtk.EventControllerMotion()
        motion.connect("motion", self.on_motion)
        motion.connect("leave", lambda *_: self.set_hover(None))
        self.add_controller(motion)
        self.connect("map", self._start)
        self.connect("unmap", self._stop)

    def _start(self, *_):
        self.ctl.player.set_spectrum(True)
        if not self._tick:
            self._tick = self.add_tick_callback(self._on_tick)

    def _stop(self, *_):
        self.ctl.player.set_spectrum(False)
        if self._tick:
            self.remove_tick_callback(self._tick)
            self._tick = 0

    def _on_tick(self, *_):
        live = self.ctl.player.meters() if self.ctl.player.playing else []
        n = len(self.bands()["drive"])
        old = self.shown + [-120.0] * max(0, n - len(self.shown))
        new = []
        for i in range(n):
            hit = live[i] if i < len(live) else -120.0
            new.append(hit if hit > old[i] else max(hit, old[i] - 0.8))   # quick up, slowly down
        self.shown = new
        self.queue_draw()
        return GLib.SOURCE_CONTINUE

    def do_measure(self, orientation, for_size):
        return (220, 260, -1, -1) if orientation == Gtk.Orientation.VERTICAL else (360, 600, -1, -1)

    def bands(self):
        return json.loads(json.dumps(self.ctl.mod["sat"]["bands"]))

    def area(self):
        w, h = self.get_width(), self.get_height()
        return self.PAD, self.PAD, max(1, w - 2 * self.PAD), max(1, h - 2 * self.PAD)

    def x_of(self, freq):
        x0, _y0, w, _h = self.area()
        return x0 + w * (math.log10(freq / PEQ_FMIN) / math.log10(PEQ_FMAX / PEQ_FMIN))

    def freq_of(self, x):
        x0, _y0, w, _h = self.area()
        return PEQ_FMIN * (PEQ_FMAX / PEQ_FMIN) ** max(0.0, min(1.0, (x - x0) / w))

    def y_of(self, amount):            # drive 0..1: bottom .. top
        _x0, y0, _w, h = self.area()
        return y0 + h * (1.0 - max(0.0, min(1.0, amount)))

    def amount_of(self, y):
        _x0, y0, _w, h = self.area()
        return max(0.0, min(1.0, 1.0 - (y - y0) / h))

    def band_at(self, x):
        f = self.freq_of(x)
        return sum(1 for c in self.bands()["x"] if f > c)

    def thing_at(self, x, _y):
        for i, f in enumerate(self.bands()["x"]):
            if abs(self.x_of(f) - x) <= self.HIT:
                return ("x", i)
        return ("band", self.band_at(x))

    def select(self, band):
        n = len(self.bands()["drive"])
        self.selected = max(0, min(n - 1, band))
        self.on_select(self.selected)
        self.queue_draw()

    def put(self, bands):
        self.ctl.set_sat_bands(bands)
        self.queue_draw()

    def set_hover(self, thing):
        if thing != self.hover:
            self.hover = thing
            self.queue_draw()

    def on_motion(self, _c, x, y):
        thing = self.thing_at(x, y)
        self.set_hover(thing)
        self.set_cursor_from_name("col-resize" if thing[0] == "x" else "row-resize")

    def sm_of(self, band):
        b = self.bands()
        edges = [PEQ_FMIN] + b["x"] + [PEQ_FMAX]
        if band >= len(edges) - 1:
            return {}
        shown = band == self.selected or b["mute"][band] > 0.5 or b["solo"][band] > 0.5
        _x0, y0, _w, ah = self.area()
        return sm_rects(self.x_of(edges[band]), self.x_of(edges[band + 1]), y0 + ah) if shown else {}

    def on_click(self, _gesture, n_press, x, y):
        self.grab_focus()
        band = self.band_at(x)
        hit = sm_hit(self.sm_of(band), x, y)
        if hit:
            if n_press == 1:
                b = self.bands()
                b[hit][band] = 0.0 if b[hit][band] > 0.5 else 1.0
                if hit == "solo" and b[hit][band] > 0.5:
                    b["mute"][band] = 0.0
                self.put(b)
            return
        thing = self.thing_at(x, y)
        if n_press == 1:
            if thing[0] == "band":
                self.select(thing[1])
            return
        if n_press != 2:
            return
        b = self.bands()
        if thing[0] == "x":                      # remove the crossover: two bands become one
            if len(b["x"]) <= 1:
                return
            i = thing[1]
            del b["x"][i]
            for key in ("drive", "type", "mix", "out", "mute", "solo"):
                del b[key][i + 1]
        else:                                    # a new crossover: the band is cut in two, same settings
            if len(b["x"]) >= OTT_MAX_BANDS - 1:
                self.ctl.flash_title(f"At most {OTT_MAX_BANDS} bands")
                return
            f = self.freq_of(x)
            if any(abs(math.log10(f / c)) < 0.08 for c in b["x"]) or not XO_MIN <= f <= XO_MAX:
                return
            band = self.band_at(x)
            b["x"].insert(band, f)
            for key in ("drive", "type", "mix", "out", "mute", "solo"):
                b[key].insert(band, b[key][band])
        self.put(b)
        self.select(self.selected)

    def on_drag_begin(self, gesture, x, y):
        if sm_hit(self.sm_of(self.band_at(x)), x, y):
            self.drag = None
            return
        gesture.set_state(Gtk.EventSequenceState.CLAIMED)
        thing = self.thing_at(x, y)
        if thing[0] == "band":
            self.select(thing[1])
        self.drag = (thing, x, y)

    def on_drag_update(self, _g, dx, dy):
        if self.drag is None or (abs(dx) < 2 and abs(dy) < 2):
            return
        (kind, i), x, y = self.drag
        b = self.bands()
        if kind == "x":
            low = b["x"][i - 1] * 1.2 if i > 0 else XO_MIN
            high = b["x"][i + 1] / 1.2 if i + 1 < len(b["x"]) else XO_MAX
            b["x"][i] = max(low, min(high, self.freq_of(x + dx)))
        else:
            b["drive"][i] = round(self.amount_of(y + dy) * 200) / 200
        self.put(b)
        if kind == "band":
            self.on_select(i)

    def on_scroll(self, _c, _dx, dy):
        if not self.hover or self.hover[0] != "band":
            return False
        i = self.hover[1]
        b = self.bands()
        b["drive"][i] = max(0.0, min(1.0, b["drive"][i] - dy * 0.02))
        self.put(b)
        self.select(i)
        return True

    @staticmethod
    def rgba(key, alpha=1.0):
        color = Gdk.RGBA()
        color.parse(COLORS[key])
        return color.red, color.green, color.blue, alpha * color.alpha

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        if w <= 2 or h <= 2:
            return
        cr = smooth_cairo(snapshot, w, h)
        x0, y0, aw, ah = self.area()
        fade = 1.0 if self.ctl.player.eq_on else 0.4
        b = self.bands()
        edges = [PEQ_FMIN] + b["x"] + [PEQ_FMAX]
        names = dict(SAT_TYPES)

        # grid: the frequencies, and the drive every 12 dB
        cr.set_line_width(1)
        cr.set_source_rgba(*self.rgba("peq_grid", 0.18))
        for f in PrismEQ.GRID_FREQS:
            x = round(self.x_of(f)) + 0.5
            cr.move_to(x, y0)
            cr.line_to(x, y0 + ah)
        for db in (12, 24):
            y = round(self.y_of(db / SAT_DRIVE_DB)) + 0.5
            cr.move_to(x0, y)
            cr.line_to(x0 + aw, y)
        cr.stroke()
        cr.set_source_rgba(*self.rgba("peq_grid", 0.45))
        cr.set_font_size(10)
        for f in FREQ_LABELS:   # the whole range, 20 Hz to 20 kHz
            text = f"{f // 1000}k" if f >= 1000 else str(f)
            ext = cr.text_extents(text)
            x = self.x_of(f) + 3 if f < PEQ_FMAX else self.x_of(f) - ext.width - 4
            cr.move_to(x, y0 + ah - 3)
            cr.show_text(text)
        for db in (12, 24):
            cr.move_to(x0 + 3, self.y_of(db / SAT_DRIVE_DB) - 3)
            cr.show_text(f"+{db} dB")

        spectrum = self.ctl.player.spectrum
        if spectrum and self.ctl.player.playing:
            step = 22050.0 / len(spectrum)
            first = True
            for i in range(1, len(spectrum)):
                f = (i + 0.5) * step
                if PEQ_FMIN <= f <= PEQ_FMAX:
                    frac = max(0.0, min(1.0, (spectrum[i] + 90) / 90))
                    (cr.move_to if first else cr.line_to)(self.x_of(f), y0 + ah - frac * ah * 0.9)
                    first = False
            cr.set_line_width(1)
            cr.set_source_rgba(*self.rgba("peq_spectrum", 0.25))
            cr.stroke()

        for i in range(len(b["drive"])):
            left, right = self.x_of(edges[i]), self.x_of(edges[i + 1])
            mid = (left + right) / 2
            sel = i == self.selected
            top = self.y_of(b["drive"][i])
            # the drive: the band filled up to it
            cr.rectangle(left + 1, top, right - left - 2, y0 + ah - top)
            cr.set_source_rgba(*self.rgba("peq_curve", (0.26 if sel else 0.14) * fade))
            cr.fill()
            cr.set_line_width(2.2)
            cr.set_source_rgba(*self.rgba("peq_curve", fade))
            cr.move_to(left + 2, top)
            cr.line_to(right - 2, top)
            cr.stroke()
            if sel:
                cr.set_line_width(1.5)
                cr.rectangle(left + 1.5, y0 + 0.5, right - left - 3, ah - 1)
                cr.set_source_rgba(*self.rgba("peq_point", 0.8 * fade))
                cr.stroke()
            # how hard it hits the saturation now: -48..+12 dB, pink above 0 dB
            hit = self.shown[i] if i < len(self.shown) else -120.0
            if hit > -48:
                bar = max(4.0, min(10.0, (right - left) * 0.12))
                frac = lambda db: max(0.0, min(1.0, (db + 48) / 60))
                y_hit, y_zero = y0 + ah * (1 - frac(hit)), y0 + ah * (1 - frac(0.0))
                cr.rectangle(mid - bar / 2, max(y_hit, y_zero), bar, y0 + ah - max(y_hit, y_zero))
                cr.set_source_rgba(*self.rgba("peq_spectrum", 0.6 * fade))
                cr.fill()
                if hit > 0:
                    cr.rectangle(mid - bar / 2, y_hit, bar, y_zero - y_hit)
                    cr.set_source_rgba(*self.rgba("lines", fade))
                    cr.fill()
            # type and drive, on top
            cr.set_font_size(11)
            text = f"{names[b['type'][i]]}  {b['drive'][i] * SAT_DRIVE_DB:+.0f} dB"
            if b["mix"][i] < 0.995:
                text += f"  {b['mix'][i] * 100:.0f}%"
            ext = cr.text_extents(text)
            if ext.width > right - left - 6:
                text = names[b["type"][i]]
                ext = cr.text_extents(text)
            cr.set_source_rgba(*self.rgba("peq_curve", fade))
            cr.move_to(mid - ext.width / 2 - ext.x_bearing, y0 + 14)
            cr.show_text(text)

        heard = band_audible(b["mute"], b["solo"])
        for i in range(len(b["drive"])):   # Solo / Mute; a band not heard is dimmed
            left, right = self.x_of(edges[i]), self.x_of(edges[i + 1])
            if heard[i] < 0.5:
                cr.rectangle(left, y0, right - left, ah)
                cr.set_source_rgba(0, 0, 0, 0.45)
                cr.fill()
            draw_sm(cr, self.sm_of(i), b["solo"][i] > 0.5, b["mute"][i] > 0.5, fade, self.rgba)

        for i, f in enumerate(b["x"]):
            x = round(self.x_of(f)) + 0.5
            strong = self.hover == ("x", i) or (self.drag and self.drag[0] == ("x", i))
            cr.set_line_width(3 if strong else 2)
            cr.set_source_rgba(*self.rgba("peq_point", (1.0 if strong else 0.75) * fade))
            cr.move_to(x, y0 + 20)
            cr.line_to(x, y0 + ah)
            cr.stroke()
            cr.arc(x, y0 + 26, 5 if strong else 4, 0, 2 * math.pi)
            cr.fill()
            if strong:
                cr.set_font_size(11)
                cr.move_to(x + 6, y0 + 30)
                cr.show_text(f"{f / 1000:.2f} kHz" if f >= 1000 else f"{f:.0f} Hz")

        cr.set_font_size(11)
        cr.set_source_rgba(*self.rgba("peq_grid", 0.45))
        cr.move_to(x0 + 6, y0 + ah - 16)
        cr.show_text("Drag a band up / down: drive   Drag lines: crossovers   Double click: add / remove a band")


class FlatBar(Gtk.Widget):
    """A flat level bar in the style of the Vital synth: no knob, a thin line that fills up.
    Click or drag: set the level.  Mouse wheel: finer steps.  Double click: 100%."""

    __gtype_name__ = "PlyerFlatBar"
    TEXT_W = 34  # room on the right for the "73%"

    def __init__(self, value, on_change, width=110, fmt=None, default=1.0, tip="Volume"):
        super().__init__()
        self.value = max(0.0, min(1.0, float(value)))
        self.on_change = on_change
        self.bar_width = width
        self.text_w = 54 if fmt else self.TEXT_W          # a "+3.5 dB" needs more room
        self.fmt = fmt or (lambda v: f"{v * 100:.0f}%")   # the number shown on the right
        self.default = default                            # double click goes back here
        self.tip = tip
        self.hover = False
        self.dragging = False
        self._x0 = 0.0
        self.set_valign(Gtk.Align.CENTER)
        self.set_cursor_from_name("pointer")

        drag = Gtk.GestureDrag()
        drag.connect("drag-begin", self._begin)
        drag.connect("drag-update", self._update)
        drag.connect("drag-end", self._end)
        self.add_controller(drag)
        click = Gtk.GestureClick()
        click.connect("pressed", self._pressed)
        self.add_controller(click)
        scroll = Gtk.EventControllerScroll(flags=Gtk.EventControllerScrollFlags.VERTICAL)
        scroll.connect("scroll", self._scroll)
        self.add_controller(scroll)
        motion = Gtk.EventControllerMotion()
        motion.connect("enter", lambda *_: self._set_hover(True))
        motion.connect("leave", lambda *_: self._set_hover(False))
        self.add_controller(motion)
        self._update_tip()

    def _set_hover(self, on):
        self.hover = on
        self.queue_draw()

    def track_width(self):
        return max(10, self.get_width() - self.text_w)

    def value_at(self, x):
        return (x - 2) / max(1, self.track_width() - 4)

    def _begin(self, gesture, x, _y):
        # The movement belongs to the bar: otherwise the header bar (the video window has the
        # volume there) takes it too and drags the whole window across the desktop.
        gesture.set_state(Gtk.EventSequenceState.CLAIMED)
        self.dragging = True
        self._x0 = x
        self.set_value(self.value_at(x))

    def _update(self, _g, dx, _dy):
        self.set_value(self.value_at(self._x0 + dx))

    def _end(self, *_):
        self.dragging = False
        self.queue_draw()

    def _pressed(self, _g, n_press, _x, _y):
        if n_press == 2:
            GLib.idle_add(lambda: self.set_value(self.default) or False)

    def _scroll(self, _c, _dx, dy):
        self.set_value(self.value - dy * 0.03)
        return True

    def _update_tip(self):
        self.set_tooltip_text(f"{self.tip} {self.fmt(self.value)}   (wheel: fine, double click: "
                              f"{self.fmt(self.default)})")

    def set_value(self, value, notify=True):
        value = max(0.0, min(1.0, float(value)))
        if abs(value - self.value) < 1e-4:
            return
        self.value = value
        self._update_tip()
        self.queue_draw()
        if notify:
            self.on_change(value)

    def do_measure(self, orientation, for_size):
        if orientation == Gtk.Orientation.HORIZONTAL:
            return self.bar_width, self.bar_width, -1, -1
        return 18, 18, -1, -1

    def do_snapshot(self, snapshot):
        w, h = self.get_width(), self.get_height()
        if w <= 0 or h <= 0:
            return
        cr = smooth_cairo(snapshot, w, h)
        text, accent = Gdk.RGBA(), Gdk.RGBA()
        text.parse(COLORS["text"])
        accent.parse(COLORS["lines"])
        tw = self.track_width()
        y = h / 2
        cr.set_line_cap(cairo.LINE_CAP_ROUND if cairo else 1)  # round ends
        # the empty line
        cr.set_line_width(4)
        cr.set_source_rgba(text.red, text.green, text.blue, 0.22 * text.alpha)
        cr.move_to(2, y)
        cr.line_to(tw - 2, y)
        cr.stroke()
        # the filled part (pink while it is being moved)
        fill = 2 + (tw - 4) * self.value
        color = accent if (self.dragging or self.hover) else text
        if self.value > 0.001:
            cr.set_source_rgba(color.red, color.green, color.blue, color.alpha)
            cr.move_to(2, y)
            cr.line_to(fill, y)
            cr.stroke()
        # the small mark at the level
        cr.set_line_cap(cairo.LINE_CAP_BUTT if cairo else 0)
        cr.set_line_width(2)
        cr.set_source_rgba(1, 1, 1, 0.95)
        cr.move_to(fill, y - 6)
        cr.line_to(fill, y + 6)
        cr.stroke()
        # the number
        cr.set_font_size(11)
        label = self.fmt(self.value)
        ext = cr.text_extents(label)
        cr.set_source_rgba(text.red, text.green, text.blue, 0.85 * text.alpha)
        cr.move_to(w - ext.width - ext.x_bearing - 1, y + ext.height / 2)
        cr.show_text(label)


class FlatVolume(Gtk.Box):
    """Master volume: a speaker button (mute) and the flat bar."""

    def __init__(self, value, on_change, width=110):
        super().__init__(spacing=2, valign=Gtk.Align.CENTER)
        self.on_change = on_change
        self._before_mute = 1.0
        self.icon = Gtk.Image.new_from_icon_name("audio-volume-high-symbolic")
        self.icon.set_pixel_size(16)
        self.icon.add_css_class("vol-icon")
        button = Gtk.Button(valign=Gtk.Align.CENTER, tooltip_text="Mute / unmute")
        button.add_css_class("flat")
        button.add_css_class("row-btn")
        button.set_child(self.icon)
        button.connect("clicked", self.toggle_mute)
        self.bar = FlatBar(value, self._changed, width)
        self.append(button)
        self.append(self.bar)
        self._update_icon()

    def _changed(self, value):
        self._update_icon()
        self.on_change(value)

    def set_value(self, value, notify=False):
        self.bar.set_value(value, notify)
        self._update_icon()

    def toggle_mute(self, *_):
        if self.bar.value > 0.001:
            self._before_mute = self.bar.value
            self.bar.set_value(0.0)
        else:
            self.bar.set_value(self._before_mute or 1.0)

    def _update_icon(self):
        v = self.bar.value
        name = ("muted" if v <= 0.001 else "low" if v < 0.34 else "medium" if v < 0.67 else "high")
        self.icon.set_from_icon_name(f"audio-volume-{name}-symbolic")


class LoadStrip(Gtk.Box):
    """A small line inside the search field that shows VST3 effects loading ("VST 2/5").
    It appears only while something loads, and fades out when everything is ready."""

    def __init__(self):
        super().__init__(spacing=6, valign=Gtk.Align.CENTER)
        self.label = Gtk.Label(label="VST")
        self.label.add_css_class("vst-load-text")
        self.bar = Gtk.ProgressBar(valign=Gtk.Align.CENTER)
        self.bar.add_css_class("vst-load-bar")
        self.bar.set_size_request(70, -1)
        self.append(self.label)
        self.append(self.bar)
        self.set_visible(False)
        self.set_can_target(True)
        self._target = 0.0
        self._timer = 0
        self._round = 0  # a new load during the fade-out keeps the line on screen

    def show_progress(self, done, total, name=""):
        total = max(1, int(total))
        done = max(0, min(int(done), total))
        self._round += 1
        self.label.set_label(f"VST {min(done + 1, total)}/{total}")
        self.set_tooltip_text(f"Loading VST3 effect: {name}" if name else "Loading VST3 effects")
        self._target = (done + 0.85) / total
        if not self.get_visible():
            self.bar.set_fraction(done / total)
            self.set_visible(True)
            animate_opacity(self, 0.0, 1.0, 200)
        else:
            self.set_opacity(1.0)
            if self.bar.get_fraction() < done / total:
                self.bar.set_fraction(done / total)
        if not self._timer:
            self._timer = GLib.timeout_add(80, self._creep)

    def _creep(self):
        """The bar keeps moving slowly while one effect loads, so it never looks frozen."""
        fraction = self.bar.get_fraction()
        if fraction < self._target:
            self.bar.set_fraction(fraction + (self._target - fraction) * 0.04)
        return True

    def finish(self):
        if not self.get_visible():
            return
        if self._timer:
            GLib.source_remove(self._timer)
            self._timer = 0
        self.bar.set_fraction(1.0)
        self.label.set_label("VST ✓")
        self.set_tooltip_text("VST3 effects are ready")
        this_round = self._round

        def fade():
            if self._round != this_round:
                return False
            animate_opacity(self, 1.0, 0.0, 300)

            def gone():
                if self._round == this_round:
                    self.set_visible(False)
                return False

            GLib.timeout_add(330, gone)
            return False

        GLib.timeout_add(700, fade)


def search_shell(entry, *extras):
    """The search field with room on its right side (loading line, volume): one framed box,
    so the field itself never moves or changes its look."""
    shell = Gtk.Box(spacing=6, hexpand=True, valign=Gtk.Align.CENTER)
    shell.add_css_class("search-shell")
    entry.remove_css_class("pinkline")
    entry.set_hexpand(True)
    shell.append(entry)
    for widget in extras:
        shell.append(widget)
    return shell


