def install_icons():
    """The app's own icons: the radio, and spares for icons a theme may lack.
    They sit in a search folder that GTK looks into only after the icon theme itself."""
    folder = Path(GLib.get_user_cache_dir()) / "player-17" / "icons"
    try:
        folder.mkdir(parents=True, exist_ok=True)
        for name, svg in {RADIO_ICON: RADIO_SVG, **FALLBACK_ICONS}.items():
            icon = folder / f"{name}.svg"
            if not icon.exists() or icon.read_text() != svg:
                icon.write_text(svg)
        Gtk.IconTheme.get_for_display(Gdk.Display.get_default()).add_search_path(str(folder))
    except Exception as err:
        print("Own icons are not available:", err)


