class RadioRecorder:
    """Writes what the player sends out (after EQ and plugins, before the volume) to a FLAC file.
    The sound arrives through Player.start_tap; FLAC keeps it lossless until it is saved."""

    SAMPLE_BYTES = {"F32LE": 4, "F32BE": 4, "F64LE": 8, "S16LE": 2, "S16BE": 2, "S32LE": 4,
                    "S24LE": 3, "S24_32LE": 4, "U8": 1, "S8": 1}

    def __init__(self, path):
        self.path = path
        self.pipe = self.src = None
        self.caps = None
        self.secs = 0.0
        self.rate = 0
        self.frame_bytes = 0
        self.closed = False
        self.lock = threading.Lock()

    @staticmethod
    def available():
        return all(Gst.ElementFactory.find(n) for n in ("appsrc", "flacenc", "filesink"))

    @property
    def seconds(self):
        return self.secs

    def push(self, caps, data):
        with self.lock:
            if self.closed or caps is None or not data:
                return
            text = caps.to_string()
            if self.pipe is None:
                self._open(caps)
            elif text != self.caps:
                # Another station with another rate or format (recording across stations):
                # the file keeps its own format, the new sound is converted into it.
                self.src.set_property("caps", caps)
                self._read_format(caps)
            self.src.emit("push-buffer", Gst.Buffer.new_wrapped(data))
            if self.frame_bytes and self.rate:
                self.secs += (len(data) // self.frame_bytes) / self.rate

    def _read_format(self, caps):
        st = caps.get_structure(0)
        self.rate = st.get_int("rate")[1] or 44100
        channels = st.get_int("channels")[1] or 2
        self.frame_bytes = self.SAMPLE_BYTES.get(st.get_string("format") or "", 4) * channels
        self.caps = caps.to_string()

    def _open(self, caps):
        self._read_format(caps)
        Path(self.path).parent.mkdir(parents=True, exist_ok=True)
        # The file's rate is the first sound's; later sound (another station) is resampled to it.
        self.pipe = Gst.parse_launch(
            "appsrc name=src format=time ! audioconvert ! audioresample ! "
            f"audio/x-raw,rate={self.rate},channels=2 ! audioconvert ! audio/x-raw,format=S24_32LE ! "
            "flacenc ! filesink name=out")
        self.src = self.pipe.get_by_name("src")
        self.src.set_property("caps", caps)
        self.pipe.get_by_name("out").set_property("location", self.path)
        self.pipe.set_state(Gst.State.PLAYING)
        self.caps = caps.to_string()

    def finish(self, done=None):
        """Close the file. done(ok) on the main thread; without `done` it waits and returns ok."""
        with self.lock:
            self.closed = True
            pipe = self.pipe

        def work():
            ok = False
            if pipe is not None:
                self.src.emit("end-of-stream")
                msg = pipe.get_bus().timed_pop_filtered(10 * Gst.SECOND, Gst.MessageType.EOS | Gst.MessageType.ERROR)
                ok = msg is not None and msg.type == Gst.MessageType.EOS
                pipe.set_state(Gst.State.NULL)
            if done is not None:
                GLib.idle_add(lambda: done(ok) or False)
            return ok

        if done is None:
            return work()
        threading.Thread(target=work, daemon=True).start()
        return None


def convert_audio(source, target, encoder):
    """Re-encode a sound file (FLAC recording -> MP3, WAV, Ogg). Waits; returns True when done."""
    try:
        pipe = Gst.parse_launch(
            f"filesrc name=src ! decodebin ! audioconvert ! audioresample ! {encoder_chain(encoder)} ! filesink name=out")
    except GLib.Error as err:
        print("Convert:", err.message)
        return False
    pipe.get_by_name("src").set_property("location", source)
    pipe.get_by_name("out").set_property("location", target)
    pipe.set_state(Gst.State.PLAYING)
    msg = pipe.get_bus().timed_pop_filtered(30 * 60 * Gst.SECOND, Gst.MessageType.EOS | Gst.MessageType.ERROR)
    pipe.set_state(Gst.State.NULL)
    return msg is not None and msg.type == Gst.MessageType.EOS


def tag_file(path, title, artist):
    if mutagen is None:
        return
    try:
        audio = mutagen.File(path, easy=True)
        if audio is None:
            return
        if audio.tags is None:
            audio.add_tags()
        audio["title"] = title
        audio["artist"] = artist
        audio.save()
    except Exception as err:
        print("Tags were not written:", err)


def safe_file_name(text):
    return re.sub(r'[\\/:*?"<>|]+', "_", text).strip() or "recording"


class ExportDialog(Adw.Window):
    """A small window with the progress of an export. The export runs in the background:
    the music keeps playing, the window can be hidden (the title says when it is ready)."""

    def __init__(self, parent, name, on_cancel, heading="Saving the track with the effects"):
        super().__init__(transient_for=parent, modal=False, title="Export")
        self.set_default_size(420, -1)
        self.set_resizable(False)
        self.set_hide_on_close(True)
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=14)
        for side in ("top", "bottom", "start", "end"):
            getattr(box, f"set_margin_{side}")(22)
        box.add_css_class("main")
        self.head = Gtk.Label(label=heading, xalign=0)
        self.head.add_css_class("prefs-head")
        box.append(self.head)
        self.label = Gtk.Label(label=name, xalign=0, ellipsize=3)
        self.label.add_css_class("eq-label")
        box.append(self.label)
        self.bar = Gtk.ProgressBar()
        box.append(self.bar)
        note = Gtk.Label(label="It runs in the background: you can keep listening and hide this window.",
                         xalign=0, wrap=True)
        note.add_css_class("eq-label")
        note.set_opacity(0.6)
        box.append(note)
        buttons = Gtk.Box(spacing=8, halign=Gtk.Align.END)
        hide = Gtk.Button(label="Hide")
        hide.add_css_class("flat")
        hide.connect("clicked", lambda *_: self.set_visible(False))
        cancel = Gtk.Button(label="Cancel")
        cancel.add_css_class("flat")
        cancel.connect("clicked", lambda *_: on_cancel())
        buttons.append(hide)
        buttons.append(cancel)
        box.append(buttons)
        self.set_content(box)


class SaveAsWindow(Adw.Window):
    """Where and in which format to save: name, folder and a format list with a short note
    on each format. The last chosen format is remembered (FLAC the first time)."""

    def __init__(self, parent, title, name, folder, formats, keys, remember, on_save, default):
        window = parent if isinstance(parent, Gtk.Window) else None
        super().__init__(transient_for=window, modal=window is not None, title=title)
        self.parent_window = parent
        self.formats, self.keys, self.remember, self.on_save = formats, keys, remember, on_save
        self.folder = folder if folder and os.path.isdir(folder) else str(Path.home())
        self.confirm = None
        self.set_default_size(460, -1)
        self.set_resizable(False)

        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=12)
        for side in ("top", "bottom", "start", "end"):
            getattr(box, f"set_margin_{side}")(22)
        box.add_css_class("main")
        head = Gtk.Label(label=title, xalign=0)
        head.add_css_class("prefs-title")
        box.append(head)
        line = Gtk.Box()
        line.add_css_class("prefs-line")
        box.append(line)

        def caption(text):
            label = Gtk.Label(label=text, xalign=0)
            label.add_css_class("prefs-head")
            box.append(label)

        caption("name")
        name_row = Gtk.Box(spacing=6)
        self.entry = Gtk.Entry(text=name, hexpand=True)
        self.entry.connect("activate", self.save)
        self.entry.connect("changed", lambda *_: self.clear_confirm())
        self.ending = Gtk.Label(xalign=0)
        self.ending.add_css_class("eq-label")
        name_row.append(self.entry)
        name_row.append(self.ending)
        box.append(name_row)

        caption("format")
        saved = parent.settings.get(remember)
        start = saved if saved in keys else (default if default in keys else keys[0])
        self.drop = Gtk.DropDown.new_from_strings([formats[k][0] for k in keys])
        self.drop.set_selected(keys.index(start))
        self.drop.connect("notify::selected", lambda *_: self.show_format())
        box.append(self.drop)
        self.note = Gtk.Label(xalign=0, wrap=True)
        self.note.add_css_class("eq-label")
        self.note.set_opacity(0.7)
        box.append(self.note)

        caption("folder")
        folder_row = Gtk.Box(spacing=10)
        setup = Gtk.Button(label="Setup")
        setup.add_css_class("flat")
        setup.connect("clicked", self.pick_folder)
        self.folder_label = Gtk.Label(label=self.folder, xalign=0, hexpand=True, ellipsize=1)
        self.folder_label.add_css_class("pinkline")
        folder_row.append(setup)
        folder_row.append(self.folder_label)
        box.append(folder_row)

        self.warn = Gtk.Label(xalign=0, wrap=True)
        self.warn.add_css_class("load-warn")
        self.warn.set_visible(False)
        box.append(self.warn)

        buttons = Gtk.Box(spacing=8, halign=Gtk.Align.END)
        cancel = Gtk.Button(label="Cancel")
        cancel.add_css_class("flat")
        cancel.connect("clicked", lambda *_: self.close())
        self.save_btn = Gtk.Button(label="Save")
        self.save_btn.add_css_class("flat")
        self.save_btn.connect("clicked", self.save)
        buttons.append(cancel)
        buttons.append(self.save_btn)
        box.append(buttons)
        self.set_content(box)
        self.show_format()

    def key(self):
        return self.keys[self.drop.get_selected()]

    def show_format(self):
        name, ending, note, _how = self.formats[self.key()]
        self.ending.set_label(f".{ending}")
        self.note.set_label(note)
        self.clear_confirm()

    def clear_confirm(self):
        self.confirm = None
        self.warn.set_visible(False)
        self.save_btn.set_label("Save")

    def pick_folder(self, *_):
        dialog = Gtk.FileDialog(title="Choose the folder")
        dialog.set_initial_folder(Gio.File.new_for_path(self.folder))

        def chosen(d, result):
            try:
                path = d.select_folder_finish(result).get_path()
            except GLib.Error:
                return
            if path:
                self.folder = path
                self.folder_label.set_label(path)
                self.clear_confirm()

        dialog.select_folder(self, None, chosen)

    def save(self, *_):
        stem = safe_file_name(self.entry.get_text())
        key = self.key()
        path = os.path.join(self.folder, f"{stem}.{self.formats[key][1]}")
        if os.path.exists(path) and self.confirm != path:
            self.confirm = path
            self.warn.set_label("This file already exists. Press Replace to overwrite it.")
            self.warn.set_visible(True)
            self.save_btn.set_label("Replace")
            return
        self.parent_window.settings[self.remember] = key
        save_settings(self.parent_window.settings)
        self.close()
        self.on_save(path, key)


def ask_save_as(parent, title, name, folder, kind, remember, on_save):
    """kind "audio": the sound formats that can be written here; "video": the video ones."""
    if kind == "video":
        formats, keys, default = VIDEO_FORMATS, list(VIDEO_FORMATS), "mkv"
    else:
        formats, keys, default = AUDIO_FORMATS, audio_formats_here(), "flac"
    if not keys:
        parent.flash_title("No encoder found: sudo apt install gstreamer1.0-plugins-good")
        return
    SaveAsWindow(parent, title, name, folder, formats, keys, remember, on_save, default).present()


class Mpris:
    """MPRIS on the session bus: GNOME sends the headset button and the keyboard media keys
    (play/pause, next, previous) to the player through it. The player also shows up in
    the GNOME media panel with its title and cover."""

    PATH = "/org/mpris/MediaPlayer2"

    def __init__(self, main):
        self.main = main
        self.conn = None
        self.ids = []
        self.owner = 0
        self.art_file = Path(GLib.get_user_cache_dir()) / "player-17" / "cover"
        try:
            self.node = Gio.DBusNodeInfo.new_for_xml(MPRIS_XML)
            self.owner = Gio.bus_own_name(
                Gio.BusType.SESSION, "org.mpris.MediaPlayer2.player17", Gio.BusNameOwnerFlags.NONE,
                self._on_bus, None, None,
            )
        except Exception as err:
            print("Media keys (MPRIS) are not available:", err)

    def _on_bus(self, conn, _name):
        self.conn = conn
        for iface in self.node.interfaces:
            try:
                register = getattr(conn, "register_object_with_closures", None) or conn.register_object
                self.ids.append(register(self.PATH, iface, self._call, self._get, None))
            except Exception as err:
                print("MPRIS:", err)

    # --- calls from GNOME (the headset button arrives as PlayPause) ---
    def _call(self, _conn, _sender, _path, _iface, method, params, invocation):
        m = self.main
        app = m.get_application()
        video = app.video_window if app is not None else None
        if not m.get_visible() and video is not None and video.get_visible():
            # Only the video window is on screen: the headset button controls the video.
            actions = {
                "PlayPause": video.on_play_pause, "Play": video.play, "Pause": video.external_pause,
                "Stop": video.external_pause, "Next": video.next_video, "Previous": video.prev_video,
                "Raise": video.present,
            }
            if method in actions:
                actions[method]()
            invocation.return_value(None)
            return
        if method == "PlayPause":
            m.on_play_pause()
        elif method == "Play":
            if not m.player.playing:
                m.on_play_pause()
        elif method in ("Pause", "Stop"):
            if m.player.playing:
                m.on_play_pause()
        elif method == "Next":
            m.next_track()
        elif method == "Previous":
            m.prev_track()
        elif method == "Raise":
            m.present()
        elif method == "Quit":
            m.close()
        invocation.return_value(None)

    def _get(self, _conn, _sender, _path, iface, prop):
        m = self.main
        values = {
            "CanQuit": GLib.Variant("b", True), "CanRaise": GLib.Variant("b", True),
            "HasTrackList": GLib.Variant("b", False), "Identity": GLib.Variant("s", "Player-17"),
            "DesktopEntry": GLib.Variant("s", APP_ID),
            "SupportedUriSchemes": GLib.Variant("as", ["file"]),
            "SupportedMimeTypes": GLib.Variant("as", ["audio/mpeg", "audio/flac"]),
            "PlaybackStatus": GLib.Variant("s", self._status()),
            "LoopStatus": GLib.Variant("s", {"off": "None", "all": "Playlist", "one": "Track"}[m.repeat_mode]),
            "Rate": GLib.Variant("d", 1.0), "MinimumRate": GLib.Variant("d", 1.0),
            "MaximumRate": GLib.Variant("d", 1.0),
            "Shuffle": GLib.Variant("b", m.shuffle),
            "Metadata": self._metadata(),
            "Volume": GLib.Variant("d", float(getattr(m, "volume_value", 1.0))),
            "Position": GLib.Variant("x", int(m.player.times()[0] * 1_000_000)),
            "CanGoNext": GLib.Variant("b", True), "CanGoPrevious": GLib.Variant("b", True),
            "CanPlay": GLib.Variant("b", bool(m.tracks) or m.radio_active),
            "CanPause": GLib.Variant("b", bool(m.tracks) or m.radio_active),
            "CanSeek": GLib.Variant("b", False), "CanControl": GLib.Variant("b", True),
        }
        return values.get(prop)

    def _status(self):
        if self.main.radio_active:
            return "Playing" if self.main.player.playing else "Paused"
        if not self.main.tracks:
            return "Stopped"
        return "Playing" if self.main.player.playing else "Paused"

    def _metadata(self):
        m = self.main
        data = {"mpris:trackid": GLib.Variant("o", "/io/github/sfh17/track/none")}
        if m.radio_active and m.station:
            data = {
                "mpris:trackid": GLib.Variant("o", "/io/github/sfh17/radio"),
                "xesam:title": GLib.Variant("s", m.radio_now or m.station["name"]),
                "xesam:artist": GLib.Variant("as", [m.station["name"]]),
            }
            if self.art_file.exists():
                data["mpris:artUrl"] = GLib.Variant("s", self.art_file.as_uri())
        elif m.tracks:
            info = m.infos[m.index]
            data = {
                "mpris:trackid": GLib.Variant("o", f"/io/github/sfh17/track/{m.index}"),
                "xesam:title": GLib.Variant("s", info["title"] or Path(m.tracks[m.index]).stem),
                "xesam:artist": GLib.Variant("as", [info["artist"]] if info["artist"] else []),
                "xesam:album": GLib.Variant("s", info["album"] or ""),
                "xesam:url": GLib.Variant("s", GLib.filename_to_uri(m.tracks[m.index], None)),
            }
            duration = m.player.times()[1]
            if duration > 0:
                data["mpris:length"] = GLib.Variant("x", int(duration * 1_000_000))
            if self.art_file.exists():
                data["mpris:artUrl"] = GLib.Variant("s", self.art_file.as_uri())
        return GLib.Variant("a{sv}", data)

    def release(self):
        if self.conn is not None:
            for reg in self.ids:
                try:
                    self.conn.unregister_object(reg)
                except Exception:
                    pass
        if self.owner:
            Gio.bus_unown_name(self.owner)
        self.conn, self.ids, self.owner = None, [], 0

    # --- tell GNOME what changed ---
    def set_cover(self, data):
        try:
            if data:
                self.art_file.parent.mkdir(parents=True, exist_ok=True)
                self.art_file.write_bytes(data)
            else:
                self.art_file.unlink(missing_ok=True)
        except OSError:
            pass

    def changed(self):
        if self.conn is None:
            return
        props = {
            "PlaybackStatus": GLib.Variant("s", self._status()),
            "Metadata": self._metadata(),
            "Shuffle": GLib.Variant("b", self.main.shuffle),
        }
        try:
            self.conn.emit_signal(
                None, self.PATH, "org.freedesktop.DBus.Properties", "PropertiesChanged",
                GLib.Variant("(sa{sv}as)", ("org.mpris.MediaPlayer2.Player", props, [])),
            )
        except Exception:
            pass


# ======================================================================================
# Online radio: stations from radio-browser.info (a free, open catalog of internet radio).
# ======================================================================================
RADIO_SERVERS = ("all.api.radio-browser.info", "de1.api.radio-browser.info", "de2.api.radio-browser.info",
                 "fi1.api.radio-browser.info", "nl1.api.radio-browser.info")
RADIO_LIMIT = 100
RADIO_AGENT = f"{APP_NAME}/{APP_VERSION}"
RADIO_RETRIES = 3        # a stream that drops is connected again this many times
_RADIO_SERVER = []       # the catalog server that answered last


def radio_request(path, params=None, timeout=8):
    """GET from the station catalog, trying the servers one by one. Returns the JSON."""
    import urllib.parse
    import urllib.request
    query = ("?" + urllib.parse.urlencode(params)) if params else ""
    servers = list(_RADIO_SERVER) + [s for s in RADIO_SERVERS if s not in _RADIO_SERVER]
    last = None
    for server in servers:
        try:
            req = urllib.request.Request(f"https://{server}{path}{query}", headers={"User-Agent": RADIO_AGENT})
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                data = json.loads(resp.read().decode("utf-8", "replace"))
            _RADIO_SERVER[:] = [server]
            return data
        except Exception as exc:
            last = exc
    raise OSError(f"the station catalog cannot be reached ({last})")


def radio_station(item):
    """Only what the player needs from a catalog entry."""
    url = (item.get("url_resolved") or item.get("url") or "").strip()
    return {
        "uuid": item.get("stationuuid") or url,
        "name": (item.get("name") or "").strip() or url,
        "url": url,
        "country": item.get("countrycode") or item.get("country") or "",
        "codec": item.get("codec") or "",
        "bitrate": int(item.get("bitrate") or 0),
        "tags": item.get("tags") or "",
        "favicon": item.get("favicon") or "",
    }


def radio_search(query):
    """Stations for a search text: by name, and by genre when few names match.
    An empty search gives the most listened stations."""
    base = {"limit": RADIO_LIMIT, "hidebroken": "true", "order": "clickcount", "reverse": "true"}
    if query:
        found = radio_request("/json/stations/search", {**base, "name": query})
        if len(found) < 10:  # e.g. "jazz", "techno": genres are tags
            found += radio_request("/json/stations/search", {**base, "tag": query.lower()})
    else:
        found = radio_request("/json/stations/search", base)
    seen, stations = set(), []
    for item in found:
        station = radio_station(item)
        if station["url"].startswith(("http://", "https://")) and station["uuid"] not in seen:
            seen.add(station["uuid"])
            stations.append(station)
    return stations


def radio_details(station):
    """The small grey line under a station name: country, format, genres."""
    parts = [station.get("country") or ""]
    if station.get("codec"):
        parts.append(f"{station['codec']} {station['bitrate']} kbps" if station.get("bitrate") else station["codec"])
    tags = ", ".join(t.strip() for t in (station.get("tags") or "").split(",")[:3] if t.strip())
    if tags:
        parts.append(tags)
    return "  \u00b7  ".join(p for p in parts if p)


def radio_count_click(uuid):
    """Tell the catalog the station was played (it ranks stations by this). Errors do not matter."""
    if not re.fullmatch(r"[0-9A-Za-z-]{1,64}", str(uuid or "")):
        return   # not a catalog id (e.g. a stream address): nothing to count

    def work():
        try:
            radio_request(f"/json/url/{uuid}", timeout=5)
        except Exception:
            pass

    threading.Thread(target=work, daemon=True).start()


def fetch_bytes(url, limit=512 * 1024, timeout=6):
    import urllib.request
    req = urllib.request.Request(url, headers={"User-Agent": RADIO_AGENT})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read(limit)


def radio_icon_name():
    """A radio icon from the icon theme (names differ between themes)."""
    try:
        theme = Gtk.IconTheme.get_for_display(Gdk.Display.get_default())
        for name in (RADIO_ICON, "radio-symbolic", "audio-radio-symbolic", "network-wireless-signal-excellent-symbolic",
                     "network-wireless-symbolic"):
            if theme.has_icon(name):
                return name
    except Exception:
        pass
    return "audio-x-generic-symbolic"


def clean_eq_settings(saved):
    """The settings of one Prism EQ 17 (points, Simple faders, mode, Bass, Reverb, Crunch),
    with every missing or broken value put right."""
    eq = {**EQ_DEFAULTS, **(saved if isinstance(saved, dict) else {})}
    eq.pop("limiter", None)          # the limiter is its own module now
    eq.pop("limiter_engine", None)
    if not isinstance(eq.get("bands"), list) or len(eq["bands"]) != 6:
        eq["bands"] = [0.0] * 6
    if not isinstance(eq.get("points"), list):
        eq["points"] = peq_default_points(eq["bands"])
    eq["points"] = [peq_clean(p) for p in eq["points"]]
    if eq.get("mode") not in ("prism", "simple"):
        eq["mode"] = "prism"
    simple = list(eq.get("simple") or [])
    eq["simple"] = [float(g) for g in simple[:10]] + [0.0] * max(0, 10 - len(simple))
    return eq


class ModuleCtl:
    """One Plugins 17 module as its panel sees it: its own settings (kept in the window's
    settings), its unit in the player, and the actions (presets, reset). The panel (EqWindow)
    calls the same names the old single equalizer window used."""

    def __init__(self, window, mod):
        self.window = window
        self.mod = mod
        self.uid = mod["id"]
        self.kind = mod["type"]
        self.player = window.player.unit(self.uid, self.kind)  # the module's unit
        self.ui = None  # EqWindow, made by the Plugins window when it shows the module

    @property
    def settings(self):
        return self.window.settings

    @property
    def eq_settings(self):
        """Prism EQ 17: its equalizer dict. Limiter 17: the module dict (it holds "limiter")."""
        return self.mod["eq"] if self.kind == "eq" else self.mod

    def schedule_save(self):
        self.window.schedule_save()

    def flash_title(self, text):
        self.window.flash_title(text)

    def load_into_unit(self):
        """Every saved value onto the unit (the chain itself is built by the window)."""
        unit = self.player
        if self.kind == "eq":
            eq = self.mod["eq"]
            unit.points = [peq_clean(x) for x in self.active_points()]
            unit.bass_db = (float(eq["bass"]) - 0.5) * 2 * EQ_RANGE_DB
            unit.reverb_level = float(eq["reverb"])
            unit.reverb_preset = eq["reverb_preset"]
            unit.crunch = float(eq.get("crunch", 0.0))
        elif self.kind == "sat":
            sat = self.mod["sat"]
            unit.points = [peq_clean(p) for p in sat["points"]]
            unit.drive_db = float(sat["drive"]) * SAT_DRIVE_DB
            unit.mix = float(sat["mix"])
            unit.output_db = (float(sat["output"]) - 0.5) * 2 * SAT_OUTPUT_DB
            unit.sat_type = sat["type"]
            unit.auto = bool(sat["auto"])
            unit.mode = sat.get("mode", "classic")
            unit.bands = json.loads(json.dumps(sat["bands"]))
        elif self.kind == "ott":
            unit.config = json.loads(json.dumps(self.mod["ott"]))
        else:
            unit.limiter_values = self.effective_limiter()

    # --- OTT 17 ---
    def push_ott(self):
        self.player.set_config(self.mod["ott"])
        self.schedule_save()

    def set_ott_value(self, key, value):
        """depth / time / up / down / in / out (0..1), mode ("classic" / "prism"), classic_gain."""
        self.mod["ott"][key] = value
        self.mod["ott"] = clean_ott_settings(self.mod["ott"])
        self.push_ott()
        if key == "mode" and self.ui is not None:
            self.ui.ott_view.queue_draw()

    def set_ott_prism(self, prism, amounts=None):
        self.mod["ott"]["prism"] = prism
        if amounts is not None:
            self.mod["ott"]["amounts"] = amounts
        self.mod["ott"] = clean_ott_settings(self.mod["ott"])
        self.push_ott()

    def set_ott_band_amount(self, key, band, value):
        """Hard Prism: one band's own depth / time / up / down."""
        amounts = self.mod["ott"]["amounts"]
        if key in amounts and 0 <= band < len(amounts[key]):
            amounts[key][band] = max(0.0, min(1.0, float(value)))
            self.push_ott()

    def reset_ott(self):
        self.mod["ott"] = clean_ott_settings({})
        self.push_ott()
        self.refresh_ui()
        self.flash_title("OTT reset")

    def save_ott_preset(self, parent):
        dialog = Gtk.FileDialog(title="Save an OTT 17 preset")
        folder = self.settings.get("eq_preset_dir") or str(Path.home() / "Documents")
        if os.path.isdir(folder):
            dialog.set_initial_folder(Gio.File.new_for_path(folder))
        dialog.set_initial_name("My OTT.ott.prism17")
        store = Gio.ListStore.new(Gtk.FileFilter)
        store.append(file_filter("Prism 17 OTT preset  *.ott.prism17", ["*.ott.prism17", "*.p17ott"]))
        dialog.set_filters(store)

        def chosen(d, result):
            try:
                path = d.save_finish(result).get_path()
            except GLib.Error:
                return
            if not path:
                return
            if not path.endswith(".ott.prism17"):
                path += ".ott.prism17"
            # Plain numbers only (Hz, dB, 0..1): the VST and Android versions read the same file.
            data = {"format": "player17-ott", "version": 1, **self.mod["ott"]}
            try:
                Path(path).write_text(json.dumps(data, indent=1))
                self.settings["eq_preset_dir"] = str(Path(path).parent)
                save_settings(self.settings)
                self.flash_title(f"Preset saved: {Path(path).name}")
            except OSError as err:
                self.flash_title(f"Could not save the preset: {err}")

        dialog.save(parent, None, chosen)

    def import_ott_preset(self, parent):
        dialog = Gtk.FileDialog(title="Import an OTT 17 preset")
        folder = self.settings.get("eq_preset_dir") or str(Path.home() / "Documents")
        if os.path.isdir(folder):
            dialog.set_initial_folder(Gio.File.new_for_path(folder))
        store = Gio.ListStore.new(Gtk.FileFilter)
        store.append(file_filter("Prism 17 OTT preset  *.ott.prism17", ["*.ott.prism17", "*.p17ott"]))
        dialog.set_filters(store)

        def chosen(d, result):
            try:
                path = d.open_finish(result).get_path()
                data = json.loads(Path(path).read_text())
                if data.get("format") != "player17-ott":
                    raise ValueError("this is not a Player-17 OTT preset")
            except (GLib.Error, OSError, ValueError, TypeError) as err:
                if not isinstance(err, GLib.Error):
                    self.flash_title(f"Could not import: {err}")
                return
            self.mod["ott"] = clean_ott_settings(data)
            self.settings["eq_preset_dir"] = str(Path(path).parent)
            self.push_ott()
            self.refresh_ui()
            self.flash_title(f"Preset loaded: {Path(path).name}")

        dialog.open(parent, None, chosen)

    # --- Prism Saturator 17 ---
    def set_sat_points(self, points):
        self.mod["sat"]["points"] = [peq_clean(p) for p in points]
        self.player.set_points(self.mod["sat"]["points"])
        self.schedule_save()

    def set_sat_value(self, key, value):
        """drive / mix / output (0..1), type ("soft"...), auto (True / False), mode ("classic" / "bands")."""
        self.mod["sat"][key] = value
        self.load_into_unit()
        self.player._put()
        self.schedule_save()

    def set_sat_bands(self, bands):
        """Bands mode: crossovers and every band's drive / type / mix / output."""
        self.mod["sat"]["bands"] = clean_sat_bands(bands)
        self.load_into_unit()
        self.player._put()
        self.schedule_save()

    def set_sat_band_value(self, index, key, value):
        bands = json.loads(json.dumps(self.mod["sat"]["bands"]))
        if 0 <= index < len(bands["drive"]):
            bands[key][index] = value
            self.set_sat_bands(bands)
            if self.ui is not None:
                self.ui.sat_bands.queue_draw()

    def save_sat_preset(self, parent):
        dialog = Gtk.FileDialog(title="Save a Prism Saturator preset")
        folder = self.settings.get("eq_preset_dir") or str(Path.home() / "Documents")
        if os.path.isdir(folder):
            dialog.set_initial_folder(Gio.File.new_for_path(folder))
        dialog.set_initial_name("My saturation.sat.prism17")
        store = Gio.ListStore.new(Gtk.FileFilter)
        store.append(file_filter("Prism 17 saturator preset  *.sat.prism17", ["*.sat.prism17", "*.p17sat"]))
        dialog.set_filters(store)

        def chosen(d, result):
            try:
                path = d.save_finish(result).get_path()
            except GLib.Error:
                return
            if not path:
                return
            if not path.endswith(".sat.prism17"):
                path += ".sat.prism17"
            data = {"format": "player17-sat", "version": 1, **self.mod["sat"]}
            try:
                Path(path).write_text(json.dumps(data, indent=1))
                self.settings["eq_preset_dir"] = str(Path(path).parent)
                save_settings(self.settings)
                self.flash_title(f"Preset saved: {Path(path).name}")
            except OSError as err:
                self.flash_title(f"Could not save the preset: {err}")

        dialog.save(parent, None, chosen)

    def import_sat_preset(self, parent):
        dialog = Gtk.FileDialog(title="Import a Prism Saturator preset")
        folder = self.settings.get("eq_preset_dir") or str(Path.home() / "Documents")
        if os.path.isdir(folder):
            dialog.set_initial_folder(Gio.File.new_for_path(folder))
        store = Gio.ListStore.new(Gtk.FileFilter)
        store.append(file_filter("Prism 17 saturator preset  *.sat.prism17", ["*.sat.prism17", "*.p17sat"]))
        dialog.set_filters(store)

        def chosen(d, result):
            try:
                path = d.open_finish(result).get_path()
                data = json.loads(Path(path).read_text())
                if data.get("format") != "player17-sat":
                    raise ValueError("this is not a Player-17 saturator preset")
            except (GLib.Error, OSError, ValueError, TypeError) as err:
                if not isinstance(err, GLib.Error):
                    self.flash_title(f"Could not import: {err}")
                return
            self.mod["sat"] = clean_sat_settings(data)
            self.settings["eq_preset_dir"] = str(Path(path).parent)
            self.load_into_unit()
            self.player._put()
            self.schedule_save()
            self.refresh_ui()
            self.flash_title(f"Preset loaded: {Path(path).name}")

        dialog.open(parent, None, chosen)

    def reset_sat(self):
        self.mod["sat"] = clean_sat_settings({})
        self.load_into_unit()
        self.player._put()
        self.schedule_save()
        self.refresh_ui()
        self.flash_title("Saturator reset")

    def refresh_ui(self):
        if self.ui is not None:
            self.ui.refresh()

    # --- Prism EQ 17 ---
    def active_points(self):
        """What the equalizer plays now: the Prism points or the ten Simple faders."""
        eq = self.mod["eq"]
        if eq.get("mode") == "simple":
            return simple_points(eq["simple"])
        return [dict(p) for p in eq["points"]]

    def set_eq_points(self, points):
        eq = self.mod["eq"]
        eq["points"] = [peq_clean(p) for p in points]
        if eq.get("mode") != "simple":
            self.player.set_points(eq["points"])
        self.schedule_save()

    def set_simple_gain(self, index, gain):
        eq = self.mod["eq"]
        eq["simple"][index] = float(gain)
        if eq.get("mode") == "simple":
            self.player.set_points(self.active_points())
        self.schedule_save()

    def set_eq_mode(self, mode):
        self.mod["eq"]["mode"] = mode
        self.player.set_points(self.active_points())
        self.schedule_save()

    def set_eq_knob(self, key, value):
        self.mod["eq"][key] = value
        if key == "bass":
            self.player.set_bass_db((value - 0.5) * 2 * EQ_RANGE_DB)
        elif key == "reverb":
            self.player.set_reverb(value)
        elif key == "crunch":
            self.player.set_crunch(value)
        self.schedule_save()

    def set_reverb_preset(self, name):
        self.mod["eq"]["reverb_preset"] = name
        self.player.set_reverb_preset(name)
        self.schedule_save()

    def ask_reset_eq(self, parent):
        """Reset asks first: it throws away this equalizer's sound."""
        heading, body = "Reset this equalizer?", (
            "Points, faders, Bass, Reverb and Crunch of this Prism EQ 17 go back to their defaults. "
            "Save a preset first if you want to keep this sound.")
        if hasattr(Adw, "AlertDialog"):
            dialog = Adw.AlertDialog(heading=heading, body=body)
        else:
            dialog = Adw.MessageDialog(transient_for=parent, heading=heading, body=body)
        dialog.add_response("cancel", "Cancel")
        dialog.add_response("reset", "Reset")
        dialog.set_response_appearance("reset", Adw.ResponseAppearance.DESTRUCTIVE)
        dialog.set_default_response("cancel")
        dialog.set_close_response("cancel")

        def answered(_d, response):
            if response == "reset":
                GLib.idle_add(lambda: self.reset_eq() and False)  # after the dialog has closed

        dialog.connect("response", answered)
        if hasattr(Adw, "AlertDialog"):
            dialog.present(parent)
        else:
            dialog.present()

    def reset_eq(self):
        """Every setting of this equalizer back to its default (the mode Prism / Simple stays)."""
        self.mod["eq"].update({
            "bands": [0.0] * 6, "simple": [0.0] * 10, "points": peq_default_points([0.0] * 6),
            "bass": EQ_DEFAULTS["bass"], "reverb": EQ_DEFAULTS["reverb"],
            "reverb_preset": EQ_DEFAULTS["reverb_preset"], "crunch": EQ_DEFAULTS["crunch"],
        })
        self.load_into_unit()
        self.window.player.refresh()
        self.schedule_save()
        self.refresh_ui()
        self.flash_title("Equalizer reset")

    def save_eq_preset(self, parent):
        settings = self.settings
        dialog = Gtk.FileDialog(title=f"Save a {PEQ_NAME} preset")
        folder = settings.get("eq_preset_dir") or str(Path.home() / "Documents")
        if os.path.isdir(folder):
            dialog.set_initial_folder(Gio.File.new_for_path(folder))
        dialog.set_initial_name("My sound.eq.prism17")
        store = Gio.ListStore.new(Gtk.FileFilter)
        store.append(file_filter("Prism 17 EQ preset  *.eq.prism17", ["*.eq.prism17", "*.p17eq"]))
        dialog.set_filters(store)

        def chosen(d, result):
            try:
                path = d.save_finish(result).get_path()
            except GLib.Error:
                return
            if not path:
                return
            if not path.endswith(".eq.prism17"):
                path += ".eq.prism17"
            # Plain numbers only (Hz, dB, Q, 0..1 knobs): the same file can later be read
            # by the VST and the Android versions of Prism EQ 17.
            data = {"format": "player17-eq", "version": 1}
            data.update({k: self.mod["eq"].get(k) for k in EQ_PRESET_KEYS if k != "limiter"})
            try:
                Path(path).write_text(json.dumps(data, indent=1))
                settings["eq_preset_dir"] = str(Path(path).parent)
                save_settings(settings)
                self.flash_title(f"Preset saved: {Path(path).name}")
            except OSError as err:
                self.flash_title(f"Could not save the preset: {err}")

        dialog.save(parent, None, chosen)

    def import_eq_preset(self, parent):
        settings = self.settings
        dialog = Gtk.FileDialog(title=f"Import a {PEQ_NAME} preset")
        folder = settings.get("eq_preset_dir") or str(Path.home() / "Documents")
        if os.path.isdir(folder):
            dialog.set_initial_folder(Gio.File.new_for_path(folder))
        store = Gio.ListStore.new(Gtk.FileFilter)
        store.append(file_filter("Prism 17 EQ preset  *.eq.prism17", ["*.eq.prism17", "*.p17eq", "*.plyereq"]))
        dialog.set_filters(store)

        def chosen(d, result):
            try:
                path = d.open_finish(result).get_path()
            except GLib.Error:
                return
            try:
                data = json.loads(Path(path).read_text())
                if data.get("format") not in ("player17-eq", "plyer-eq"):
                    raise ValueError("this is not a Player-17 EQ preset")
            except (OSError, ValueError) as err:
                self.flash_title(f"Could not import: {err}")
                return
            eq = self.mod["eq"]
            for key in EQ_PRESET_KEYS:
                if key != "limiter" and key in data and data[key] is not None:
                    eq[key] = data[key]
            self.mod["eq"] = clean_eq_settings(eq)
            settings["eq_preset_dir"] = str(Path(path).parent)
            self.load_into_unit()
            self.window.player.refresh()
            self.schedule_save()
            self.refresh_ui()
            self.flash_title(f"Preset loaded: {Path(path).name}")

        dialog.open(parent, None, chosen)

    # --- Limiter 17 ---
    def limiter_mode(self):
        """"simple" or "prism" (only the own limiter has Simple; LSP / Calf show all)."""
        if self.player.lv2_name != "p17limiter":
            return "prism"
        mode = self.mod.get("limiter_mode")
        if mode in ("simple", "prism"):
            return mode
        # A module from before the modes: Prism if anything beyond the Simple knobs was set,
        # so it keeps sounding exactly as it did. Decided once and kept.
        extra = [k for k in (self.mod.get("limiter") or {}) if k not in LIM_SIMPLE and k != "enabled"]
        self.mod["limiter_mode"] = "prism" if extra else "simple"
        return self.mod["limiter_mode"]

    def effective_limiter(self):
        """The values the limiter plays with now: all saved ones (Prism), or the Simple knobs
        on top of the defaults (Simple)."""
        saved = dict(self.mod.get("limiter") or {})
        if self.limiter_mode() != "simple":
            return saved
        values = {name: default for name, _l, _h, default in P17LIM_PARAMS}
        values.update({k: saved[k] for k in LIM_SIMPLE + ("enabled",) if k in saved})
        return values

    def set_limiter_mode(self, mode):
        if mode not in ("simple", "prism") or mode == self.limiter_mode():
            return
        self.mod["limiter_mode"] = mode
        values = self.effective_limiter()
        for name, _l, _h, default in P17LIM_PARAMS:   # every knob glides to its new value
            self.player.set_limiter_param(name, values.get(name, default))
        self.player.limiter_values = values
        self.schedule_save()

    def set_limiter_param(self, name, value):
        self.mod.setdefault("limiter", {})[name] = value
        if self.limiter_mode() == "simple" and name not in LIM_SIMPLE + ("enabled",):
            self.schedule_save()   # kept for Prism, not heard in Simple
            return
        self.player.set_limiter_param(name, value)
        self.schedule_save()

    def limiter_defaults(self):
        """Every limiter setting back to the plugin's default; the limiter stays on."""
        for name, _kind, _low, _high, default in self.player.limiter_params():
            if lim_key(name) in ("g-in", "g-out") and isinstance(default, float) and default > 1.0001:
                default = 1.0  # 0 dB, whatever the plugin reports
            self.player.set_limiter_param(name, True if lim_key(name) == "enabled" else default)
        self.player.limiter_values = {}

    def reset_limiter(self):
        self.limiter_defaults()
        self.mod["limiter"] = {}
        self.player.apply()
        self.schedule_save()
        if self.ui is not None:
            self.ui.refresh_limiter()
        self.flash_title("Limiter reset")


class SoundControls:
    """What the music and the video window share: their own equalizer (Prism EQ, knobs, limiter),
    their own master volume, and the small line that shows VST3 effects loading.
    The window sets EQ_KEY / EQ_ON_KEY / VOLUME_KEY: each window keeps its own sound."""

    EQ_KEY = "eq"
    EQ_ON_KEY = "eq_on"
    P17_KEY = "plugins17"
    VOLUME_KEY = "music_volume"
    EQ_TITLE = PEQ_NAME

    def load_eq_settings(self):
        saved = self.settings.get(self.EQ_KEY, {})
        eq = {**EQ_DEFAULTS, **(saved if isinstance(saved, dict) else {})}
        eq["limiter"] = dict(eq.get("limiter") or {})
        # The old limiter panel showed only part of the settings (no attack, release, mode)
        # and could leave the limiter switched off or at extreme gains: start once from the defaults.
        for name, value in list(eq["limiter"].items()):
            if lim_key(name) in LIM_MAX_0DB and isinstance(value, (int, float)) and value > 1.0:
                eq["limiter"][name] = 1.0
        engine = getattr(getattr(self, "player", None), "lv2_name", None) or ""
        if eq.get("limiter_engine") != engine:
            # LSP and the own limiter count differently (factor vs dB): start the new one clean
            eq["limiter"] = {}
            eq["limiter_engine"] = engine
        flag = f"{self.EQ_KEY}_limiter_v2"
        if not self.settings.get(flag):
            eq["limiter"] = {}
            self.settings[flag] = True
        if len(eq["bands"]) != 6:
            eq["bands"] = [0.0] * 6
        if not isinstance(eq.get("points"), list):
            # First start with Prism EQ: the six fader values become six points.
            eq["points"] = peq_default_points(eq["bands"])
        eq["points"] = [peq_clean(p) for p in eq["points"]]
        if eq.get("mode") not in ("prism", "simple"):
            eq["mode"] = "prism"
        simple = list(eq.get("simple") or [])
        eq["simple"] = [float(g) for g in simple[:10]] + [0.0] * max(0, 10 - len(simple))
        return eq

    # --- master volume (flat bar), separate for music and video ---
    def load_volume(self, fallback=1.0):
        try:
            value = float(self.settings.get(self.VOLUME_KEY, fallback))
        except (TypeError, ValueError):
            value = 1.0
        self.volume_value = max(0.0, min(1.0, value))
        self.player.set_volume(self.volume_value)
        if getattr(self, "volume_ctrl", None) is not None:
            self.volume_ctrl.set_value(self.volume_value, notify=False)

    def set_master_volume(self, value):
        self.volume_value = float(value)
        self.player.set_volume(self.volume_value)
        if not getattr(self, "_volume_save", 0):
            def flush():
                self._volume_save = 0
                self.settings[self.VOLUME_KEY] = round(self.volume_value, 3)
                save_settings(self.settings)
                return False

            self._volume_save = GLib.timeout_add(600, flush)

    # --- export: a second, silent player runs the same chain as fast as it can ---
    def export_plugins_on(self):
        return self.player.plugins_on

    def export_running(self):
        return getattr(self, "_export", None) is not None or getattr(self, "_mux_proc", None) is not None

    def render_job(self, source, target, encoder):
        """Everything the export needs, as plain data: the same Plugins 17 modules in the same
        order with the same settings, copies of the VST3 effects (their full state), tempo
        and volume. The export process builds its own chain from it."""
        live = self.player
        modules = []
        for unit in live.modules:
            if unit.kind == "eq":
                state = {"points": [dict(p) for p in unit.points], "bass_db": unit.bass_db,
                         "reverb_level": unit.reverb_level, "reverb_preset": unit.reverb_preset,
                         "crunch": unit.crunch}
            elif unit.kind == "sat":
                state = {"points": [dict(p) for p in unit.points], "drive_db": unit.drive_db, "mix": unit.mix,
                         "output_db": unit.output_db, "sat_type": unit.sat_type, "auto": unit.auto,
                         "mode": unit.mode, "bands": json.loads(json.dumps(unit.bands))}
            elif unit.kind == "ott":
                state = {"config": json.loads(json.dumps(unit.config))}
            else:
                state = {"limiter_values": dict(unit.limiter_values)}
            state["eq_on"] = bool(unit.eq_on)   # a switched-off module is in the chain, silent
            modules.append({"uid": unit.uid, "kind": unit.kind, "state": state})
        vst = []
        plugins_on = self.export_plugins_on() and bool(self.p17().get("all_on", True))
        if plugins_on and live.vst.available:
            with live.vst.lock:
                for slot in live.vst.slots:
                    if not slot["enabled"]:
                        continue
                    try:
                        state = base64.b64encode(bytes(slot["plugin"].raw_state)).decode()
                    except Exception:
                        state = ""
                    vst.append({"path": slot["path"], "name": slot["name"], "state": state,
                                "params": dict(slot["params"])})
        lv2 = [{"factory": s["factory"], "name": s["name"], "enabled": s.get("enabled", True),
                "params": dict(s.get("params", {})), "kinds": dict(s.get("kinds", {}))} for s in live.lv2_slots]
        return {
            "source": source, "target": target, "encoder": encoder, "video": live.video,
            "modules": modules, "vst": vst, "lv2": lv2, "plugins_on": plugins_on,
            "tempo": live.tempo, "master_tempo": live.master_tempo,
            "volume": float(live.pipe.get_property("volume")),
        }

    def start_render(self, source, target, encoder, finished, name, heading="Saving the track with the effects"):
        """Write the sound of `source` through this window's effects to `target`, in the
        background: a separate process with its own copies of every effect, so what plays now
        is never paused or slowed down (and a plugin that crashes there takes only the export
        with it). finished(ok, cancelled) is called at the end; the progress window stays open
        until close_export_dialog() (the video export still has a second step).
        The file sounds exactly as heard, the volume bar included."""
        if self.export_running():
            self.flash_title("An export is already running")
            if getattr(self, "_export_dialog", None) is not None:
                self._export_dialog.present()
            return
        cache = Path(GLib.get_user_cache_dir()) / "player-17"
        cache.mkdir(parents=True, exist_ok=True)
        job_file = cache / f"export-job-{os.getpid()}-{int(time.time() * 1000)}.json"
        job_file.write_text(json.dumps(self.render_job(source, target, encoder)))
        try:
            proc = subprocess.Popen([named_python(sys.executable, "Player-17-Export"), os.path.abspath(__file__), "--render", str(job_file)],
                                    stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        except OSError as exc:
            print("Export:", exc)
            job_file.unlink(missing_ok=True)
            finished(False, False)
            return

        self._export = {"proc": proc, "target": target, "finished": finished, "job": job_file}
        self._export_dialog = ExportDialog(self, name, self.cancel_export, heading)
        self._export_dialog.present()

        def progress(value):
            if getattr(self, "_export_dialog", None) is not None:
                self._export_dialog.bar.set_fraction(max(0.0, min(1.0, value)))
            return False

        def read():
            ok = False
            for line in proc.stdout:
                line = line.strip()
                if line.startswith("P "):
                    try:
                        GLib.idle_add(progress, float(line[2:]))
                    except ValueError:
                        pass
                elif line == "DONE":
                    ok = True
            err = proc.stderr.read()
            proc.wait()
            if not ok and err.strip():
                print("Export:", err.strip())
            GLib.idle_add(self.render_done, ok and proc.returncode == 0, False, proc)

        threading.Thread(target=read, daemon=True).start()

    def render_done(self, ok, cancelled=False, proc=None):
        job = getattr(self, "_export", None)
        if job is None or (proc is not None and job["proc"] is not proc):
            return False
        self._export = None
        if job["proc"].poll() is None:
            try:
                job["proc"].kill()
            except OSError:
                pass
        job["job"].unlink(missing_ok=True)
        if not ok:
            try:
                os.remove(job["target"])  # a half-written file is no use
            except OSError:
                pass
        job["finished"](ok, cancelled)
        return False

    def cancel_export(self):
        if getattr(self, "_export", None) is not None:
            self.render_done(False, cancelled=True)
            return
        proc = getattr(self, "_mux_proc", None)
        if proc is not None:  # the video export is joining picture and sound
            self._mux_cancelled = True
            try:
                proc.kill()
            except OSError:
                pass

    def close_export_dialog(self):
        if getattr(self, "_export_dialog", None) is not None:
            self._export_dialog.destroy()
            self._export_dialog = None

    # --- VST3 loading line inside the search field ---
    def vst_progress(self, done, total, name=""):
        strip = getattr(self, "load_strip", None)
        if strip is not None:
            strip.show_progress(done, total, name)

    def vst_progress_end(self):
        strip = getattr(self, "load_strip", None)
        if strip is not None:
            strip.finish()

    def flash_title(self, text):
        """Show a short message in place of the track title for two seconds."""
        old = self.title_label.get_text()
        self.title_label.set_text(text)

        def back():
            if self.title_label.get_text() == text:
                self.title_label.set_text(old)
            return False

        GLib.timeout_add(2000, back)

    # ================= Plugins 17: the player's own modules =================
    def p17(self):
        """The state of the Plugins window, kept in the settings:
        modules = [{"id", "type": "eq" / "limiter", "on", "eq": {...} or "limiter": {...}}, ...]
        in the order the sound goes through them. Older settings are taken over once:
        the old equalizer and limiter become the first two modules, with their sound."""
        data = self.settings.get(self.P17_KEY)
        if not isinstance(data, dict):
            data = {
                "modules": ["eq", "limiter"],
                "eq_on": bool(self.settings.get(self.EQ_ON_KEY, True)),
                "limiter_on": True,
                "on": True,             # the Plugins 17 tab switch
                "all_on": True,         # the main switch next to the overload meter
                "unlimited": False,     # Plugins 17: more than P17_LIMIT modules allowed
                "vst_unlimited": False, # VST: more than P17_LIMIT plugins allowed
                "vst_on": True,         # VST tab switch (the video window; music keeps its own)
            }
            self.settings[self.P17_KEY] = data
        modules = data.get("modules")
        if not isinstance(modules, list):
            modules = data["modules"] = ["eq", "limiter"]
        if any(isinstance(m, str) for m in modules):
            # From the first Plugins window (one module of each kind, names only).
            old = self.eq_settings
            limiter = dict(old.get("limiter") or {})
            limiter_on = bool(data.get("limiter_on", True))
            for name, value in list(limiter.items()):
                if lim_key(name) == "enabled" and value is False:
                    limiter_on = False  # the old inner switch becomes the module switch
                    limiter[name] = True
            new = []
            for m in modules:
                if m == "eq":
                    new.append({"id": "eq1", "type": "eq", "on": bool(data.get("eq_on", True)),
                                "eq": clean_eq_settings(json.loads(json.dumps(old)))})
                elif m == "limiter":
                    new.append({"id": "lim1", "type": "limiter", "on": limiter_on, "limiter": limiter,
                                "engine": self.player.lv2_name or ""})
                elif isinstance(m, dict):
                    new.append(m)
            data["modules"] = modules = new
            data["next"] = 2
            save_settings(self.settings)
        if getattr(self, "_p17_checked", False):
            return data
        self._p17_checked = True  # the rest runs once per start
        for m in modules:
            if not isinstance(m, dict):
                continue
            if m.get("type") == "eq":
                m["eq"] = clean_eq_settings(m.get("eq"))
            elif m.get("type") == "sat":
                m["sat"] = clean_sat_settings(m.get("sat"))
            elif m.get("type") == "ott":
                m["ott"] = clean_ott_settings(m.get("ott"))
            elif m.get("type") == "limiter":
                engine = self.player.lv2_name or ""
                if m.get("engine") != engine:
                    # The own limiter and LSP count differently (dB vs factor): start clean.
                    m["limiter"], m["engine"] = {}, engine
                m.setdefault("limiter", {})
        data["modules"] = [m for m in modules if isinstance(m, dict) and m.get("type") in MODULE_UNITS
                           and m.get("id")]
        data.setdefault("next", len(data["modules"]) + 1)
        return data

    def module_ctls(self):
        """A ModuleCtl for every module, in the chain order (made the first time it is needed)."""
        ctls = getattr(self, "_module_ctls", None)
        if ctls is None:
            ctls = self._module_ctls = {}
        modules = self.p17()["modules"]
        for m in modules:
            ctl = ctls.get(m["id"])
            if ctl is None or ctl.mod is not m:
                ctl = ModuleCtl(self, m)
                ctl.load_into_unit()
                ctls[m["id"]] = ctl
        for uid in [u for u in ctls if u not in {m["id"] for m in modules}]:
            ctls.pop(uid)
            self.player.forget_unit(uid)
        return [ctls[m["id"]] for m in modules]

    def module_live(self, mod):
        """Is this module really in the sound: its own switch, the tab, the main switch."""
        data = self.p17()
        return bool(mod.get("on", True)) and bool(data.get("on", True)) and bool(data.get("all_on", True))

    def apply_modules(self):
        """The modules that are on go into the sound, in their order (a new chain only if
        that changed)."""
        ctls = self.module_ctls()
        self.player.set_modules([ctl.player for ctl in ctls],
                                [ctl.player for ctl in ctls if self.module_live(ctl.mod)])
        hub = getattr(self, "plugins_hub", None)
        if hub is not None:
            hub.show_states()

    def apply_eq(self):
        """Every saved module value onto the player at once (one new chain at most)."""
        for ctl in self.module_ctls():
            ctl.load_into_unit()
        self.apply_modules()

    def find_module(self, uid):
        return next((m for m in self.p17()["modules"] if m["id"] == uid), None)

    def set_module_on(self, uid, on):
        mod = self.find_module(uid)
        if mod is not None:
            mod["on"] = bool(on)
            save_settings(self.settings)
            self.apply_modules()

    def add_module(self, kind):
        """A new module at the end of the chain, with default settings. None: the limit."""
        data = self.p17()
        if not data.get("unlimited", False) and len(data["modules"]) >= P17_LIMIT:
            return None
        number = int(data.get("next", 1))
        data["next"] = number + 1
        prefix = {"eq": "eq", "sat": "sat", "ott": "ott"}.get(kind, "lim")
        uid = f"{prefix}{number}"
        while self.find_module(uid) is not None:
            number += 1
            data["next"] = number + 1
            uid = f"{prefix}{number}"
        if kind == "eq":
            mod = {"id": uid, "type": "eq", "on": True, "eq": clean_eq_settings({})}
        elif kind == "sat":
            mod = {"id": uid, "type": "sat", "on": True, "sat": clean_sat_settings({})}
        elif kind == "ott":
            mod = {"id": uid, "type": "ott", "on": True, "ott": clean_ott_settings({})}
        else:
            mod = {"id": uid, "type": "limiter", "on": True, "limiter": {}, "engine": self.player.lv2_name or ""}
        data["modules"].append(mod)
        save_settings(self.settings)
        self.apply_modules()
        return mod

    def remove_module(self, uid):
        data = self.p17()
        data["modules"] = [m for m in data["modules"] if m["id"] != uid]
        save_settings(self.settings)
        self.apply_modules()

    def move_module(self, uid, to_index):
        """Change the order of the sound: this module goes to place `to_index`."""
        modules = self.p17()["modules"]
        mod = self.find_module(uid)
        if mod is None:
            return
        modules.remove(mod)
        modules.insert(max(0, min(to_index, len(modules))), mod)
        save_settings(self.settings)
        self.apply_modules()

    def refresh_module_panels(self):
        for ctl in self.module_ctls():
            ctl.refresh_ui()

    def set_p17_tab_on(self, on):
        self.p17()["on"] = bool(on)
        save_settings(self.settings)
        self.apply_modules()

    def set_all_plugins_on(self, on):
        """The main switch: every plugin, ours and VST, at once."""
        self.p17()["all_on"] = bool(on)
        save_settings(self.settings)
        self.apply_modules()
        self.apply_plugin_state()

    # --- the VST tab switch (the music window has its own version: music / radio) ---
    def vst_tab_on(self):
        return bool(self.p17().get("vst_on", True))

    def set_vst_tab_on(self, on):
        self.p17()["vst_on"] = bool(on)
        save_settings(self.settings)
        self.apply_plugin_state()

    def apply_plugin_state(self, reload=True):
        on = self.vst_tab_on() and bool(self.p17().get("all_on", True))
        self.player.vst.set_bypass(not on)
        self.player.set_plugins_on(on, reload=reload)

    def open_hub(self, tab="p17"):
        """The Plugins window: tabs Plugins 17 and VST, the overload meter, the main switch."""
        pop = getattr(self, "prefs_popover", None)
        if pop is not None:
            pop.popdown()
        if getattr(self, "plugins_hub", None) is None:
            self.plugins_hub = PluginsHub(self)
        self.plugins_hub.show_tab(tab)
        self.plugins_hub.show_states()  # switches may have changed elsewhere (Preferences, radio)
        bring_to_front(self.plugins_hub)  # Plugins: always in front, even when the player covered it

    def schedule_save(self):
        if not self._save_pending:
            self._save_pending = True
            GLib.timeout_add(500, self.flush_eq_save)

    def flush_eq_save(self):
        self._save_pending = False
        self.settings[self.EQ_KEY] = self.eq_settings
        save_settings(self.settings)
        return False

    def open_eq(self, *_):
        self.open_hub("p17")


class MainWindow(Adw.ApplicationWindow, SoundControls):
    def __init__(self, app):
        super().__init__(application=app, title="Player-17")
        self.expanded = False
        self.current_scale = 1.0
        self._last_size = (0, 0)
        # --- radio ---
        self.radio_mode = False      # the list on the right shows radio stations
        self.radio_active = False    # the player holds a station (not a track)
        self.station = None          # the station that is on
        self.stations = []           # the last search result
        self.station_order = []      # stations in the order they are shown (next / previous)
        self.station_rows = {}       # uuid -> (row, playing bars)
        self.station_of_row = {}
        self.radio_now = ""          # the song the station says is on
        self._radio_search = 0
        self._radio_query = None
        self._radio_retries = 0
        self._radio_started = 0.0
        self.recorder = None         # a radio recording in progress
        # --- browser ---
        self.web_mode = False        # the right side shows the browser
        self.web_route = WebAudioRoute()
        self.browser = BrowserProcess(self.on_browser_event)
        self.browser_visible = False
        self._web_title = ""
        self.rec_station = None
        self.set_default_size(COMPACT_W, WIN_H)

        # Second stylesheet: text sizes, rewritten whenever the window scale changes.
        self.scale_provider = Gtk.CssProvider()
        Gtk.StyleContext.add_provider_for_display(
            Gdk.Display.get_default(), self.scale_provider,
            Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION + 1,
        )

        root = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=12)
        root.add_css_class("main")
        root.set_margin_top(8)
        root.set_margin_bottom(16)
        root.set_margin_start(32)
        root.set_margin_end(32)

        toolbar = Adw.ToolbarView()
        self.toolbar = toolbar
        toolbar.add_top_bar(self.build_header())
        toolbar.set_content(root)
        self.set_content(toolbar)

        # 10 equal columns: player = 3 (30%), track list = 7 (70%) in full mode.
        # Player | track list, with a handle in between: drag it to change the widths.
        self.body = Gtk.Paned(orientation=Gtk.Orientation.HORIZONTAL, vexpand=True, wide_handle=False)
        self.player_col = self.build_player_column()
        self.track_area = self.build_track_area()
        self.body.set_start_child(self.player_col)
        self.body.set_end_child(self.track_area)
        self.body.set_shrink_start_child(False)
        self.body.set_shrink_end_child(False)
        # Resizing the window changes only the list on the right; the player keeps its width.
        self.body.set_resize_start_child(False)
        self.body.set_resize_end_child(True)
        self.split_px = 0            # player width in full mode (0 = 30% of the window the first time)
        self._split_width = 0        # 0 = the handle still has to be placed after a mode change
        self._placing_split = False
        self._split_save = 0
        self.body.connect("notify::position", self.on_split_moved)
        root.append(self.body)

        self.apply_mode(first=True)
        self.apply_scale(1.0)
        self._shown_once = False
        self.connect("map", self.on_first_map)
        self.add_tick_callback(self.on_tick)

        # --- music ---
        self.settings = shared_settings()
        try:
            self.split_px = max(0, int(self.settings.get("split_px", 0)))
        except (TypeError, ValueError):
            self.split_px = 0
        self.music_dir = Path(self.settings.get("music_dir") or DEFAULT_MUSIC_DIR)
        self.tracks, self.infos = [], []
        self.order = []                 # track numbers in the order they are shown
        self.index = 0
        self.category = self.settings.get("category", "track")
        if self.category not in CATEGORIES:
            self.category = "track"
        self.ratings = dict(self.settings.get("ratings", {}))      # path -> 1..5
        self.favorites = set(self.settings.get("favorites", []))   # paths
        self.tempos = dict(self.settings.get("tempos", {}))        # path -> saved BPM
        self.saved_bpm = None
        self.playlists = {k: list(v) for k, v in self.settings.get("playlists", {}).items()}
        self.row_track = {}             # list row -> track number
        self.row_stars = {}             # track number -> its 5 star buttons
        self.row_bars = {}              # track number -> its "playing" bars (shown on one row only)
        self.row_names = {}             # track number -> its title (moved by the slider under the list)
        self.row_of = {}                # track number -> its list row
        self.removed = set()            # tracks moved to the Trash in this session
        self.scan_id = 0                # number of the newest folder scan
        self._rows_left = []
        self.base_bpm = DEFAULT_BPM
        self.bpm = DEFAULT_BPM
        self.repeat_mode = self.settings.get("repeat", "all")   # off / all / one
        if self.repeat_mode not in ("off", "all", "one"):
            self.repeat_mode = "all"
        self.shuffle = bool(self.settings.get("shuffle", False))
        self.analysis = dict(self.settings.get("bpm_analysis", {}))   # path -> {"bpm", "mtime"}
        self.analysis_queue = deque()
        self._analysing = None          # the file being analysed now
        self._analysis_save = 0
        self.play_history = []          # for "previous" while shuffle is on
        lv2_chain = [
            {"factory": item["factory"], "name": item.get("name") or item["factory"],
             "enabled": item.get("enabled", True), "params": dict(item.get("params") or {})}
            for item in self.settings.get("lv2_chain") or []
            if LV2_EFFECTS and isinstance(item, dict) and item.get("factory")
            and Gst.ElementFactory.find(item["factory"])
        ]
        for slot in lv2_chain:
            slot["kinds"] = {s[0]: s[1] for s in lv2_specs(slot["factory"])}
        self.player = Player(self.on_track_end, lv2_chain, on_play=lambda: app.pause_others(self))
        # The sample rate chosen in Plugins. "Auto" = as the output device: the chain always runs
        # at one fixed rate (with "as the track" it was rebuilt on every track and could get
        # stuck at 0:00 in silence).
        self.player.set_out_rate(self.music_out_rate())
        # "Repeat: this track" loops without a seam (see Player._about_to_finish)
        self.player.loop_one = lambda: (getattr(self, "repeat_mode", "off") == "one"
                                        and not getattr(self, "radio_active", False))
        self.player.on_tag = self.on_radio_tag
        self.player.on_error = self.on_player_error
        self.radio_favorites = [
            s for s in self.settings.get("radio_favorites") or []
            if isinstance(s, dict) and s.get("url") and s.get("uuid")
        ]
        self._closed = False
        self.player.master_tempo = bool(self.settings.get("master_tempo", True))
        self.eq_settings = self.load_eq_settings()
        self.eq_window = None
        self._save_pending = False
        self.apply_eq()
        self.load_volume(self.eq_settings.get("volume", 1.0))  # older settings kept it in the EQ
        self.apply_plugin_state(reload=False)
        self.connect_player_controls()

        self.build_prefs_popover()
        self.search.connect("search-changed", self.on_search_changed)
        self.track_list.set_filter_func(self.filter_row)
        self.track_list.set_sort_func(self.sort_rows)
        self.track_list.set_header_func(self.row_header)
        self.track_list.connect("row-activated", self.on_row_activated)
        GLib.timeout_add(250, self.update_progress)
        self.connect("close-request", self.on_close)
        self.mpris = Mpris(self)
        self.add_space_key()
        add_file_drop(self, self.toolbar, self.on_media_dropped)
        self.load_library(self.music_dir)
        track_input(self)
        GLib.timeout_add(1500, lambda: self.restore_vst() or False)  # after the window is drawn

    # --- compact / full mode: the arrow shows or hides the track list and the search ---
    def on_first_map(self, *_):
        self._shown_once = True  # the window manager animates the window itself

    def toggle_tracks(self, *_):
        """The arrow: the window slides open (list fades in) or the list fades out and the
        window slides closed."""
        if getattr(self, "_mode_anim", None) is not None:
            return  # still moving
        self.expanded = not self.expanded
        if self.expanded:
            # The player stays exactly where it is and the list grows out of its right side
            # (before, the list appeared squeezed into the small window and pushed the player).
            self._open_split = self.player_col.get_width()
            self.body.set_shrink_end_child(True)  # the list may be narrower than usual while opening
            self.track_area.set_opacity(0.0)
            self.search_box.set_opacity(0.0)
            self.apply_mode(animate=True)
            animate_opacity(self.track_area, 0.0, 1.0, 360)
            animate_opacity(self.search_box, 0.0, 1.0, 360)
        elif self.is_maximized() or self.is_fullscreen() or self.get_width() <= 0:
            self.expanded = True  # keep the list on screen while it fades out
            animate_opacity(self.track_area, 1.0, 0.0, 160)
            animate_opacity(self.search_box, 1.0, 0.0, 160)

            def close():
                self.expanded = False
                self.apply_mode(animate=True)
                self.track_area.set_opacity(1.0)
                self.search_box.set_opacity(1.0)
                return False

            GLib.timeout_add(170, close)
        else:
            # The mirror of opening: the list stays while the window slides closed, the player
            # glides back to its compact width, the list fades and is swallowed on the way.
            self.expanded = True
            k = EXPANDED_W / COMPACT_W
            self.animate_close(round(self.get_width() / k), self.get_height())

    def animate_width(self, width, height):
        """Resize the window smoothly (about a quarter of a second)."""
        self._resizing = True
        start_w = self.get_width()
        split_from, self._open_split = getattr(self, "_open_split", 0), 0
        split_to = 0
        if split_from and self.expanded and width != start_w:
            # Where the handle will end up (the same rule as place_split), so the player
            # glides to its full-mode width together with the window, without a jump at the end.
            final_body = self.body.get_width() + (width - start_w)
            wanted = self.split_px or round(final_body * 0.30)
            split_to = max(180, min(wanted, final_body - 260))

        def set_split(t):
            self._placing_split = True
            self.body.set_position(round(split_from + (split_to - split_from) * t))
            self._placing_split = False
            self.player_col.set_margin_end(round(20 * t))

        if split_to:
            set_split(0.0)

        def step(value):
            self.set_default_size(round(value), height)
            if split_to:
                set_split(max(0.0, min(1.0, (value - start_w) / (width - start_w))))

        def done(*_):
            self._mode_anim = None
            self._resizing = False
            self.body.set_shrink_end_child(False)
            self.player_col.set_margin_end(20 if self.expanded else 0)
            self.set_default_size(width, height)
            self._split_width = 0  # now put the handle where it belongs
            return False

        try:
            anim = Adw.TimedAnimation.new(self, self.get_width(), width, 280, Adw.CallbackAnimationTarget.new(step))
            anim.set_easing(Adw.Easing.EASE_IN_OUT_CUBIC)
            anim.connect("done", done)
            self._mode_anim = anim
            anim.play()
        except Exception:
            done()

    def animate_close(self, width, height):
        """Full -> compact, exactly the reverse of the opening slide (same time, same easing)."""
        self._resizing = True
        start_w = self.get_width()
        split_from = self.body.get_position()
        split_to = max(1, self.body.get_width() + (width - start_w))  # the player takes the whole body
        self.body.set_shrink_end_child(True)  # the list may get narrower than usual while closing

        def progress(value):
            return 1.0 if start_w == width else max(0.0, min(1.0, (start_w - value) / (start_w - width)))

        def step(value):
            t = progress(value)
            self.set_default_size(round(value), height)
            self._placing_split = True
            self.body.set_position(round(split_from + (split_to - split_from) * t))
            self._placing_split = False
            self.player_col.set_margin_end(round(20 * (1.0 - t)))
            fade = max(0.0, 1.0 - t * 1.6)  # the list is gone a little before the window stops
            self.track_area.set_opacity(fade)
            self.search_box.set_opacity(fade)
            if t >= 0.6 and self.search_box.get_visible():
                self.search_box.set_visible(False)  # so the header lets the window get narrow

        def done(*_):
            self._mode_anim = None
            self.expanded = False
            self.apply_mode(resize=False)
            self._resizing = False
            self.body.set_shrink_end_child(False)
            self.track_area.set_opacity(1.0)
            self.search_box.set_opacity(1.0)
            self.set_default_size(width, height)
            self._split_width = 0
            return False

        try:
            anim = Adw.TimedAnimation.new(self, start_w, width, 280, Adw.CallbackAnimationTarget.new(step))
            anim.set_easing(Adw.Easing.EASE_IN_OUT_CUBIC)
            anim.connect("done", done)
            self._mode_anim = anim
            anim.play()
        except Exception:
            done()

    def apply_mode(self, first=False, animate=False, resize=True):
        full = self.expanded
        self.track_area.set_visible(full)
        self.search_box.set_visible(full)
        self.rescan_btn.set_visible(full and not self.radio_mode and not self.web_mode)
        self.home_btn.set_visible(full and not self.radio_mode and self.category != "track")
        self.place_right_group(full)

        self.player_col.set_margin_end(20 if full else 0)
        self._split_width = 0  # place the handle again once the window has its new size

        self.back_btn.get_child().set_from_icon_name(
            "go-previous-symbolic" if full else "go-next-symbolic"
        )

        if not resize:  # the size was already set by the closing slide
            self._open_split = 0
            return

        # Keep the same proportions: the window grows or shrinks by the same factor.
        if first or self.get_width() <= 0:
            w, h = (EXPANDED_W if full else COMPACT_W), WIN_H
        else:
            k = EXPANDED_W / COMPACT_W
            w = round(self.get_width() * (k if full else 1 / k))
            h = self.get_height()
        if animate and not first and not self.is_maximized() and not self.is_fullscreen():
            self.animate_width(w, h)
        else:
            self._open_split = 0
            self.body.set_shrink_end_child(False)
            self.set_default_size(w, h)

    # --- scaling: icons and text follow the size of the player column ---
    # --- the handle between the player and the list ---
    def place_split(self):
        """Put the handle where it was last left (once, after switching to full mode)."""
        width = self.body.get_width()
        if not self.expanded or width <= 0:
            return
        wanted = self.split_px or round(width * 0.30)
        self._placing_split = True
        self.body.set_position(max(180, min(wanted, width - 260)))
        self._placing_split = False
        self._split_width = width

    def on_split_moved(self, *_):
        if self._placing_split or not self.expanded or not self._split_width:
            return
        self.split_px = self.body.get_position()  # moved by hand: remember the player width
        if not self._split_save:
            def save():
                self._split_save = 0
                self.settings["split_px"] = self.split_px
                save_settings(self.settings)
                return False

            self._split_save = GLib.timeout_add(600, save)

    def on_tick(self, widget, clock):
        # Just switched to full mode: put the handle where it was. Later window resizes
        # do not move it (only the list changes size).
        if (self.expanded and not self._split_width and self.body.get_width() > 0
                and not getattr(self, "_resizing", False)):
            self.place_split()
        w, h = self.player_col.get_width(), self.player_col.get_height()
        if w > 0 and h > 0:
            lw, lh = self._last_size
            if abs(w - lw) >= 6 or abs(h - lh) >= 6:
                self._last_size = (w, h)
                scale = min(w / BASE_COL_W, h / BASE_COL_H)
                debug_log(f"player column {w}x{h}, window {self.get_width()}x{self.get_height()}, "
                          f"scale {max(MIN_SCALE, min(MAX_SCALE, scale)):.2f}")
                self.apply_scale(max(MIN_SCALE, min(MAX_SCALE, scale)))
        return GLib.SOURCE_CONTINUE

    def apply_scale(self, s):
        self.current_scale = s
        for img, base in SCALABLE:
            img.set_pixel_size(max(8, round(base * s)))
        self.scale_provider.load_from_string(
            f".title {{ font-size: {22 * s:.1f}px; }}\n"
            f".track {{ font-size: {24 * s:.1f}px; }}\n"
            f".bpm {{ font-size: {15 * s:.1f}px; }}\n"
            f".row-icon {{ -gtk-icon-size: {15 * s:.1f}px; }}\n"
            f".time {{ font-size: {13 * s:.1f}px; }}\n"
            f".star {{ font-size: {20 * s:.1f}px; }}\n"
            f".row-star {{ font-size: {15 * s:.1f}px; }}\n"
            f".group-head {{ font-size: {18 * s:.1f}px; }}\n"
        )

    # --- library: read in the background; the music that plays is never touched ---
    # The list is updated in place: new files get a row, files that are gone lose theirs,
    # changed tags are shown. Track numbers never change, so the playing track, the
    # "previous" history and the BPM analysis all stay valid. (A file that is gone stays in
    # self.tracks, marked in self.removed, like a track moved to the Trash.)
    def load_library(self, folder):
        folder = Path(folder)
        self.scan_id += 1
        scan_id = self.scan_id
        self.path_label.set_text(str(folder))
        if not self.tracks:
            self.hint.set_text("Looking for music...")
        # What is known already: unchanged files are not read again (fast rescans).
        known = {}
        mtimes = getattr(self, "track_mtimes", {})
        for i, path in enumerate(self.tracks):
            if path in mtimes:
                known[path] = (mtimes[path], self.infos[i])

        def work():
            paths = scan_music(folder) if folder.exists() else []
            found = []
            for path in paths:
                try:
                    mtime = os.path.getmtime(path)
                except OSError:
                    continue
                old = known.get(path)
                info = old[1] if old and old[0] == mtime else read_tags(path, with_cover=False)
                found.append((path, mtime, info))
            GLib.idle_add(self.on_scan_done, scan_id, folder, found)

        threading.Thread(target=work, daemon=True).start()

    def on_scan_done(self, scan_id, folder, found):
        if scan_id != self.scan_id:
            return False  # a newer scan was started meanwhile
        self.track_mtimes = getattr(self, "track_mtimes", {})
        index_of = {path: i for i, path in enumerate(self.tracks)}
        wanted = {path for path, _m, _i in found}
        current = self.tracks[self.index] if self.tracks and 0 <= self.index < len(self.tracks) else None
        self._library_changes = {"added": 0, "gone": 0, "changed": 0}

        # Gone (deleted, renamed, or another folder was chosen): the row goes away.
        # The track that is loaded now keeps its row while it still exists (another folder).
        for path, i in index_of.items():
            if path in wanted or i in self.removed:
                continue
            if path == current and os.path.exists(path):
                continue
            self.remove_track_row(i)
            self._library_changes["gone"] += 1

        # New, back again, or with changed tags.
        self._rows_left = []
        for path, mtime, info in found:
            self.track_mtimes[path] = mtime
            i = index_of.get(path)
            if i is None:
                i = len(self.tracks)
                self.tracks.append(path)
                self.infos.append(info)
                self._rows_left.append(i)
                self._library_changes["added"] += 1
            elif i in self.removed or i not in self.row_of:
                self.removed.discard(i)
                self.infos[i] = info
                self._rows_left.append(i)
                self._library_changes["added"] += 1
            elif info is not self.infos[i] and info != self.infos[i]:
                self.infos[i] = info
                self.update_track_row(i)
                self._library_changes["changed"] += 1
        self._rows_left.reverse()  # popped from the end: first file first
        GLib.idle_add(self.add_rows_batch, scan_id, folder)
        return False

    def remove_track_row(self, index):
        """Take a track out of the list (its ratings, favorites and saved tempo are kept:
        the file may come back). The sound is not touched."""
        self.removed.add(index)
        row = self.row_of.pop(index, None)
        if row is not None:
            self.track_list.remove(row)
            self.row_track.pop(row, None)
        self.row_bars.pop(index, None)
        self.row_names.pop(index, None)
        self.row_stars.pop(index, None)
        try:
            self.analysis_queue.remove(self.tracks[index])
        except ValueError:
            pass

    def update_track_row(self, index):
        """The tags of a file changed: show the new title."""
        info = self.infos[index]
        name = self.row_names.get(index)
        if name is not None:
            text = f"{info['title']} - {info['artist']}" if info["artist"] else info["title"]
            name.set_text(text)
            name.set_tooltip_text(text)
        if index == self.index and not self.radio_active:
            label = info["title"] if not info["artist"] else f"{info['title']} - {info['artist']}"
            self.title_label.set_text(label)

    def add_rows_batch(self, scan_id, folder):
        """Add the rows 25 at a time so a big library does not block the window."""
        if scan_id != self.scan_id:
            return False
        for _ in range(25):
            if not self._rows_left:
                break
            i = self._rows_left.pop()
            self.add_track(i, self.infos[i])
        if self._rows_left:
            return True
        self.finish_library(folder)
        return False

    def rescan_library(self):
        """Read the folder again in the background; whatever plays goes on untouched."""
        self.rescan_btn.get_child().add_css_class("spinning")
        self._rescan_by_hand = True
        self.load_library(self.music_dir)

    def open_files(self, paths):
        """Files opened from the file manager ("Open with Player-17") or the command line."""
        if getattr(self, "_library_ready", False):
            self.play_files(paths)
        else:
            self._open_after_scan = list(paths)  # played as soon as the library is read

    def live_tracks(self):
        return [i for i in range(len(self.tracks)) if i not in self.removed]

    def finish_library(self, folder):
        first_time = not getattr(self, "_library_ready", False)
        self._library_ready = True
        waiting, self._open_after_scan = getattr(self, "_open_after_scan", None), None
        if waiting:
            GLib.idle_add(lambda: self.play_files(waiting) and False)
        self.rescan_btn.get_child().remove_css_class("spinning")

        # BPM analysis for what is new (what was there keeps its place in the queue).
        for i in self.live_tracks():
            path = self.tracks[i]
            if self.analysed_bpm(path) is None and path not in self.analysis_queue and path != self._analysing:
                self.analysis_queue.append(path)
        self.run_analysis()

        if self.radio_mode or self.web_mode:  # that view stays on screen; the music list is ready behind it
            self.order = sorted(self.live_tracks(), key=self.sort_key)
            self.track_list.invalidate_sort()
            self.track_list.invalidate_headers()
            self.track_list.invalidate_filter()
        else:
            self.refresh_category()
        self.apply_scale(self.current_scale)  # new rows get the right icon size

        live = self.live_tracks()
        changes = getattr(self, "_library_changes", {})
        by_hand, self._rescan_by_hand = getattr(self, "_rescan_by_hand", False), False
        if not live:
            self.hint.set_text("No music files found")
            if not self.player.playing and not self.radio_active:
                self.title_label.set_text("No music found")
                self.update_fav_icon()
                self.set_cover(None)
            print(f"No music files found in {folder}")
            return
        nothing_loaded = self.index in self.removed or self.player.uri is None
        if nothing_loaded and not self.radio_active and not self.player.playing:
            # First start (or the loaded track is gone and nothing plays): get the first one ready.
            self.load_track(self.order[0] if self.order else live[0])
        elif not first_time and (by_hand or any(changes.values())):
            parts = []
            if changes.get("added"):
                parts.append(f"+{changes['added']}")
            if changes.get("gone"):
                parts.append(f"-{changes['gone']}")
            note = f" ({', '.join(parts)})" if parts else ""
            self.flash_title(f"{len(live)} tracks{note}")

    def choose_folder(self, *_):
        dialog = Gtk.FileDialog(title="Choose your music folder")
        dialog.select_folder(self, None, self.on_folder_chosen)

    def on_folder_chosen(self, dialog, result):
        try:
            folder = dialog.select_folder_finish(result)
        except GLib.Error:
            return  # cancelled
        path = folder.get_path()
        if path:
            self.music_dir = Path(path)
            self.settings["music_dir"] = path
            save_settings(self.settings)
            self.prefs_popover.popdown()
            self.load_library(self.music_dir)

    def build_prefs_popover(self):
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
        for side in ("top", "bottom", "start", "end"):
            getattr(box, f"set_margin_{side}")(16)
        box.set_size_request(280, -1)

        title = Gtk.Label(label="Preferences", xalign=0)
        title.add_css_class("prefs-title")
        box.append(title)
        line = Gtk.Box()
        line.add_css_class("prefs-line")
        box.append(line)

        cat_head = Gtk.Label(label="library categories", xalign=0)
        cat_head.add_css_class("prefs-head")
        box.append(cat_head)
        flow = Gtk.FlowBox(selection_mode=Gtk.SelectionMode.NONE, homogeneous=False)
        flow.set_min_children_per_line(3)
        flow.set_max_children_per_line(3)
        self.cat_dots = {}
        for key in CATEGORIES:
            btn = Gtk.Button()
            btn.add_css_class("flat")
            btn.add_css_class("cat-btn")
            inner = Gtk.Box(spacing=6)
            dot = Gtk.Box(valign=Gtk.Align.CENTER)
            dot.add_css_class("cat-dot")
            inner.append(dot)
            inner.append(Gtk.Label(label=key))
            btn.set_child(inner)
            btn.connect("clicked", lambda _b, k=key: self.set_category(k))
            flow.append(btn)
            self.cat_dots[key] = dot
        box.append(flow)
        line2 = Gtk.Box()
        line2.add_css_class("prefs-line")
        box.append(line2)

        player_head = Gtk.Label(label="player settings", xalign=0)
        player_head.add_css_class("prefs-head")
        box.append(player_head)
        plugins_btn = Gtk.Button(label="Plugins", halign=Gtk.Align.START)
        plugins_btn.add_css_class("flat")
        plugins_btn.set_tooltip_text("Plugins 17 (Prism EQ 17, Limiter 17) and VST")
        plugins_btn.connect("clicked", self.open_eq)
        box.append(plugins_btn)
        colors_btn = Gtk.Button(label="Color and background", halign=Gtk.Align.START)
        colors_btn.add_css_class("flat")
        colors_btn.connect("clicked", self.open_colors)
        box.append(colors_btn)

        mt_row = Gtk.Box(spacing=10)
        mt_text = Gtk.Label(label="Master Tempo", xalign=0, hexpand=True)
        mt_text.set_margin_start(10)  # lined up with the buttons above
        mt_row.append(mt_text)
        mt_switch = Gtk.Switch(active=self.player.master_tempo, valign=Gtk.Align.CENTER)
        mt_switch.set_tooltip_text(
            "On: the tempo changes, the key stays (attacks can get a little softer).\n"
            "Off: like vinyl, a clean kick, the key moves with the tempo."
        )
        mt_switch.connect("notify::active", lambda sw, _p: self.set_master_tempo(sw.get_active()))
        mt_row.append(mt_switch)
        box.append(mt_row)
        pl_row = Gtk.Box(spacing=10)
        self.plugins_text = Gtk.Label(label="Plugins in Music", xalign=0, hexpand=True)
        self.plugins_text.set_margin_start(10)
        pl_row.append(self.plugins_text)
        self.plugins_switch = Gtk.Switch(active=True, valign=Gtk.Align.CENTER)
        self.plugins_switch.set_tooltip_text(
            "All VST3 effects on or off at once.\n"
            "Music and radio keep their own choice: on for music, off for radio at first (for safety)."
        )
        self.plugins_switch.connect("notify::active", self.on_plugins_switch)
        pl_row.append(self.plugins_switch)
        box.append(pl_row)
        line3 = Gtk.Box()
        line3.add_css_class("prefs-line")
        box.append(line3)

        head = Gtk.Label(label="file directory", xalign=0)
        head.add_css_class("prefs-head")
        box.append(head)

        row = Gtk.Box(spacing=10)
        setup = Gtk.Button(label="Setup")
        setup.add_css_class("flat")
        setup.connect("clicked", self.choose_folder)
        row.append(setup)
        self.path_label = Gtk.Label(label=str(self.music_dir), xalign=0, hexpand=True, ellipsize=1)  # 1 = start
        self.path_label.add_css_class("pinkline")
        row.append(self.path_label)
        box.append(row)
        box.append(version_label())

        self.prefs_popover = Gtk.Popover()
        self.prefs_popover.set_child(fit_on_screen(box))
        self.prefs_popover.set_parent(self.menu_btn)
        self.menu_btn.connect("clicked", self.open_prefs)
        self.update_category_dots()

    def on_row_activated(self, _list, row):
        index = self.row_track.get(row)
        if index is None:
            return
        self.load_track(index)
        if not self.player.playing:
            self.on_play_pause()

    def matches_search(self, index):
        """The search looks only where the chosen tab looks: album -> album names,
        artist -> artists, genre -> genres, track and playlist -> everything."""
        query = self.search.get_text().strip().lower()
        if not query:
            return True
        info = self.infos[index]
        if self.category in ("album", "artist", "genre"):
            return query in (info[self.category] or "").lower()
        return query in f"{info['title']} {info['artist']} {info['album']} {info['genre']}".lower()

    def filter_row(self, row):
        index = self.row_track.get(row)
        return True if index is None else self.matches_search(index)

    def on_search_changed(self, *_):
        if getattr(self, "_switching_search", False) or self.web_mode:
            return  # the browser goes to an address only on Enter
        if self.radio_mode:
            self.search_stations_soon()
            return
        if self.category == "playlist":
            self.rebuild_playlists()
        else:
            self.track_list.invalidate_filter()

    def update_search_hint(self):
        self.search.set_placeholder_text({
            "album": "Search albums", "artist": "Search artists", "genre": "Search genres",
            "playlist": "Search in playlists",
        }.get(self.category, "Type to search music track"))

    # --- categories: album / artist / genre group the list, track shows it flat ---
    def group_of(self, index):
        if self.category not in ("album", "artist", "genre"):
            return ""
        return self.infos[index][self.category] or f"Unknown {self.category}"

    def is_fav(self, index):
        return bool(self.tracks) and self.tracks[index] in self.favorites

    def section(self, index):
        """0 = favorite (top), 1 = rated with stars (under "Rating"), 2 = all the others."""
        if self.is_fav(index):
            return 0
        return 1 if self.ratings.get(self.tracks[index], 0) > 0 else 2

    def sort_key(self, index):
        """Favorites first, then the rated tracks (5 stars first), then the rest by category."""
        sec = self.section(index)
        if sec == 0:
            return (0, 0, "", index)
        if sec == 1:
            return (1, -self.ratings.get(self.tracks[index], 0), "", index)
        return (2, 0, self.group_of(index).lower(), index)

    def sort_rows(self, row1, row2):
        a, b = self.row_track.get(row1, 0), self.row_track.get(row2, 0)
        ka, kb = self.sort_key(a), self.sort_key(b)
        return (ka > kb) - (ka < kb)

    def row_header(self, row, before):
        index = self.row_track.get(row)
        if index is None:
            row.set_header(None)
            return
        prev = self.row_track.get(before) if before is not None else None
        sec = self.section(index)
        prev_sec = self.section(prev) if prev is not None else None
        parts = []
        if prev is not None and prev_sec != sec:  # a new section starts: the pink line
            line = Gtk.Box()
            line.add_css_class("fav-line")
            parts.append(line)
        if sec == 1 and prev_sec != 1:
            label = Gtk.Label(label="Rating", xalign=0)
            label.add_css_class("group-head")
            parts.append(label)
        # Group names (album / artist / genre) only for the tracks of the last section.
        if self.category in ("album", "artist", "genre") and sec == 2:
            group = self.group_of(index)
            if prev is None or prev_sec != 2 or self.group_of(prev) != group:
                label = Gtk.Label(label=group, xalign=0, ellipsize=3)
                label.add_css_class("group-head")
                parts.append(label)
        if not parts:
            row.set_header(None)
            return
        if len(parts) == 1:
            row.set_header(parts[0])
            return
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL)
        for part in parts:
            box.append(part)
        row.set_header(box)

    def letter_of(self, index):
        """What the scroll bubble shows for a track: ★ for favorites, the stars of a rated
        track, otherwise the first letter (of the group name in album / artist / genre)."""
        sec = self.section(index)
        if sec == 0:
            return "\u2605"
        if sec == 1:
            return f"{self.ratings.get(self.tracks[index], 0)}\u2605"
        if self.category in ("album", "artist", "genre"):
            text = self.group_of(index)
        else:
            info = self.infos[index]
            text = f"{info['title']} - {info['artist']}" if info["artist"] else info["title"]
        for char in text:
            if char.isalnum():
                return "#" if char.isdigit() else char.upper()
        return "#"

    def on_list_scrolled(self, adj):
        """Show the big letter next to the scroll bar while the list moves."""
        row = self.track_list.get_row_at_y(int(adj.get_value()) + 4)
        index = self.row_track.get(row) if row is not None else None
        if index is None:
            return
        self.scroll_letter.set_label(self.letter_of(index))
        span = max(1.0, adj.get_upper() - adj.get_page_size())
        room = max(0, self.track_scroll.get_height() - 64)
        self.scroll_letter.set_margin_top(int(room * min(1.0, adj.get_value() / span)))
        if self.scroll_letter.get_opacity() < 0.99 and not getattr(self, "_letter_showing", False):
            self._letter_showing = True
            animate_opacity(self.scroll_letter, self.scroll_letter.get_opacity(), 1.0, 120)
        if getattr(self, "_letter_timer", 0):
            GLib.source_remove(self._letter_timer)

        def hide():
            self._letter_timer = 0
            self._letter_showing = False
            animate_opacity(self.scroll_letter, 1.0, 0.0, 380)
            return False

        self._letter_timer = GLib.timeout_add(700, hide)

    def resort_list(self):
        """Favorites changed: move rows above / below the pink line, next / previous follow."""
        if self.category != "playlist":
            self.order = sorted(self.live_tracks(), key=self.sort_key)
        self.track_list.invalidate_sort()
        self.track_list.invalidate_headers()

    def refresh_category(self):
        self.order = sorted(self.live_tracks(), key=self.sort_key)
        self.track_list.invalidate_sort()
        self.track_list.invalidate_headers()
        self.track_list.invalidate_filter()
        self.hint.set_text("No tracks found")
        if self.category == "playlist":
            self.rebuild_playlists()
            self.area_stack.set_visible_child_name("playlists")
            self.show_name_slider(False)
            flat = []
            for paths in self.playlists.values():
                flat += [i for i in (self.tracks.index(p) for p in paths if p in self.tracks) if i not in self.removed]
            self.order = flat  # next / previous follow the playlists (empty = the whole library)
        else:
            self.area_stack.set_visible_child_name("tracks")
            self.show_name_slider(True)
        self.update_category_dots()

    def show_name_slider(self, on):
        """Hidden but keeping its place, so the volume next to it stays where it is."""
        self.name_slider.set_opacity(1.0 if on else 0.0)
        self.name_slider.set_can_target(on)

    # --- playlists: {name: [file paths]}, saved in the settings ---
    def save_playlists(self):
        self.settings["playlists"] = self.playlists
        save_settings(self.settings)

    def create_playlist(self, name):
        name = name.strip()
        if name and name not in self.playlists:
            self.playlists[name] = []
            self.save_playlists()
        return name

    def add_to_playlist(self, name, index):
        path = self.tracks[index]
        if path not in self.playlists.setdefault(name, []):
            self.playlists[name].append(path)
            self.save_playlists()
        if self.category == "playlist":
            self.refresh_category()

    def open_add_menu(self, button, index):
        pop = Gtk.Popover()
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=4)
        head = Gtk.Label(label="Add to playlist", xalign=0)
        head.add_css_class("prefs-head")
        box.append(head)

        def choose(name):
            pop.popdown()
            self.add_to_playlist(name, index)

        for name in self.playlists:
            btn = Gtk.Button(label=name, halign=Gtk.Align.START)
            btn.add_css_class("flat")
            btn.connect("clicked", lambda _b, n=name: choose(n))
            box.append(btn)
        entry = Gtk.Entry(placeholder_text="New playlist...")

        def new(_entry):
            name = self.create_playlist(entry.get_text())
            if name:
                choose(name)

        entry.connect("activate", new)
        box.append(entry)
        pop.set_child(box)
        pop.set_parent(button)
        pop.connect("closed", lambda p: GLib.idle_add(p.unparent))
        pop.popup()

    # --- the button next to the search: jump to the track that is playing ---
    def show_current_track(self, *_):
        if self.radio_active:  # a station is on: show it in the station list
            if not self.radio_mode:
                self.set_radio_mode(True)
            item = self.station_rows.get(self.station["uuid"]) if self.station else None
            if item is not None:
                GLib.idle_add(self._scroll_to_row, item[0], self.station_list, self.radio_scroll)
            return
        if self.radio_mode:
            self.set_radio_mode(False)
        if not self.tracks:
            return
        if self.category == "playlist":  # the playing track is shown in the full list
            self.set_category("track")
        row = self.row_of.get(self.index)
        if row is None:
            return
        if not self.filter_row(row):
            self.search.set_text("")  # the search hides it: clear the search first
        GLib.idle_add(self._scroll_to_row, row)

    def _scroll_to_row(self, row, listbox=None, scroll=None):
        listbox = listbox or self.track_list
        scroll = scroll or self.track_scroll
        adj = scroll.get_vadjustment()
        ok, point = row.compute_point(listbox, Graphene.Point().init(0, 0))
        if ok:
            target = point.y - (adj.get_page_size() - row.get_height()) / 2  # in the middle
            target = max(adj.get_lower(), min(target, adj.get_upper() - adj.get_page_size()))
            try:
                anim = Adw.TimedAnimation.new(
                    scroll, adj.get_value(), target, 350,
                    Adw.CallbackAnimationTarget.new(adj.set_value),
                )
                anim.set_easing(Adw.Easing.EASE_OUT_CUBIC)
                self._scroll_anim = anim
                anim.play()
            except Exception:
                adj.set_value(target)
        listbox.select_row(row)
        return False

    # --- the ... button of a track: share, show in folder, info, delete ---
    def open_track_menu(self, button, index):
        pop = Gtk.Popover()
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
        info = self.infos[index]
        head = Gtk.Label(label=info["title"], xalign=0, ellipsize=3, max_width_chars=32)
        head.add_css_class("prefs-head")
        box.append(head)

        def item(text, handler, tip=None):
            btn = Gtk.Button(label=text, halign=Gtk.Align.START, tooltip_text=tip)
            btn.add_css_class("flat")

            def clicked(_b):
                pop.popdown()
                handler(index)

            btn.connect("clicked", clicked)
            box.append(btn)

        item("Share (copy file)", self.copy_track_file,
             "Copies the file: paste it into a messenger, an e-mail or a folder")
        item("Show in folder", self.show_track_in_folder)
        item("Export with effects...", self.export_track,
             "Save this track with the EQ, Crunch, reverb, plugins and tempo you hear")
        item("Track info", lambda i: self.show_track_info(button, i))
        item("Move to Trash", self.ask_trash_track, "The file can be restored from the Trash")
        pop.set_child(box)
        pop.set_parent(button)
        pop.connect("closed", lambda p: GLib.idle_add(p.unparent))
        pop.popup()

    def copy_track_file(self, index):
        path = self.tracks[index]
        uri = GLib.filename_to_uri(path, None)
        providers = [
            Gdk.ContentProvider.new_for_bytes("text/uri-list", GLib.Bytes.new(f"{uri}\r\n".encode())),
            Gdk.ContentProvider.new_for_bytes(
                "x-special/gnome-copied-files", GLib.Bytes.new(f"copy\n{uri}".encode())
            ),
            Gdk.ContentProvider.new_for_bytes("text/plain;charset=utf-8", GLib.Bytes.new(path.encode())),
        ]
        self.get_clipboard().set_content(Gdk.ContentProvider.new_union(providers))
        self.flash_title("File copied: paste it where you want to share")

    def show_track_in_folder(self, index):
        launcher = Gtk.FileLauncher.new(Gio.File.new_for_path(self.tracks[index]))
        launcher.open_containing_folder(self, None, None)

    def show_track_info(self, anchor, index):
        path = self.tracks[index]
        info = read_tags(path, with_cover=False)
        try:
            size = f"{os.path.getsize(path) / 1_048_576:.1f} MB"
        except OSError:
            size = "?"
        lines = (
            ("Title", info["title"]), ("Artist", info["artist"] or "-"), ("Album", info["album"] or "-"),
            ("Genre", info["genre"] or "-"), ("BPM", self.bpm_source_text(path, info)),
            ("Format", Path(path).suffix.lstrip(".").upper()), ("Size", size), ("File", path),
        )
        pop = Gtk.Popover()
        grid = Gtk.Grid(column_spacing=14, row_spacing=6)
        for side in ("top", "bottom", "start", "end"):
            getattr(grid, f"set_margin_{side}")(8)
        for row, (key, value) in enumerate(lines):
            k = Gtk.Label(label=key, xalign=0)
            k.set_opacity(0.6)
            v = Gtk.Label(label=value, xalign=0, selectable=True, wrap=True, max_width_chars=40)
            grid.attach(k, 0, row, 1, 1)
            grid.attach(v, 1, row, 1, 1)
        pop.set_child(grid)
        pop.set_parent(anchor)
        pop.connect("closed", lambda p: GLib.idle_add(p.unparent))
        pop.popup()

    def ask_trash_track(self, index):
        info = self.infos[index]
        name = f"{info['title']} - {info['artist']}" if info["artist"] else info["title"]
        dialog = Adw.MessageDialog(
            transient_for=self, heading="Move to Trash?",
            body=f"{name}\n\nThe file goes to the Trash, you can restore it from there.",
        )
        dialog.add_response("cancel", "Cancel")
        dialog.add_response("trash", "Move to Trash")
        dialog.set_response_appearance("trash", Adw.ResponseAppearance.DESTRUCTIVE)
        dialog.set_default_response("cancel")
        dialog.connect("response", lambda _d, answer: self.trash_track(index) if answer == "trash" else None)
        dialog.present()

    def trash_track(self, index):
        path = self.tracks[index]
        try:
            Gio.File.new_for_path(path).trash(None)
        except GLib.Error as err:
            self.flash_title(f"Could not move to Trash: {err.message}")
            return
        playing_it = index == self.index
        self.removed.add(index)
        row = self.row_of.pop(index, None)
        if row is not None:
            self.track_list.remove(row)
            self.row_track.pop(row, None)
        self.row_bars.pop(index, None)
        self.row_names.pop(index, None)
        self.row_stars.pop(index, None)
        # Forget everything that was saved for this file.
        self.ratings.pop(path, None)
        self.favorites.discard(path)
        self.tempos.pop(path, None)
        for paths in self.playlists.values():
            while path in paths:
                paths.remove(path)
        self.settings.update(
            ratings=self.ratings, favorites=sorted(self.favorites), tempos=self.tempos, playlists=self.playlists,
        )
        save_settings(self.settings)
        if self.category == "playlist":
            self.refresh_category()
        if playing_it:
            if len(self.removed) >= len(self.tracks):
                self.player.stop()
                self.player.playing = False
                self.play_btn.get_child().set_from_icon_name("media-playback-start-symbolic")
                self.title_label.set_text("No music found")
            else:
                self.step_track(1)

    # --- BPM analysis ---
    def analysed_bpm(self, path):
        """The analysed BPM of a file, or None (not analysed yet, or the file changed since)."""
        item = self.analysis.get(path)
        try:
            if item and abs(item.get("mtime", 0) - os.path.getmtime(path)) < 1 and item.get("bpm", 0) > 0:
                return float(item["bpm"])
        except OSError:
            pass
        return None

    def track_bpm(self, path, info):
        """Analysed BPM first (like Rekordbox), then the tag, then 120. If the file has a tag,
        the analysis keeps the tag's octave (so a 128 track never shows as 64)."""
        found = self.analysed_bpm(path)
        if found:
            return max(1, round(fold_bpm(found, info["bpm"] if info.get("has_bpm") else None)))
        return info["bpm"]

    def bpm_source_text(self, path, info):
        bpm = self.track_bpm(path, info)
        if self.analysed_bpm(path):
            return f"{bpm} (analysed)"
        if info.get("has_bpm"):
            return f"{bpm} (from the tag)"
        if HAVE_AUBIO:
            return f"{bpm} (not analysed yet)"
        return f"{bpm} (default, pip install aubio to analyse)"

    def analyse_first(self, path):
        try:
            self.analysis_queue.remove(path)
        except ValueError:
            pass
        if path != self._analysing:
            self.analysis_queue.appendleft(path)
        self.run_analysis()

    def run_analysis(self):
        """One file at a time, in the background."""
        if not HAVE_AUBIO or self._analysing or not self.analysis_queue:
            return
        path = self.analysis_queue.popleft()
        if self.analysed_bpm(path) is not None or not os.path.exists(path):
            GLib.idle_add(lambda: self.run_analysis() or False)
            return
        self._analysing = path

        def work():
            bpm = 0.0
            failed = False
            if not _ANALYSIS_PYTHON:
                _ANALYSIS_PYTHON.append(analysis_python())
            python = _ANALYSIS_PYTHON[0]
            if python is None:  # no Python with a working aubio: stop trying for this run
                print("BPM analysis is off: aubio does not work (sudo apt install python3-aubio)")
                GLib.idle_add(self.analysis_unavailable)
                return
            try:
                run = subprocess.run(
                    [python, "-I", "-c", with_site(ANALYZE_CODE), path, str(ANALYSIS_SECONDS)],
                    capture_output=True, text=True, timeout=180,
                )
                if run.returncode == 0:
                    bpm = float(json.loads(run.stdout.strip().splitlines()[-1])["bpm"])
                else:
                    failed = True
                    print("BPM analysis failed:", Path(path).name, (run.stderr.strip().splitlines() or [""])[-1])
            except (OSError, subprocess.TimeoutExpired, ValueError, IndexError, KeyError):
                failed = True
            GLib.idle_add(self.analysis_done, path, bpm, failed)

        threading.Thread(target=work, daemon=True).start()

    def analysis_unavailable(self):
        self._analysing = None
        self.analysis_queue.clear()
        return False

    def analysis_done(self, path, bpm, failed=False):
        self._analysing = None
        self._analysis_fails = getattr(self, "_analysis_fails", 0) + 1 if failed else 0
        if self._analysis_fails >= ANALYSIS_MAX_FAILS:
            print("BPM analysis stopped after repeated errors (see above). The player works without it.")
            self.analysis_queue.clear()
            return False
        bpm = fold_bpm(bpm)
        if bpm > 0:
            try:
                mtime = os.path.getmtime(path)
            except OSError:
                mtime = 0
            self.analysis[path] = {"bpm": round(bpm, 2), "mtime": mtime}
            self.save_analysis_soon()
            if self.tracks and self.tracks[self.index] == path:
                self.apply_new_base_bpm(path)
        GLib.timeout_add(ANALYSIS_PAUSE_MS, lambda: self.run_analysis() or False)
        return False

    def apply_new_base_bpm(self, path):
        """The playing track got its real BPM: keep the same speed, show the right numbers."""
        info = read_tags(path, with_cover=False)
        new_base = self.track_bpm(path, info)
        if new_base == self.base_bpm:
            return
        ratio = self.bpm / self.base_bpm
        self.base_bpm = new_base
        self.bpm = max(round(new_base * 0.5), min(round(new_base * 2), round(new_base * ratio)))
        saved = self.tempos.get(path)
        self.saved_bpm = self.bpm if not saved else self.saved_bpm
        self.player.set_tempo(self.bpm / self.base_bpm, smooth=True)
        self.show_bpm()
        self.update_save_button()

    def save_analysis_soon(self):
        if self._analysis_save:
            return

        def flush():
            self._analysis_save = 0
            self.settings["bpm_analysis"] = self.analysis
            save_settings(self.settings)
            return False

        self._analysis_save = GLib.timeout_add(3000, flush)

    # --- Master Tempo (switch in Preferences) ---
    def set_master_tempo(self, on):
        self.player.set_master_tempo(on)
        self.settings["master_tempo"] = bool(on)
        save_settings(self.settings)

    # --- Space: play / pause (not while typing in a text field) ---
    def add_space_key(self):
        add_play_keys(self, self.on_play_pause)

    def play_index(self, index):
        self.load_track(index)
        if not self.player.playing:
            self.on_play_pause()

    def rebuild_playlists(self):
        while (child := self.playlist_box.get_first_child()) is not None:
            self.playlist_box.remove(child)

        create = Gtk.Box(spacing=8)
        create.set_margin_top(8)
        create.set_margin_start(8)
        create.set_margin_end(8)
        entry = Gtk.Entry(placeholder_text="New playlist...", hexpand=True)
        make = Gtk.Button(label="Create")
        make.add_css_class("flat")

        def do_create(*_):
            if self.create_playlist(entry.get_text()):
                self.refresh_category()

        entry.connect("activate", do_create)
        make.connect("clicked", do_create)
        create.append(entry)
        create.append(make)
        self.playlist_box.append(create)

        if not self.playlists:
            note = Gtk.Label(label="No playlists yet. Create one, then add tracks with +")
            note.set_opacity(0.5)
            note.set_margin_top(24)
            self.playlist_box.append(note)

        searching = bool(self.search.get_text().strip())
        for name, paths in self.playlists.items():
            paths = [p for p in paths if p in self.tracks and self.tracks.index(p) not in self.removed]
            shown = [p for p in paths if self.matches_search(self.tracks.index(p))]
            if searching and not shown and self.search.get_text().strip().lower() not in name.lower():
                continue  # nothing found in this playlist
            head = Gtk.Box(spacing=8)
            title = Gtk.Label(label=name, xalign=0, hexpand=True, ellipsize=3)
            title.add_css_class("group-head")
            title.set_hexpand(True)
            head.append(title)
            drop = Gtk.Button(label="\u2715", tooltip_text="Delete playlist")
            drop.add_css_class("flat")
            drop.connect("clicked", lambda _b, n=name: self.delete_playlist(n))
            head.append(drop)
            self.playlist_box.append(head)
            for path in (shown if searching else paths):
                if path not in self.tracks:
                    continue  # the file is not in the current music folder
                index = self.tracks.index(path)
                info = self.infos[index]
                text = f"{info['title']} - {info['artist']}" if info["artist"] else info["title"]
                row = Gtk.Box(spacing=8)
                play = Gtk.Button(halign=Gtk.Align.FILL, hexpand=True)
                play.add_css_class("flat")
                label = Gtk.Label(label=text, xalign=0, ellipsize=3)
                label.add_css_class("track")
                play.set_child(label)
                play.connect("clicked", lambda _b, i=index: self.play_index(i))
                row.append(play)
                remove = Gtk.Button(label="\u2715", tooltip_text="Remove from playlist")
                remove.add_css_class("flat")
                remove.connect("clicked", lambda _b, n=name, p=path: self.remove_from_playlist(n, p))
                row.append(remove)
                self.playlist_box.append(row)

    def delete_playlist(self, name):
        self.playlists.pop(name, None)
        self.save_playlists()
        self.refresh_category()

    def remove_from_playlist(self, name, path):
        if path in self.playlists.get(name, []):
            self.playlists[name].remove(path)
            self.save_playlists()
            self.refresh_category()

    def update_category_dots(self):
        for key, dot in self.cat_dots.items():
            if key == self.category:
                dot.add_css_class("active")
            else:
                dot.remove_css_class("active")
        self.update_search_hint()
        if hasattr(self, "home_btn"):
            want = self.category != "track" and not self.radio_mode and not self.web_mode
            if want != self.home_btn.get_visible():
                self.home_btn.set_visible(want)
                if want:
                    animate_opacity(self.home_btn, 0.0, 1.0, 220)

    def set_category(self, key):
        if self.web_mode:
            self.set_web_mode(False)
        if self.radio_mode:
            self.set_radio_mode(False)  # a library category: back to the music list
        self.category = key
        self.settings["category"] = key
        save_settings(self.settings)
        self.refresh_category()
        self.prefs_popover.popdown()
        if not self.expanded:
            self.toggle_tracks()  # show the list so the change is visible

    # ================= online radio =================
    def set_radio_mode(self, on):
        """The radio button: the track list fades out and the station list fades in (and back).
        Whatever plays keeps playing until a station (or a track) is chosen."""
        on = bool(on)
        if on == self.radio_mode:
            return
        if getattr(self, "_mode_anim", None) is not None:
            # The window is still sliding (mini <-> full): a second switch in the middle of it
            # (radio again, quickly) is taken once it stops, not on top of the moving layout.
            GLib.timeout_add(320, lambda: self.set_radio_mode(on) or False)
            return
        if on and self.web_mode:
            self.set_web_mode(False)
        self.radio_mode = on
        self.radio_btn.set_tooltip_text("Back to the music" if on else "Online radio")
        self.refresh_more_btn()
        # Each view keeps its own search text.
        texts = self.__dict__.setdefault("_search_texts", {})
        texts["music" if on else "radio"] = self.search.get_text()
        self._switching_search = True
        self.search.set_text(texts.get("radio" if on else "music", ""))
        self._switching_search = False
        if on:
            sliding = not self.expanded  # the window opens from the mini player right now
            if sliding:
                self.area_stack.set_transition_type(Gtk.StackTransitionType.NONE)
            self.area_stack.set_visible_child_name("radio")
            if sliding:
                self.area_stack.set_transition_type(Gtk.StackTransitionType.CROSSFADE)
            self.show_name_slider(False)
            self.search.set_placeholder_text("Search radio stations or genres")
            self.load_stations(self.search.get_text())
        else:
            self.refresh_category()  # back to the tracks (or playlists)
        self.rescan_btn.set_visible(self.expanded and not on)
        self.home_btn.set_visible(self.expanded and not on and self.category != "track")
        if on and not self.expanded:
            self.toggle_tracks()  # the stations need the right side of the window

    # ================= the browser (its own window and process) =================
    def web_sound(self):
        """The browser's sound chain (made once, kept by the app)."""
        app = self.get_application()
        if getattr(app, "web_sound", None) is None:
            app.web_sound = WebSound(self)
        return app.web_sound

    def set_web_mode(self, on=True):
        """The globe button: open the browser window, or hide / show it."""
        if self.browser.running():
            self.browser.send(cmd="toggle" if not on or self.browser_visible else "show")
            return
        if not on:
            return
        sound = self.web_sound()
        rate_choice = str(self.settings.get("web_sample_rate") or "auto")
        if not self.web_route.ok:   # the virtual output is made at the chosen sample rate
            set_web_rate(web_rate_choice(rate_choice))
        self.web_route.setup()
        init = {"pinned": self.settings.get("web_pinned") or [], "engine": self.settings.get("web_engine"),
                "sites": self.settings.get("web_sites"),  # None = the original music sites
                "colors": {k: COLORS[k] for k in BROWSER_COLOR_KEYS}, "app_id": APP_ID,
                "frame": FRAME_ON[0],
                "volume": float(sound.volume_value), "route": bool(self.web_route.ok),
                "tabs_shown": bool(self.settings.get("web_tabs_shown", True)),
                "pinned_tabs": list(self.settings.get("web_pinned_tabs") or []),
                "one_player": bool(self.settings.get("web_one_player", True)),
                "links_new_tab": bool(self.settings.get("web_links_new_tab", False)),
                "site_theme": self.settings.get("web_site_theme") or "auto",
                "open_tabs": list(getattr(self, "_web_reopen", None) or []),
                "download_dir": self.settings.get("web_download_dir") or "",
                "download_ask": bool(self.settings.get("web_download_ask", True)),
                "sample_rate": rate_choice}
        self._web_reopen = None  # handed over once (after a restart for the site theme)
        self.browser.transparent = None   # always see-through now: no restart when the opacity changes
        self.prefs_popover.popdown()
        self.launch_electron(init)

    def launch_electron(self, init):
        """The Electron browser: downloaded once, its sandbox set up once, then started."""
        if not os.path.exists(ELECTRON_BIN):
            if ELECTRON_INSTALL["running"]:
                self.flash_title("Electron is still downloading...")
                return
            ELECTRON_INSTALL["running"] = True
            self.flash_title("Downloading Electron (~110 MB, once)...")

            def done(ok, message):
                ELECTRON_INSTALL["running"] = False
                print("[Player-17]", message, file=sys.stderr, flush=True)
                self.flash_title(message)
                if ok:
                    self.set_web_mode(True)

            install_electron(lambda p: self.flash_title(f"Downloading Electron... {p}%"), done)
            return
        no_sandbox = bool(os.environ.get("PLAYER_ELECTRON_NO_SANDBOX"))
        if not no_sandbox and not PACKAGED_ELECTRON and not electron_sandbox_ok():
            if getattr(self, "_electron_sandbox_asked", False):
                return
            self._electron_sandbox_asked = True
            self.flash_title("Electron needs your password once (browser sandbox)")

            def fixed(ok):
                self._electron_sandbox_asked = False
                if ok:
                    self.set_web_mode(True)
                else:
                    print("[Player-17] Electron's sandbox is not set up. Once, in the terminal:\n"
                          f"  sudo chown root:root \"{ELECTRON_SANDBOX}\" && sudo chmod 4755 \"{ELECTRON_SANDBOX}\"",
                          file=sys.stderr, flush=True)
                    self.flash_title("Electron's sandbox is not set up (the command is in the terminal)")

            fix_electron_sandbox(fixed)
            return
        wrapper = [os.environ["PLAYER_ELECTRON_WRAPPER"]] if PACKAGED_ELECTRON and os.environ.get("PLAYER_ELECTRON_WRAPPER") else []
        command = wrapper + [ELECTRON_BIN, f"--class={APP_ID}"] + (["--no-sandbox"] if no_sandbox else []) + [electron_app_dir()]
        if not self.browser.start(init, command=command):
            self.flash_title("The browser could not start (see the terminal)")

    def web_js(self, script):
        self.browser.send(cmd="js", script=script)

    # --- the music's sample rate (its Plugins window): "auto" = as the track ---
    SAMPLE_RATE_TIP = ("The sample rate the music is played at\n"
                       "Auto: as the sound output device")

    def music_out_rate(self):
        """The rate the music chain works at, in Hz: the chosen one, or the device's for Auto."""
        choice = self.sample_rate_choice()
        if choice == "auto":
            try:
                return int(device_rate(48000))
            except Exception:
                return 48000
        return int(choice)

    def has_sample_rate(self):
        return True

    def sample_rate_choice(self):
        choice = str(self.settings.get("music_sample_rate") or "auto")
        return choice if choice in {key for key, _name in HUB_RATES} else "auto"

    def choose_sample_rate(self, choice):
        choice = str(choice or "auto")
        if choice not in {key for key, _name in HUB_RATES}:
            choice = "auto"
        self.settings["music_sample_rate"] = choice
        save_settings(self.settings)
        rate = self.music_out_rate()
        self.player.set_out_rate(rate)
        self.flash_title("Sample rate: " + dict(HUB_RATES)[choice] + (f" (as the device, {rate} Hz)" if choice == "auto" else ""))

    # --- the browser's sample rate (the browser's menu and its Plugins window both set it) ---
    def get_sample_rate_choice(self):
        choice = str(self.settings.get("web_sample_rate") or "auto")
        return choice if choice in {key for key, _name in HUB_RATES} else "auto"

    def set_sample_rate_choice(self, choice, from_page=False):
        choice = str(choice or "auto")
        if choice not in {key for key, _name in HUB_RATES}:
            choice = "auto"
        self.settings["web_sample_rate"] = choice
        save_settings(self.settings)
        sound = self.web_sound()
        rebuild_web_rate(self.web_route, sound, choice)
        if from_page:
            sound.refresh_rate()
        elif self.browser.running():
            self.browser.send(cmd="rate", value=choice)   # the browser's menu shows it too

    def on_browser_event(self, event):
        kind = event.get("ev")
        sound = self.web_sound()
        if kind == "playing":
            sound.on_playing(bool(event.get("on")))
        elif kind == "title":
            sound.title = event.get("text") or ""
        elif kind == "restart":  # the site theme changed: the browser starts again, same tabs open
            self._web_reopen = [u for u in (event.get("tabs") or []) if isinstance(u, str)]
            self.browser.stop()
            self.browser_visible = False
            self.refresh_more_btn()
            GLib.timeout_add(300, lambda: self.set_web_mode(True) or False)
        elif kind == "goto":  # the arrow left of the browser's address: music, video, radio
            self.get_application().show_window(event.get("where") or "music")
        elif kind == "set" and event.get("key") in ("web_pinned", "web_engine", "web_tabs_shown",
                                                     "web_pinned_tabs", "web_one_player", "web_sites",
                                                     "web_download_dir", "web_download_ask",
                                                     "web_links_new_tab", "web_site_theme"):
            self.settings[event["key"]] = event.get("value")
            save_settings(self.settings)
        elif kind == "rate":  # the sample rate from the browser's menu
            self.set_sample_rate_choice(event.get("value"), from_page=True)
        elif kind == "visible":
            self.browser_visible = bool(event.get("on"))
            self.refresh_more_btn()
        elif kind == "plugins":
            sound.open_hub("p17")
        elif kind == "volume":
            try:
                sound.set_master_volume(max(0.0, min(1.0, float(event.get("value")))))
            except (TypeError, ValueError):
                pass
        elif kind == "exit":
            if event.get("proc") is not self.browser.proc:
                return  # an older browser process
            self.browser_visible = False
            self.refresh_more_btn()
            sound.stop()
            if event.get("code"):
                self.flash_title("The browser crashed: press the globe to open it again")
            GLib.idle_add(lambda: self.get_application().quit_if_nothing_open() or False)

    def search_stations_soon(self):
        """Ask the catalog once typing has paused, not on every letter."""
        if self._radio_search:
            GLib.source_remove(self._radio_search)

        def go():
            self._radio_search = 0
            self.load_stations(self.search.get_text())
            return False

        self._radio_search = GLib.timeout_add(450, go)

    def load_stations(self, query):
        query = (query or "").strip()
        if query == self._radio_query and self.stations:
            self.fill_stations(fade=False)
            return
        self._radio_query = query
        self.radio_status.set_label("Looking for stations...")
        self.fill_stations(fade=False)  # the favorites show at once

        def work():
            try:
                found, error = radio_search(query), None
            except Exception as exc:
                found, error = [], str(exc)
            GLib.idle_add(self.stations_ready, query, found, error)

        threading.Thread(target=work, daemon=True).start()

    def stations_ready(self, query, found, error):
        if query != self._radio_query:
            return False  # an older search answered late
        if error:
            print("Radio:", error)
            self.radio_status.set_label("No connection to the station catalog. Check the internet")
            self._radio_query = None  # ask again next time
        else:
            self.radio_status.set_label("" if found else "No stations found")
        self.stations = found
        self.fill_stations()
        return False

    def station_head(self, text):
        row = Gtk.ListBoxRow(activatable=False, selectable=False)
        label = Gtk.Label(label=text, xalign=0)
        label.add_css_class("group-head")
        row.set_child(label)
        return row

    def fill_stations(self, fade=True, force=False):
        query = (self._radio_query or "").lower()
        favorites = [s for s in self.radio_favorites
                     if not query or query in f"{s['name']} {s.get('tags', '')}".lower()]
        favorite_ids = {s["uuid"] for s in self.radio_favorites}
        others = [s for s in self.stations if s["uuid"] not in favorite_ids]
        shape = ([s["uuid"] for s in favorites], [s["uuid"] for s in others])
        if not force and shape == getattr(self, "_stations_shape", None) and self.station_list.get_first_child():
            # The same stations are already there (back to the radio, or the same search again):
            # nothing is torn down and rebuilt. Rebuilding the rows while the window was still
            # sliding open (from the mini player) could crash GTK.
            self.show_station_bars()
            return
        self._stations_shape = shape
        while (row := self.station_list.get_first_child()) is not None:
            self.station_list.remove(row)
        self.station_rows.clear()
        self.station_of_row.clear()
        self.station_order = favorites + others
        if favorites:
            self.station_list.append(self.station_head("Favorite stations"))
            for station in favorites:
                self.add_station_row(station, True)
        if others:
            self.station_list.append(self.station_head("Found" if query else "Popular stations"))
            for station in others:
                self.add_station_row(station, False)
        self.apply_scale(self.current_scale)
        if fade:
            animate_opacity(self.station_list, 0.0, 1.0, 260)

    def add_station_row(self, station, favorite):
        """One row: playing bars, name with a small line under it, the favorite star."""
        lbr = Gtk.ListBoxRow()
        row = Gtk.Box(spacing=10)
        row.set_margin_top(5)
        row.set_margin_bottom(5)
        row.set_margin_start(8)
        row.set_margin_end(6)
        bars = PlayingBars(lambda: self.player.playing and self.radio_active)
        bars.set_visible(bool(self.radio_active and self.station and self.station["uuid"] == station["uuid"]))
        row.append(bars)
        texts = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=1, hexpand=True, valign=Gtk.Align.CENTER)
        name = NameLabel(station["name"])
        name.add_css_class("track")
        name.set_tooltip_text(station["name"])
        texts.append(name)
        details = radio_details(station)
        if details:
            info = Gtk.Label(label=details, xalign=0, ellipsize=3)
            info.add_css_class("station-info")
            texts.append(info)
        row.append(texts)
        star = star_button(favorite)
        star.add_css_class("row-btn")
        star.get_child().remove_css_class("star")
        star.get_child().add_css_class("row-star")
        star.set_valign(Gtk.Align.CENTER)
        star.set_tooltip_text("Remove from favorites" if favorite else "Add to favorite stations")
        star.connect("clicked", lambda *_: self.toggle_station_favorite(station))
        row.append(star)
        lbr.set_child(row)
        self.station_of_row[lbr] = station
        self.station_rows[station["uuid"]] = (lbr, bars)
        self.station_list.append(lbr)

    def toggle_station_favorite(self, station):
        ids = [s["uuid"] for s in self.radio_favorites]
        if station["uuid"] in ids:
            self.radio_favorites.pop(ids.index(station["uuid"]))
        else:
            self.radio_favorites.append(dict(station))
        self.settings["radio_favorites"] = self.radio_favorites
        save_settings(self.settings)
        self.fill_stations(fade=False, force=True)

    def on_station_activated(self, _list, row):
        station = self.station_of_row.get(row)
        if station is not None:
            self.play_station(station)

    def show_station_bars(self):
        on = self.station["uuid"] if (self.radio_active and self.station) else None
        for uuid, (_row, bars) in self.station_rows.items():
            bars.set_visible(uuid == on)

    def update_radio_controls(self):
        """What makes no sense for a live stream is hidden while a station is on:
        BPM, repeat and shuffle, the favorite star, the progress line."""
        radio = self.radio_active
        for widget in (self.bpm_box, self.loop_box, self.fav_btn, self.save_tempo_btn,
                       self.progress, self.time_total):
            widget.set_visible(not radio)
        self.progress_row.set_halign(Gtk.Align.CENTER if radio else Gtk.Align.FILL)
        self.art.set_from_icon_name(radio_icon_name() if radio else "audio-x-generic-symbolic")
        if radio:
            self.time_now.set_text("0:00")
        self.rec_box.set_visible(radio)
        for widget in (self.bpm_box, self.rec_box, self.loop_box, self.fav_btn, self.progress_row):
            animate_opacity(widget, 0.0, 1.0, 260)

    def play_station(self, station):
        if not station.get("url"):
            return
        if self.recorder is not None:
            if self.settings.get("radio_rec_mode", "station") == "all":
                if station["name"] not in self.rec_names:  # the recording goes on with this station
                    self.rec_names.append(station["name"])
            else:
                self.stop_recording()  # another station: the recording of this one is finished
        old = self.row_bars.get(self.index)
        if old is not None:
            old.set_visible(False)  # the track row no longer shows "playing"
        self.station = station
        self.radio_active = True
        self.radio_now = ""
        self._radio_retries = 0
        self.update_radio_controls()
        self.apply_plugin_state(reload=False)
        self.player.set_tempo(1.0)
        self.title_label.set_text(station["name"])
        self.set_cover(None)
        self.mpris.set_cover(None)
        self.fetch_station_icon(station)
        self.player.playing = False
        self.player.load_uri(station["url"])
        self.player.play()  # also pauses the video window
        self._radio_started = time.monotonic()
        self.play_btn.get_child().set_from_icon_name("media-playback-pause-symbolic")
        self.show_station_bars()
        if "/" not in station["uuid"]:
            radio_count_click(station["uuid"])
        GLib.timeout_add(400, lambda: self.mpris.changed() or False)

    # --- copy the name (right click on the title) ---
    def copy_now_playing(self):
        if self.radio_active:
            text = self.radio_now or (self.station or {}).get("name", "")
        elif self.tracks:
            info = self.infos[self.index]
            text = f"{info['title']} - {info['artist']}" if info["artist"] else info["title"]
        else:
            return
        if not text:
            return
        self.get_clipboard().set_content(Gdk.ContentProvider.new_for_value(text))
        self.flash_title(f"Copied: {text}")

    # --- radio recording: what you hear (after EQ and plugins), saved where you choose ---
    def toggle_recording(self, *_):
        if self.recorder is None:
            self.start_recording()
        else:
            self.stop_recording()

    def start_recording(self):
        if not (self.radio_active and self.station):
            return
        if not RadioRecorder.available():
            self.flash_title("Recording needs gstreamer1.0-plugins-good (flacenc)")
            return
        if not self.player.playing and self.radio_active:
            self.toggle_radio()  # start the station: recording silence makes no sense
        temp = Path(GLib.get_user_cache_dir()) / "player-17" / "radio-recording.flac"
        try:
            temp.unlink(missing_ok=True)
        except OSError:
            pass
        self.recorder = RadioRecorder(str(temp))
        self.rec_station = dict(self.station)
        self.rec_names = [self.station["name"]]   # every station in this recording
        self._rec_started_at = time.localtime()
        self.player.start_tap(self.recorder.push)
        self.update_rec_ui()

    def stop_recording(self, ask=True):
        """ask=False: the window closes, the recording goes straight to the default folder."""
        rec, self.recorder = self.recorder, None
        if rec is None:
            return
        self.player.stop_tap()
        self.update_rec_ui()
        station = self.rec_station or {"name": "Radio"}
        if len(getattr(self, "rec_names", [])) > 1:  # recorded across several stations
            station = {"name": "Player-17 Radio"}
        stamp = time.strftime("%Y-%m-%d %H-%M", getattr(self, "_rec_started_at", time.localtime()))
        name = safe_file_name(f"{station['name']} {stamp}")
        if not ask:
            ok = rec.finish()
            self.save_recording(rec, ok, name, station, None)
            return
        self.flash_title("Finishing the recording...")
        rec.finish(lambda ok: self.save_recording(rec, ok, name, station, True))

    def recordings_folder(self):
        folder = self.settings.get("radio_rec_dir")
        if folder and os.path.isdir(folder):
            return folder
        folder = Path.home() / "Music" / "Player-17 Radio"
        folder.mkdir(parents=True, exist_ok=True)
        return str(folder)

    def save_recording(self, rec, ok, name, station, ask):
        if not ok or rec.seconds < 1 or not os.path.exists(rec.path):
            self.flash_title("Nothing was recorded")
            return
        if not ask:  # closing: no questions, the default folder
            target = os.path.join(self.recordings_folder(), name + ".flac")
            try:
                shutil.move(rec.path, target)
                tag_file(target, name, station["name"])
                print("Radio recording saved:", target)
            except OSError as err:
                print("Radio recording not saved:", err)
            return

        def chosen(target, key):
            self.settings["radio_rec_dir"] = str(Path(target).parent)
            save_settings(self.settings)
            self.flash_title("Saving the recording...")

            def work():
                if key == "flac":  # recorded as FLAC already: only moved
                    try:
                        shutil.move(rec.path, target)
                        done_ok = True
                    except OSError as err:
                        print("Radio recording:", err)
                        done_ok = False
                else:
                    done_ok = convert_audio(rec.path, target, audio_encoder(key))
                    try:
                        os.remove(rec.path)
                    except OSError:
                        pass
                if done_ok:
                    tag_file(target, name, station["name"])
                GLib.idle_add(lambda: self.flash_title(
                    f"Saved: {Path(target).name}" if done_ok else "The recording was not saved (see the terminal)") or False)

            threading.Thread(target=work, daemon=True).start()

        ask_save_as(self, "Save the radio recording", name, self.recordings_folder(), "audio",
                    "radio_rec_format", chosen)

    def update_rec_ui(self):
        on = self.recorder is not None
        (self.rec_btn.add_css_class if on else self.rec_btn.remove_css_class)("rec-on")
        self.rec_btn.set_tooltip_text("Stop and save the recording" if on else "Record the station (what you hear)")
        self.rec_label.set_text("REC 0:00" if on else "REC")
        all_mode = self.settings.get("radio_rec_mode", "station") == "all"
        self.rec_mode_btn.set_tooltip_text(
            "How to record: all stations in a row" if all_mode else "How to record: this station only")

    def open_rec_menu(self, *_):
        """The arrow next to REC: record only this station, or keep going across stations."""
        pop = Gtk.Popover()
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
        head = Gtk.Label(label="Record", xalign=0)
        head.add_css_class("prefs-head")
        box.append(head)
        mode = self.settings.get("radio_rec_mode", "station")

        def choose(key):
            pop.popdown()
            self.settings["radio_rec_mode"] = key
            save_settings(self.settings)
            self.update_rec_ui()

        for key, text, tip in (
            ("station", "This station only", "Switching to another station stops and saves the recording"),
            ("all", "All stations in a row", "The recording goes on when you switch stations"),
        ):
            mark = "\u25cf  " if key == mode else "     "
            btn = Gtk.Button(label=mark + text, halign=Gtk.Align.START, tooltip_text=tip)
            btn.add_css_class("flat")
            btn.connect("clicked", lambda _b, k=key: choose(k))
            box.append(btn)
        pop.set_child(box)
        pop.set_parent(self.rec_mode_btn)
        pop.connect("closed", lambda p: GLib.idle_add(p.unparent))
        pop.popup()

    def leave_radio(self):
        """A track was chosen while a station was on: the player is a music player again."""
        if self.recorder is not None:
            self.stop_recording()
        self.radio_active = False
        self.radio_now = ""
        self.update_radio_controls()
        self.show_station_bars()
        self.apply_plugin_state(reload=False)

    def toggle_radio(self):
        """Pause stops the stream (a paused stream only falls behind); play connects again."""
        if self.player.playing:
            self.player.pause()
            self.player.pipe.set_state(Gst.State.NULL)
        elif self.station is not None:
            self._radio_retries = 0
            self.player.load_uri(self.station["url"])
            self.player.play()
            self._radio_started = time.monotonic()
        self.play_btn.get_child().set_from_icon_name(
            "media-playback-pause-symbolic" if self.player.playing else "media-playback-start-symbolic"
        )
        self.mpris.changed()

    def step_station(self, delta):
        """Next / previous: through the stations as they are listed."""
        order = self.station_order or self.radio_favorites
        if not order:
            return
        ids = [s["uuid"] for s in order]
        if self.station is not None and self.station["uuid"] in ids:
            pos = ids.index(self.station["uuid"])
        else:
            pos = -1 if delta > 0 else 0
        self.play_station(order[(pos + delta) % len(order)])

    def reconnect_radio(self, reason):
        """The stream broke off: connect again a few times, then give up and say so."""
        if not self.radio_active or not self.player.playing or self.station is None:
            return
        if self._radio_retries >= RADIO_RETRIES:
            self.player.pause()
            self.player.pipe.set_state(Gst.State.NULL)
            self.play_btn.get_child().set_from_icon_name("media-playback-start-symbolic")
            self.flash_title(f"{reason}: the station is not available now")
            self.mpris.changed()
            return
        self._radio_retries += 1
        station = self.station

        def again():
            if self.radio_active and self.station is station and self.player.playing:
                self.player.load_uri(station["url"])
            return False

        GLib.timeout_add(1500 * self._radio_retries, again)

    def on_player_error(self, message):
        if self.radio_active:
            self.reconnect_radio("Connection error")
        elif message:
            self.flash_title(str(message))

    def on_radio_tag(self, title):
        """The station says which song is on: shown in place of the title."""
        if not self.radio_active or self.station is None or title == self.radio_now:
            return
        self.radio_now = title
        self._radio_retries = 0  # the stream works
        name = self.station["name"]
        self.title_label.set_text(title if title == name else f"{title}  \u00b7  {name}")
        self.mpris.changed()

    def fetch_station_icon(self, station):
        """The station's own logo as the cover (only when it is big enough not to look blurry)."""
        url = station.get("favicon") or ""
        if not url.startswith(("http://", "https://")):
            return

        def work():
            try:
                data = fetch_bytes(url)
            except Exception:
                data = None
            GLib.idle_add(done, data)

        def done(data):
            if not data or not self.radio_active or self.station is not station:
                return False
            try:
                texture = Gdk.Texture.new_from_bytes(GLib.Bytes.new(data))
            except GLib.Error:
                return False
            if min(texture.get_width(), texture.get_height()) >= 96:
                self.set_cover(data)
                self.mpris.set_cover(data)
                self.mpris.changed()
            return False

        threading.Thread(target=work, daemon=True).start()

    # --- plugins on / off: music and radio each keep their own choice ---
    def plugins_wanted(self):
        if self.radio_active:
            return bool(self.settings.get("plugins_radio", False))  # off at first, for safety
        return bool(self.settings.get("plugins_music", True))

    def apply_plugin_state(self, reload=True):
        on = self.plugins_wanted() and bool(self.p17().get("all_on", True))
        VST.set_bypass(not on)
        self.player.set_plugins_on(on, reload=reload)

    # The VST tab switch of the music window is the same as "Plugins in Music / Radio"
    # in Preferences: music and radio keep their own choice.
    def vst_tab_on(self):
        return self.plugins_wanted()

    def set_vst_tab_on(self, on):
        self.settings["plugins_radio" if self.radio_active else "plugins_music"] = bool(on)
        save_settings(self.settings)
        self.apply_plugin_state()

    def open_prefs(self, *_):
        if self.prefs_popover.get_visible():  # the menu button also closes the menu
            self.prefs_popover.popdown()
            return
        self._syncing_switch = True
        self.plugins_text.set_label("Plugins in Radio" if self.radio_active else "Plugins in Music")
        self.plugins_switch.set_active(self.plugins_wanted())
        self._syncing_switch = False
        self.prefs_popover.popup()
        GLib.timeout_add(200, self._check_prefs_opened)

    def _check_prefs_opened(self):
        """On Ubuntu (Wayland) the menu sometimes silently refuses to open. If so, it is
        built again on the spot (same content) and opened once more."""
        pop = self.prefs_popover
        if pop.get_mapped():
            return False
        debug_log(f"menu did not open: window {self.get_width()}x{self.get_height()}, "
                  f"maximized={self.is_maximized()}, full={self.expanded}, radio={self.radio_mode}; rebuilding it")
        child = pop.get_child()
        pop.set_child(None)
        pop.unparent()
        fresh = Gtk.Popover()
        fresh.set_child(child)
        fresh.set_parent(self.menu_btn)
        self.prefs_popover = fresh
        fresh.popup()
        GLib.timeout_add(200, lambda: debug_log(f"menu after rebuild: opened={fresh.get_mapped()}") or False)
        return False

    def on_plugins_switch(self, switch, _param):
        if getattr(self, "_syncing_switch", False):
            return
        self.settings["plugins_radio" if self.radio_active else "plugins_music"] = switch.get_active()
        save_settings(self.settings)
        self.apply_plugin_state()

    # --- equalizer: values are applied to the player at once and saved a moment later ---
    # --- export the track with everything applied (EQ, Crunch, reverb, VST3, LV2, limiter, tempo) ---
    def export_track(self, index=None):
        if not self.tracks:
            return
        index = self.index if index is None else index
        source = self.tracks[index]
        folder = self.settings.get("export_dir") or str(Path(source).parent)

        def chosen(target, key):
            self.settings["export_dir"] = str(Path(target).parent)
            save_settings(self.settings)
            self.start_export(source, target, audio_encoder(key))

        ask_save_as(self, "Export the track with the effects", f"{Path(source).stem} (Player-17)",
                    folder, "audio", "export_format", chosen)

    def start_export(self, source, target, encoder):
        def finished(ok, cancelled):
            self.close_export_dialog()
            if ok:
                copy_tags(source, target)
                self.flash_title(f"Saved: {Path(target).name}")
            elif not cancelled:
                self.flash_title("The export did not work (see the terminal)")

        self.start_render(source, target, encoder, finished, Path(target).name)

    def export_plugins_on(self):
        return bool(self.settings.get("plugins_music", True))

    def open_vst(self, *_):
        self.open_hub("vst")

    def store_vst_chain(self):
        """Remember the effects, but never overwrite them while they are still loading
        or when VST3 is not available (then the old list must stay as it was)."""
        if getattr(self, "_vst_loading", False):
            self._vst_dirty = True  # saved when the restore is finished
            return
        if not (VST.available and HAVE_VST_ELEMENT):
            return
        self.settings["vst3_chain"] = VST.saved()
        save_settings(self.settings)

    def save_vst(self):
        if getattr(self, "_vst_save_pending", False):
            return
        self._vst_save_pending = True

        def flush():
            self._vst_save_pending = False
            self.store_vst_chain()
            return False

        GLib.timeout_add(500, flush)

    def save_lv2(self):
        """Saved half a second after the last change (moving a fader changes it many times)."""
        if getattr(self, "_lv2_save_pending", False):
            return
        self._lv2_save_pending = True

        def flush():
            self._lv2_save_pending = False
            self.store_lv2_chain()
            return False

        GLib.timeout_add(500, flush)

    def store_lv2_chain(self):
        if not LV2_EFFECTS:
            return  # the saved LV2 chains stay as they were
        self.settings["lv2_chain"] = [
            {"factory": s["factory"], "name": s["name"], "enabled": s.get("enabled", True), "params": s.get("params", {})}
            for s in self.player.lv2_slots
        ]
        save_settings(self.settings)

    def restore_vst(self):
        """Load the effects saved last time, in the background."""
        restore_chain(self, VST, "vst3_chain")

    def open_colors(self, *_):
        self.prefs_popover.popdown()
        if getattr(self, "colors_window", None) is None:
            self.colors_window = ColorsWindow(self)
        self.colors_window.present()

    # --- rating and favorite: outline star = off, filled star = on ---
    def update_stars(self, index):
        rating = self.ratings.get(self.tracks[index], 0)
        for n, btn in enumerate(self.row_stars.get(index, [])):
            set_star(btn, n < rating)

    def on_star(self, index, value):
        path = self.tracks[index]
        if self.ratings.get(path, 0) == value:
            value = 0  # clicking the same star again clears the rating
        if value:
            self.ratings[path] = value
        else:
            self.ratings.pop(path, None)
        self.settings["ratings"] = self.ratings
        save_settings(self.settings)
        self.update_stars(index)
        self.resort_list()  # the track moves under "Rating" (or back out of it)

    def toggle_favorite(self, *_):
        if not self.tracks:
            return
        path = self.tracks[self.index]
        self.favorites.symmetric_difference_update({path})
        self.settings["favorites"] = sorted(self.favorites)
        save_settings(self.settings)
        self.update_fav_icon()
        self.resort_list()

    def update_fav_icon(self):
        on = bool(self.tracks) and self.tracks[self.index] in self.favorites
        set_star(self.fav_btn, on)

    # --- music: controls, tracks, progress, tempo ---
    def connect_player_controls(self):
        self.play_btn.connect("clicked", self.on_play_pause)
        self.next_btn.connect("clicked", lambda *_: self.next_track())
        self.prev_btn.connect("clicked", lambda *_: self.prev_track())
        self.bpm_minus.connect("clicked", lambda *_: self.set_bpm(self.bpm - 1))
        self.bpm_plus.connect("clicked", lambda *_: self.set_bpm(self.bpm + 1))
        self.progress.connect("change-value", self.on_seek)
        self.fav_btn.connect("clicked", self.toggle_favorite)
        self.save_tempo_btn.connect("clicked", self.save_tempo)
        self.repeat_btn.connect("clicked", self.open_repeat_menu)

        self.shuffle_btn.connect("clicked", self.toggle_shuffle)
        self.update_loop_icons()

        # Dragging left/right over the BPM number changes the tempo faster.
        drag = Gtk.GestureDrag()
        drag.connect("drag-begin", lambda *_: setattr(self, "_bpm_drag_start", self.bpm))
        # A hand shake of a few pixels (like during a double click) must not change the tempo.
        drag.connect(
            "drag-update",
            lambda _g, dx, _dy: self.set_bpm(self._bpm_drag_start + round(dx / 6)) if abs(dx) >= 8 else None,
        )
        self.bpm_label.add_controller(drag)

        # Double click on the BPM number: back to the track's original tempo.
        click = Gtk.GestureClick()
        click.connect(
            "pressed",
            lambda _g, n, _x, _y: self.reset_bpm() if n == 2 else None,
        )
        self.bpm_label.add_controller(click)
        self.bpm_label.set_tooltip_text("Double click: original tempo")

    def load_track(self, index):
        if not self.tracks:
            return
        if self.radio_active:
            self.leave_radio()  # a track was chosen: back to music
        old = self.row_bars.get(self.index)
        if old is not None:
            old.set_visible(False)
        self.index = index % len(self.tracks)
        path = self.tracks[self.index]
        info = read_tags(path)
        bars = self.row_bars.get(self.index)
        if bars is not None:
            bars.set_visible(True)

        label = info["title"] if not info["artist"] else f"{info['title']} - {info['artist']}"
        self.title_label.set_text(label)
        self.set_cover(info["cover"])
        self.update_fav_icon()

        # Tempo goes back to the original on every track change, unless a tempo was saved for it.
        self.base_bpm = self.track_bpm(path, info)
        if self.analysed_bpm(path) is None and HAVE_AUBIO:
            self.analyse_first(path)  # this one before all others
        self.bpm = self.base_bpm
        saved = self.tempos.get(path)
        if saved:
            self.bpm = max(round(self.base_bpm * 0.5), min(round(self.base_bpm * 2), int(saved)))
        self.saved_bpm = self.bpm
        self.player.set_tempo(self.bpm / self.base_bpm)
        self.show_bpm()
        self.update_save_button()

        self.progress.set_value(0)
        self.player.load(path)
        if getattr(self, "mpris", None) is not None:
            self.mpris.set_cover(info["cover"])
            GLib.timeout_add(400, lambda: self.mpris.changed() or False)  # the length is known a moment later

    def set_cover(self, data):
        self.cover_picture.set_visible(False)
        self.art.set_visible(True)
        if not data:
            return
        try:
            texture = Gdk.Texture.new_from_bytes(GLib.Bytes.new(data))
        except GLib.Error:
            return
        self.cover_picture.set_paintable(texture)
        self.cover_picture.set_visible(True)
        self.art.set_visible(False)

    def on_play_pause(self, *_):
        if self.radio_active:
            self.toggle_radio()
            return
        if not self.tracks:
            return
        if self.player.playing:
            self.player.pause()
        else:
            self.player.play()
        self.play_btn.get_child().set_from_icon_name(
            "media-playback-pause-symbolic" if self.player.playing else "media-playback-start-symbolic"
        )
        self.mpris.changed()

    def play_order(self):
        """Tracks in the order they are shown, without the ones moved to the Trash."""
        order = self.order if self.order else list(range(len(self.tracks)))
        return [i for i in order if i not in self.removed] or [self.index]

    def step_track(self, delta):
        order = self.play_order()
        pos = order.index(self.index) if self.index in order else 0
        self.load_track(order[(pos + delta) % len(order)])

    def next_track(self):
        if self.radio_active:
            self.step_station(1)
            return
        if not self.tracks:
            return
        self.play_history.append(self.index)
        del self.play_history[:-100]
        if self.shuffle and len(self.tracks) > 1:
            choices = [i for i in range(len(self.tracks)) if i != self.index and i not in self.removed] or [self.index]
            self.load_track(random.choice(choices))
        else:
            self.step_track(1)

    def on_track_end(self):
        """A track finished by itself: repeat it, go on, or stop after the last one."""
        if self.radio_active:
            self.reconnect_radio("The station stopped")
            return
        if not self.tracks:
            return
        if self.repeat_mode == "one":
            self.load_track(self.index)
        elif self.shuffle:
            self.next_track()
        else:
            order = self.play_order()
            last = order[-1] if order else 0
            if self.repeat_mode == "off" and self.index == last:
                self.player.pause()
                self.play_btn.get_child().set_from_icon_name("media-playback-start-symbolic")
                self.load_track(order[0])  # ready at the start, paused
            else:
                self.next_track()

    def update_loop_icons(self, animate=False):
        icon = self.repeat_btn.get_child()
        icon.set_from_icon_name(
            "media-playlist-repeat-song-symbolic" if self.repeat_mode == "one" else "media-playlist-repeat-symbolic"
        )
        icon.set_opacity(0.35 if self.repeat_mode == "off" else 1.0)
        self.repeat_btn.set_tooltip_text(
            {"off": "Repeat: off", "all": "Repeat: all tracks", "one": "Repeat: this track"}[self.repeat_mode]
        )
        shuffle_icon = self.shuffle_btn.get_child()
        shuffle_icon.set_opacity(1.0 if self.shuffle else 0.35)
        self.shuffle_btn.set_tooltip_text("Shuffle: on" if self.shuffle else "Shuffle: off")
        if animate:
            animate_opacity(icon, 0.0, icon.get_opacity(), 260)

    def open_repeat_menu(self, *_):
        pop = Gtk.Popover()
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
        head = Gtk.Label(label="Repeat", xalign=0)
        head.add_css_class("prefs-head")
        box.append(head)

        def choose(mode):
            pop.popdown()
            self.repeat_mode = mode
            self.settings["repeat"] = mode
            save_settings(self.settings)
            self.update_loop_icons(animate=True)
            self.player.refresh_loop()   # "This track": a seamless loop from right here

        for mode, text in (("off", "No repeat"), ("all", "All tracks"), ("one", "This track")):
            mark = "\u25cf  " if mode == self.repeat_mode else "     "
            btn = Gtk.Button(label=mark + text, halign=Gtk.Align.START)
            btn.add_css_class("flat")
            btn.connect("clicked", lambda _b, m=mode: choose(m))
            box.append(btn)
        pop.set_child(box)
        pop.set_parent(self.repeat_btn)
        pop.connect("closed", lambda p: GLib.idle_add(p.unparent))
        pop.popup()

    def toggle_shuffle(self, *_):
        self.shuffle = not self.shuffle
        self.settings["shuffle"] = self.shuffle
        save_settings(self.settings)
        self.update_loop_icons()
        animate_opacity(self.shuffle_btn.get_child(), 0.0, 1.0 if self.shuffle else 0.35, 300)

    def prev_track(self):
        if self.radio_active:
            self.step_station(-1)
            return
        if not self.tracks:
            return
        _fraction, seconds = self.player.position_fraction()
        if seconds > SEEK_BACK_SECONDS:
            self.player.seek_fraction(0)
        elif self.shuffle and [i for i in self.play_history if i not in self.removed]:
            self.play_history = [i for i in self.play_history if i not in self.removed]
            self.load_track(self.play_history.pop())  # back to what was played before
        else:
            self.step_track(-1)

    def on_seek(self, _scale, _scroll, value):
        self.player.seek_fraction(value / 100)
        return False  # let the slider move

    def update_progress(self):
        if self._closed:
            return False  # the window is gone: stop the timer
        if self.radio_active:  # live: how long this station has been on
            if self.player.playing:
                self.time_now.set_text(format_time(time.monotonic() - self._radio_started))
            if self.recorder is not None:
                self.rec_label.set_text(f"REC {format_time(self.recorder.seconds)}")
            return True
        pos, dur = self.player.times()
        if self.player.playing and dur > 0:
            self.progress.set_value(pos / dur * 100)
        self.time_now.set_text(format_time(pos))
        self.time_total.set_text(format_time(dur))
        return True  # keep the timer running

    def set_bpm(self, value):
        low, high = round(self.base_bpm * 0.5), round(self.base_bpm * 2)
        self.bpm = max(low, min(high, int(value)))
        self.player.set_tempo(self.bpm / self.base_bpm, smooth=True)
        self.show_bpm()
        self.update_save_button()

    def reset_bpm(self):
        self._bpm_drag_start = self.base_bpm  # the drag that goes with the click must not undo the reset
        self.set_bpm(self.base_bpm)

    def update_save_button(self):
        """The save button shows only while the tempo differs from what is saved for the track."""
        want = bool(self.tracks) and self.bpm != self.saved_bpm
        if want == getattr(self, "_save_shown", False):
            return
        self._save_shown = want
        self.save_tempo_btn.set_sensitive(want)
        self.save_tempo_btn.set_can_target(want)
        animate_opacity(self.save_tempo_btn, self.save_tempo_btn.get_opacity(), 1.0 if want else 0.0, 220)

    def save_tempo(self, *_):
        if not self.tracks:
            return
        path = self.tracks[self.index]
        if self.bpm == self.base_bpm:
            self.tempos.pop(path, None)  # back to the original: nothing to remember
        else:
            self.tempos[path] = self.bpm
        self.settings["tempos"] = self.tempos
        save_settings(self.settings)  # the audio file itself is never touched
        self.saved_bpm = self.bpm
        self.update_save_button()

    def show_bpm(self):
        self.bpm_label.set_text(f"Bpm  {self.bpm}")

    # --- drag and drop: music plays here, videos go to the video window ---
    def on_media_dropped(self, audio, video):
        if audio:
            self.play_files(audio)
        if video:
            app = self.get_application()
            app.open_video()
            app.video_window.play_files(video)

    def play_files(self, paths):
        """Play files from anywhere: ones not in the library are added to the list for now."""
        first = None
        for path in paths:
            if path in self.tracks:
                index = self.tracks.index(path)
                self.removed.discard(index)
                if index not in self.row_of:  # its row was taken out (file was gone): back
                    self.add_track(index, self.infos[index])
            else:
                index = len(self.tracks)
                info = read_tags(path, with_cover=False)
                self.tracks.append(path)
                self.infos.append(info)
                self.add_track(index, info)
                if HAVE_AUBIO and self.analysed_bpm(path) is None:
                    self.analysis_queue.append(path)
            if first is None:
                first = index
        if first is None:
            return
        self.resort_list()
        self.apply_scale(self.current_scale)
        self.present()
        self.load_track(first)
        if not self.player.playing:
            self.on_play_pause()
        self.run_analysis()

    def external_pause(self):
        """The video player (or the browser) started: the music pauses."""
        if self.player.playing:
            self.on_play_pause()

    def on_close(self, *_):
        app = self.get_application()
        if self.recorder is not None:
            self.stop_recording(ask=False)  # saved to Music/Player-17 Radio (or the last folder)
        self.settings["eq"] = self.eq_settings
        save_settings(self.settings)
        self.store_vst_chain()
        self.store_lv2_chain()
        if app is not None and app.other_is_open(self):
            # The video window stays: this one is only hidden (nothing is torn down,
            # so closing it can never take the video with it). The note button shows it again.
            if self.player.playing:
                self.on_play_pause()
            for name in ("plugins_hub", "colors_window"):
                window = getattr(self, name, None)
                if window is not None:
                    window.set_visible(False)
            self.close_popovers()
            # its size, so it comes back exactly as it was (see open_music)
            self._hidden_state = (self.get_width(), self.get_height(), self.is_maximized())
            self.set_visible(False)
            return True
        self._closed = True
        self.analysis_queue.clear()
        self.browser.stop()
        if app is not None and getattr(app, "web_sound", None) is not None:
            app.web_sound.stop()
        self.web_route.close()
        self.mpris.release()
        save_settings(self.settings)
        if getattr(self, "plugins_hub", None) is not None:
            self.plugins_hub.destroy()
        if getattr(self, "colors_window", None) is not None:
            self.colors_window.destroy()
        self.player.stop()
        self.prefs_popover.unparent()
        if app is not None:
            GLib.idle_add(lambda: app.quit() or False)  # the last window: the app ends
        return False

    # --- colored window buttons on the left (close, minimize, maximize) ---
    def build_window_dots(self):
        box = Gtk.Box(spacing=DOT_SPACING, valign=Gtk.Align.CENTER, homogeneous=True)
        box.add_css_class("dots")
        box.set_margin_start(DOT_LEFT)  # as far from the left edge as from the top
        box.set_margin_end(DOT_GAP)
        box.append(window_dot("dot-close", "Close", "window-close-symbolic", lambda *_: self.close()))
        box.append(window_dot("dot-min", "Minimize", "window-minimize-symbolic", lambda *_: self.minimize()))
        box.append(window_dot(
            "dot-max", "Maximize", "window-maximize-symbolic",
            lambda *_: toggle_maximize(self),
        ))
        return box

    # --- top row: dots, search (full mode only), arrow, menu ---
    def build_header(self):
        header = Adw.HeaderBar()
        header.set_show_title(True)
        header.set_show_start_title_buttons(False)  # we draw our own dots
        header.set_show_end_title_buttons(False)
        header.pack_start(self.build_window_dots())
        # Radio: the last button on the right; the list on the right turns into radio stations.
        self.radio_btn = self.place_item(radio_icon_name(), "Radio", "Online radio",
                                         lambda: self.set_radio_mode(not self.radio_mode))

        # Search lives in the middle and is shown only in full mode.
        self.search_box = Gtk.Box()
        self.search = Gtk.SearchEntry(placeholder_text="Type to search music track")
        self.search.add_css_class("pinkline")
        self.search.set_hexpand(True)
        self.locate_btn = header_button("media-record-symbolic", "Show the track that is playing",
                                        self.show_current_track)  # a circle
        self.near = Gtk.Box(spacing=HEADER_GAP)  # search, circle (and in full mode the buttons) side by side
        self.load_strip = LoadStrip()  # inside the search, on its right: VST3 effects loading
        self.near.append(search_shell(self.search, self.load_strip))
        self.near.append(self.locate_btn)
        self.search_box.append(Adw.Clamp(maximum_size=640, child=self.near, hexpand=True))
        header.set_title_widget(self.search_box)
        self.header = header

        # The right group: video, arrow, menu. In full mode it moves right next to the search
        # (away from the window edge, where some systems put their own window buttons).
        self.right_group = Gtk.Box(spacing=HEADER_GAP, valign=Gtk.Align.CENTER)
        self.video_btn = self.place_item("video-x-generic-symbolic", "Video player", "Open the video player",
                                         lambda: self.get_application().open_video())
        self.back_btn = header_button("go-next-symbolic", None, self.toggle_tracks)  # icon flips in apply_mode()
        self.menu_btn = header_button("open-menu-symbolic")
        # Back to the full track list (shown only in album / artist / genre / playlist).
        self.home_btn = header_button("view-list-symbolic", "Back to all tracks",
                                      lambda *_: self.set_category("track"))
        self.home_btn.set_visible(False)
        # Read the music folder again (after deleting, adding or renaming files).
        self.rescan_btn = header_button("view-refresh-symbolic", "Rescan the music folder",
                                        lambda *_: self.rescan_library())
        self.web_btn = self.place_item("web-browser-symbolic", "Browser", "Browser (opens in its own window)",
                                       lambda: self.set_web_mode(True))
        # Video, radio and browser sit in a small menu behind an arrow, so the header stays calm.
        self.places_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
        for side in ("top", "bottom", "start", "end"):
            getattr(self.places_box, f"set_margin_{side}")(4)
        for btn in (self.video_btn, self.radio_btn, self.web_btn):
            self.places_box.append(btn)
        self.more_btn = header_button("pan-down-symbolic", "Video, radio, browser", self.open_places)
        self.more_btn.add_css_class("more-btn")
        for btn in (self.home_btn, self.rescan_btn, self.back_btn, self.more_btn, self.menu_btn):
            self.right_group.append(btn)
        header.pack_end(self.right_group)
        return header

    def place_item(self, icon, text, tip, action):
        """One line of the video / radio / browser menu: icon and name; it closes the menu."""
        btn = Gtk.Button(tooltip_text=tip)
        btn.add_css_class("flat")
        btn.add_css_class("radio-btn")
        btn.add_css_class("place-item")
        row = Gtk.Box(spacing=10)
        # the pink dot of what is open now, like the library categories in Preferences
        dot = Gtk.Box(valign=Gtk.Align.CENTER)
        dot.add_css_class("cat-dot")
        row.append(dot)
        self.__dict__.setdefault("place_dots", {})[text] = dot
        image = Gtk.Image.new_from_icon_name(icon)
        image.set_pixel_size(18)
        row.append(image)
        row.append(Gtk.Label(label=text, xalign=0))
        btn.set_child(row)

        def clicked(*_):
            pop = getattr(self, "places_pop", None)
            if pop is not None:
                pop.popdown()

            def run():
                # After the menu has closed: opening another window while the menu was still
                # closing (the mouse still over its button) could crash GTK.
                action()
                self.refresh_more_btn()
                return False

            GLib.idle_add(run)

        btn.connect("clicked", clicked)
        return btn

    def open_places(self, *_):
        """The video / radio / browser menu. Made once and kept (it was taken apart after
        every closing; with the window hidden and shown again in between, GTK then crashed
        on a mouse move over a menu that no longer had a window)."""
        pop = getattr(self, "places_pop", None)
        if pop is None:
            pop = Gtk.Popover()
            pop.set_child(self.places_box)
            pop.set_parent(self.more_btn)
            pop.connect("closed", lambda *_: setattr(self, "_places_closed_at", time.monotonic()))
            self.places_pop = pop
        if pop.get_visible():   # the arrow also closes the menu
            pop.popdown()
            return
        if time.monotonic() - getattr(self, "_places_closed_at", 0.0) < 0.25:
            return   # this very click on the arrow has just closed it
        self.refresh_more_btn()   # the dots as things are now (the video window may have closed)
        pop.popup()

    def refresh_more_btn(self):
        """The arrow turns pink while the radio is on screen or the browser window is open;
        in its menu a pink dot marks what is open now (video window, radio, browser)."""
        if getattr(self, "more_btn", None) is None:
            return
        on = self.radio_mode or self.browser_visible
        (self.more_btn.add_css_class if on else self.more_btn.remove_css_class)("more-on")
        app = self.get_application()
        video = getattr(app, "video_window", None) if app is not None else None
        states = {"Video player": video is not None and video.get_visible(),
                  "Radio": self.radio_mode, "Browser": self.browser_visible}
        for text, dot in getattr(self, "place_dots", {}).items():
            (dot.add_css_class if states.get(text) else dot.remove_css_class)("active")

    def place_right_group(self, full):
        parent = self.right_group.get_parent()
        if full and parent is not self.near:
            self.header.remove(self.right_group)
            self.near.append(self.right_group)
        elif not full and parent is self.near:
            self.near.remove(self.right_group)
            self.header.pack_end(self.right_group)
        else:
            return
        # The menu button just moved to a new place: attach its Preferences popover again.
        # Newer GTK (Ubuntu) keeps a popover tied to the old place, and it then silently
        # refuses to open; older GTK (Zorin) forgives this.
        pop = getattr(self, "prefs_popover", None)
        if pop is not None:
            pop.popdown()
            pop.unparent()
            pop.set_parent(self.menu_btn)
        # The same for the video / radio / browser menu (made again the next time it opens).
        places = getattr(self, "places_pop", None)
        if places is not None:
            places.popdown()
            places.set_child(None)
            places.unparent()
            self.places_pop = None

    def close_popovers(self):
        """Every menu of this window closed (before the window is hidden for a moment)."""
        for name in ("places_pop", "prefs_popover"):
            pop = getattr(self, name, None)
            if pop is not None:
                try:
                    pop.popdown()
                except Exception:
                    pass

